//! The owning controller task. Holds the transport, `SessionManager`,
//! discovery, and `ControllerState`. Processes [`Command`]s; while any
//! subscription is active it also listens for unsolicited reports.

use std::collections::{HashMap, VecDeque};
use std::net::{IpAddr, SocketAddr};
use std::sync::Arc;
use std::time::{Duration, Instant};

use matter_commissioning::driver::AsyncDatagram;
use matter_commissioning::NocRng;
use matter_transport::{
    DecodeInboundOutput, Discovery, MessageCounter, MrpEvent, MrpFlags, ProtocolHeader, ProtocolId,
    QueryHandle, ServiceKind, SessionId, SessionManager, SessionRole,
};
use tokio::sync::{mpsc, oneshot};

use crate::error::Error;
use crate::fabric::FabricConfig;
use crate::snapshot;
use crate::state::ControllerState;
use crate::store::ControllerStore;
use crate::subscription::{AttributeReport, SubscriptionEvent, SUBSCRIPTION_CHANNEL_CAP};

/// IM opcodes used by the subscription flow.
const OP_SUBSCRIBE_REQUEST: u8 = 0x03;
const OP_SUBSCRIBE_RESPONSE: u8 = 0x04;
const OP_REPORT_DATA: u8 = 0x05;
const OP_STATUS_RESPONSE: u8 = 0x01;
const OP_TIMED_REQUEST: u8 = 0x0a;
/// IM `WriteRequest` opcode — used by the chunked-write primitive.
const OP_WRITE_REQUEST: u8 = 0x06;
/// IM `WriteResponse` opcode — the device's per-chunk reply to a
/// `WriteRequest` in the chunked-write primitive. A device that rejects a
/// chunk outright (e.g. Busy) replies with a message-level `StatusResponse`
/// (opcode [`OP_STATUS_RESPONSE`]) instead — `resolve_chunked_write` checks
/// the opcode explicitly rather than assuming every reply is a `WriteResponse`.
const OP_WRITE_RESPONSE: u8 = 0x07;
/// IM status `NEEDS_TIMED_INTERACTION` — a device returns this when a write/invoke
/// that requires a timed interaction arrives without a preceding `TimedRequest`.
/// Triggers the transparent timed retry (see [`response_needs_timed`]).
const NEEDS_TIMED_INTERACTION: u8 = 0xc6;
/// IM status `INVALID_ACTION` (Matter 1.4 §8.10). Answers a message on a
/// subscribe exchange that ends the attempt (chip's `ReadClient` error exit),
/// and a steady-state report that cannot be read.
const IM_STATUS_INVALID_ACTION: u8 = 0x80;
/// IM status `INVALID_SUBSCRIPTION` (Matter 1.4 §8.10). Answers a report for a
/// subscription this controller does not hold (or no longer wants), so the
/// device drops it at once (Matter 1.4 §8.5).
const IM_STATUS_INVALID_SUBSCRIPTION: u8 = 0x7d;

/// `true` if a plain (non-timed) write/invoke response signals the device
/// requires a *timed* interaction (`NEEDS_TIMED_INTERACTION`, 0xc6).
///
/// A device may signal this two ways, and real hardware uses both:
/// * as a **message-level** `StatusResponse` (0xc6), or
/// * as a **per-command** `CommandStatusIB` inside an `InvokeResponse`, or a
///   **per-attribute** `AttributeStatusIB` inside a `WriteResponse`.
///
/// Only the first form was handled originally, so timed-required commands failed
/// against shipping devices that use the second — notably door locks (e.g. the
/// eufy E31, which returns 0xc6 as an `InvokeResponse` command status). Chip and
/// the Apple/Google controllers accept both forms, so handling both is required
/// for real-world interop. `opcode` is the original request opcode
/// (`OP_INVOKE_REQUEST` / `OP_WRITE_REQUEST`), used to select the response parser.
fn response_needs_timed(opcode: u8, payload: &[u8]) -> bool {
    // Message-level StatusResponse.
    if matches!(
        matter_interaction::parse_status_response(payload),
        Ok(Some(NEEDS_TIMED_INTERACTION))
    ) {
        return true;
    }
    // Per-command / per-attribute status embedded in the response body.
    match opcode {
        crate::node::OP_INVOKE_REQUEST => matches!(
            matter_interaction::parse_invoke_response_batch(payload),
            Ok(entries) if entries.iter().any(|e| matches!(
                e.response,
                matter_interaction::InvokeResponse::Status(s)
                    if s.to_u8() == NEEDS_TIMED_INTERACTION
            ))
        ),
        OP_WRITE_REQUEST => matches!(
            matter_interaction::parse_write_response(payload),
            Ok(statuses)
                if statuses.iter().any(|(_, s)| s.to_u8() == NEEDS_TIMED_INTERACTION)
        ),
        _ => false,
    }
}

/// How often the loop wakes while at least one operational resolve is parked.
///
/// mDNS results arrive by *polling* ([`Actor::drive_pending_resolves`] drains
/// [`Discovery::poll_results`]), not on a stored deadline, so this is the only
/// remaining periodic component of the actor's park while `pending_resolves` is
/// non-empty, and for [`REQUERY_FAST_DRAIN`] after a watch re-query. While
/// only the resubscribe watch holds the subtype browse the slower
/// [`ADVERT_WATCH_POLL_INTERVAL`] applies otherwise. Every other timer
/// source contributes a real deadline through [`Actor::next_timer_deadline`].
///
/// [`Discovery::poll_results`]: matter_transport::Discovery::poll_results
const RESOLVE_POLL_INTERVAL: std::time::Duration = std::time::Duration::from_millis(250);

/// Default bound on how long an operational request waits for its Interaction
/// Model response before failing with [`Error::ResponseTimeout`].
///
/// MRP bounds delivery, not response: the moment a peer ACKs a request its
/// retransmit entry is dropped, so a device that accepts a request and never
/// answers leaves nothing at the exchange layer to expire. This is the
/// independent application-level bound that makes such an op fail instead of
/// hang.
///
/// 30 s matches the commissioning driver's `RESPONSE_DEADLINE`, which guards
/// the same shape of hang on the BLE/PASE path. Override per controller with
/// [`MatterControllerBuilder::response_deadline`][crate::MatterControllerBuilder::response_deadline].
pub(crate) const DEFAULT_RESPONSE_DEADLINE: std::time::Duration =
    std::time::Duration::from_secs(30);

/// How many consecutive `recv_from` errors the loop absorbs at full speed
/// before it starts backing off.
///
/// A socket surfaces isolated, recoverable errors as a matter of course — a
/// signal interrupting the syscall (`EINTR`), a spurious wakeup (`EWOULDBLOCK`),
/// or a queued ICMP error (`ECONNREFUSED`; that one reaches only a *connected*
/// UDP socket, which our `TokioUdpTransport` is not, but an out-of-tree
/// `AsyncDatagram` may well be) — and a blip must NOT cost the loop anything.
/// Only a *run* of errors, with no successful receive in between, suggests a
/// wedged transport rather than a blip, so the first few are free.
///
/// The run must also be close together in *time*: see [`RECV_ERROR_DECAY`],
/// which clears the counter after a quiet gap so the free budget is genuinely
/// restored rather than being a once-per-process allowance.
const RECV_ERROR_FREE_RETRIES: u32 = 8;

/// First backoff step (milliseconds) applied once [`RECV_ERROR_FREE_RETRIES`]
/// consecutive `recv_from` errors have gone by; it doubles per further
/// consecutive error, capped at [`RECV_ERROR_BACKOFF_MAX_MS`].
const RECV_ERROR_BACKOFF_MIN_MS: u64 = 1;

/// Ceiling (milliseconds) on the recv backoff.
///
/// Chosen below the ~300 ms floor of an MRP retransmit interval, so even a
/// permanently-erroring transport cannot suppress the recv arm long enough to
/// swallow a whole retransmit window for the datagrams that *do* arrive. It
/// bounds a wedged transport to ~5 wakeups per second — versus the ~75 000 per
/// second (~447 000 in 6 s) measured when the loop discarded the error and
/// immediately re-polled.
const RECV_ERROR_BACKOFF_MAX_MS: u64 = 200;

/// Quiet gap after which a run of `recv_from` errors is considered over, so the
/// consecutive counter (and the escalation state in [`RecvWarnStage`]) decays
/// back to zero.
///
/// Without this, `consecutive_recv_errors` would only ever be cleared by a
/// *successful* receive, and a controller whose only peer is offline — one
/// error per MRP retransmit, no intervening `Ok` for minutes — would march to
/// [`RECV_ERROR_BACKOFF_MAX_MS`] and stay pinned there for the life of the
/// process, delaying the first datagram from a returning device by up to that
/// cap. With the decay, the "an isolated blip costs nothing" property of
/// [`RECV_ERROR_FREE_RETRIES`] holds for every blip, not just the first few of a
/// process's life.
///
/// Deliberately LARGER than [`RECV_ERROR_BACKOFF_MAX_MS`]: at saturation the
/// backoff itself spaces polls ~200 ms apart, so a decay window at (or below)
/// the cap would be tripped by the backoff's own pacing and hand a permanently
/// wedged transport its free retries back on every cycle — re-opening a slow
/// version of the spin. Twice the cap leaves a comfortable margin over that
/// pacing while still being far shorter than any interval at which a healthy
/// controller sees repeated errors.
const RECV_ERROR_DECAY: std::time::Duration =
    std::time::Duration::from_millis(2 * RECV_ERROR_BACKOFF_MAX_MS);

/// Whether a `recv_from` error means the transport itself is gone, so the actor
/// should shut down rather than keep polling a socket that will never deliver.
///
/// Deliberately a SHORT list: everything not named here is treated as transient,
/// because killing a live controller over an error we failed to anticipate is
/// far worse than backing off on it (which [`Actor::run`] does, bounding the
/// cost of a permanently-transient error to
/// [`RECV_ERROR_BACKOFF_MAX_MS`]).
///
/// - [`std::io::ErrorKind::BrokenPipe`] — the endpoint's peer half is gone for
///   good. This is what [`matter_commissioning::driver::InMemoryDatagram`]
///   returns once its paired endpoint drops, and it is the case that spun.
/// - [`std::io::ErrorKind::NotConnected`] — `ENOTCONN`: the descriptor is no
///   longer a usable socket. No amount of retrying recovers it.
///
/// Everything else — `ConnectionRefused`, `ConnectionReset`, `Interrupted`
/// (`EINTR`), `WouldBlock`, `TimedOut`, `HostUnreachable`/`NetworkUnreachable`,
/// and any kind added by a future std — is transient. Only the two kinds above
/// are named, and both have been stable since Rust 1.0, so nothing here depends
/// on a variant newer than the 1.88 MSRV.
///
/// This split is part of the [`AsyncDatagram`] contract, not a private
/// heuristic: an out-of-tree transport that reports a *recoverable* gap as
/// `BrokenPipe` stops the controller for good. It is documented as such on
/// `AsyncDatagram::recv_from`.
///
/// [`AsyncDatagram`]: matter_commissioning::driver::AsyncDatagram
fn recv_error_is_terminal(kind: std::io::ErrorKind) -> bool {
    matches!(
        kind,
        std::io::ErrorKind::BrokenPipe | std::io::ErrorKind::NotConnected
    )
}

/// How long the recv arm stays suppressed after `consecutive` back-to-back
/// `recv_from` errors, or `None` while still inside the free-retry budget.
///
/// This is the backstop that makes the loop *incapable* of busy-looping on a
/// transport whose errors are transient-classified but recur forever: the delay
/// doubles from [`RECV_ERROR_BACKOFF_MIN_MS`] and saturates at
/// [`RECV_ERROR_BACKOFF_MAX_MS`], so a permanently-erroring transport settles at
/// a handful of wakeups per second. The suppression is expressed as a deadline
/// the loop parks on (not a `sleep` inside the arm), so commands, timers and MRP
/// keep running at full speed while it is in effect.
fn recv_error_backoff(consecutive: u32) -> Option<std::time::Duration> {
    let step = consecutive.saturating_sub(RECV_ERROR_FREE_RETRIES);
    if step == 0 {
        return None;
    }
    // `min(63)` keeps the shift in range; `unwrap_or` covers the (unreachable)
    // overflow return of `checked_shl` without an `unwrap`.
    let shift = (step - 1).min(63);
    let ms = RECV_ERROR_BACKOFF_MIN_MS
        .checked_shl(shift)
        .unwrap_or(u64::MAX)
        .min(RECV_ERROR_BACKOFF_MAX_MS);
    Some(std::time::Duration::from_millis(ms))
}

/// How far the current run of transient `recv_from` errors has already been
/// escalated to `warn`.
///
/// A transient error is logged at `debug`, which is right for the blip it
/// usually is — but a transport that fails EVERY receive is also "transient" by
/// the classification above, and it leaves the controller permanently deaf:
/// every read, write, subscribe and connect fails with a timeout while the
/// actor is alive and polling a handful of times a second. At the default
/// `info`/`warn` filter, nothing would ever say why. So the loop escalates to
/// `warn` on the *edges* of that condition — never per error, or a wedged
/// transport would become a log flood in its own right.
///
/// The stage only ever rises within a run; it is reset by a successful receive
/// and by [`RECV_ERROR_DECAY`], so a *later* wedge warns again.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord)]
enum RecvWarnStage {
    /// Nothing warned for this run: either there is no run, or it is still
    /// inside the [`RECV_ERROR_FREE_RETRIES`] budget.
    #[default]
    Quiet,
    /// The run crossed [`RECV_ERROR_FREE_RETRIES`], so the receive arm is now
    /// being backed off — the first point at which "this is not a blip" is
    /// knowable.
    BackingOff,
    /// The backoff has reached [`RECV_ERROR_BACKOFF_MAX_MS`]: the transport has
    /// failed every receive across the whole ramp and looks wedged for good.
    Saturated,
}

/// The escalation stage implied by the backoff `recv_error_backoff` just
/// returned: `None` (still free) is [`RecvWarnStage::Quiet`], a capped backoff
/// is [`RecvWarnStage::Saturated`], anything in between is
/// [`RecvWarnStage::BackingOff`].
fn recv_error_warn_stage(backoff: Option<std::time::Duration>) -> RecvWarnStage {
    match backoff {
        None => RecvWarnStage::Quiet,
        Some(d) if d >= std::time::Duration::from_millis(RECV_ERROR_BACKOFF_MAX_MS) => {
            RecvWarnStage::Saturated
        }
        Some(_) => RecvWarnStage::BackingOff,
    }
}

/// Whether an error arriving at `now`, with the previous one at `prev`, starts a
/// NEW run — i.e. whether the quiet gap between them exceeded
/// [`RECV_ERROR_DECAY`], so the consecutive counter must decay to zero first.
///
/// `None` (no previous error, the state after every successful receive) is not a
/// broken run: there is nothing to decay.
fn recv_error_run_broken(prev: Option<Instant>, now: Instant) -> bool {
    prev.is_some_and(|prev| now.saturating_duration_since(prev) > RECV_ERROR_DECAY)
}

/// Backstop park duration when no timer work is scheduled at all. Timer
/// deadlines are recomputed after every loop iteration, so this only bounds
/// how long an unforeseen, unenumerated deadline source could stall; the
/// five known sources (MRP, liveness, resubscribe, resolve polling, recv
/// backoff) all flow through [`Actor::next_timer_deadline`].
const IDLE_PARK_MAX: std::time::Duration = std::time::Duration::from_secs(3600);

/// How long a parked operational resolve ([`Actor::park_resolve`]) waits for its
/// device's mDNS record before its waiters are failed. Matches the budget the
/// old inline resolve spent (`RESOLVE_POLL_ATTEMPTS` × 100 ms in
/// `matter_commissioning::driver`), which is of the same order as chip's
/// session-establishment discovery budget. The wait now costs the actor nothing
/// — it is one entry polled on the [`RESOLVE_POLL_INTERVAL`] arm, not a blocked
/// loop.
#[cfg(not(test))]
const RESOLVE_DEADLINE: std::time::Duration = std::time::Duration::from_secs(30);
/// Shortened under `cfg(test)` so `actor_stays_live_while_resolve_pends` can
/// observe the expiry without 30 s of wall clock. Only the in-crate unit tests
/// see this; integration tests link the lib without `cfg(test)` and get 30 s.
#[cfg(test)]
const RESOLVE_DEADLINE: std::time::Duration = std::time::Duration::from_secs(2);

/// How long the compressed-fabric subtype browse runs **alone** before the
/// base-type `_matter._tcp` browse is opened behind it as a fallback.
///
/// The two must not run concurrently from the start. The underlying defect
/// (keepsimple1/mdns-sd#493) is that the resolver completes per-instance
/// SRV/address resolution roughly one instance per query cycle, from a queue
/// shared by every open browse. The subtype helps *only* because it limits how
/// many instances enter that queue — 3 instead of 18 on the reporter's network.
/// Opening the base type alongside it re-discovers all 18 and puts our nodes
/// back at the end of the same slow queue, which is exactly what the first
/// attempt at this fix did: the reporter's log shows the subtype browse
/// surfacing *nothing* in 30 s, every record credited to the base browse.
///
/// Two seconds is chosen from both ends: long enough that a healthy subtype
/// responder always answers first (~266 ms on the reporter's network, ~250 ms on
/// ours — 2 s is ~8x that, and covers a query that has to be retransmitted
/// once), and short enough to be noise against the [`RESOLVE_DEADLINE`] budget,
/// leaving ~28 s of the 30 s for a responder that genuinely publishes no subtype
/// PTR.
///
/// Matches `SUBTYPE_ONLY_WINDOW` in `matter_commissioning::driver`, which
/// applies the same policy to the commissioning-time resolve.
#[cfg(not(test))]
const SUBTYPE_ONLY_WINDOW: std::time::Duration = std::time::Duration::from_secs(2);
/// Shortened under `cfg(test)` for the same reason [`RESOLVE_DEADLINE`] is, and
/// in the same proportion: the in-crate tests run against a 2 s deadline, so a
/// 2 s window would leave a fallback no room to be observed. Still several
/// [`RESOLVE_POLL_INTERVAL`] ticks, so "opened late, not immediately" remains
/// the property under test. Only in-crate unit tests see this; integration tests
/// link the lib without `cfg(test)` and get the real 2 s.
#[cfg(test)]
const SUBTYPE_ONLY_WINDOW: std::time::Duration = std::time::Duration::from_millis(250);

/// How long a drained operational record stays usable in `seen_records`.
///
/// Records must be cached at all because [`Discovery::poll_results`] CONSUMES
/// what it returns while the shared browse stays open: mdns-sd re-flushes its
/// cache only to *newly* opened browses, and otherwise re-emits an instance only
/// on an actual record refresh (its re-query backoff doubles 1 s, 2 s, 4 s … up
/// to an hour). Without the cache, a record drained while nothing was parked for
/// it would be lost, and a resolve parked seconds later for that very much
/// *online* device would sit until [`RESOLVE_DEADLINE`].
///
/// The TTL bounds the other direction: a device that moves address must not be
/// dialled at its old one indefinitely. A minute is far shorter than a Matter
/// operational record's typical TTL and than mdns-sd's own cache retention, so
/// a moved device is re-learned well before this matters.
const SEEN_RECORD_TTL: std::time::Duration = std::time::Duration::from_secs(60);

/// Cap on cached operational records, so a large fabric (or a hostile flood of
/// `_matter._tcp` advertisements) cannot grow `seen_records` without bound. Well
/// above any realistic fabric size; the oldest entry is evicted to make room.
const SEEN_RECORD_CAP: usize = 256;

/// Max `ReportData` chunks a single read may span before aborting (mirrors
/// `matter_commissioning::driver::MAX_READ_CHUNKS`).
const MAX_READ_CHUNKS: usize = 64;
/// Max total decoded payload bytes a single read may accumulate (256 `KiB`).
const MAX_READ_BYTES: usize = 256 * 1024;

/// The Matter group multicast UDP port (Matter Core Spec §4.2.2 — operational
/// and group traffic share port 5540).
const MATTER_GROUP_PORT: u16 = 5540;

/// How many outbound group message counters one durable persist reserves.
///
/// The persisted `outbound_group_counter` holds the reserved **ceiling**, not
/// the last-sent value: every counter below it may be handed out without a
/// further store write. A crash therefore resumes at the ceiling, skipping at
/// most `GROUP_COUNTER_BLOCK - 1` never-sent values but NEVER reusing a sent
/// one (reuse would let an attacker replay an old group message).
///
/// 64 trades a bounded counter-space skip (the space is 2^32) for one fsync per
/// 64 group sends instead of one per send.
///
/// This is chip's design: `src/transport/GroupPeerMessageCounter.cpp` in
/// connectedhomeip persists a ceiling and keeps the live counter in RAM the
/// same way. chip reserves in blocks of 1000; 64 is the more conservative
/// choice (a crash skips fewer counters) and still amortizes the fsync away.
const GROUP_COUNTER_BLOCK: u32 = 64;

/// chip resubscribe backoff constants (`CHIPConfig.h`, verbatim).
const RESUB_MAX_FIBONACCI_STEP_INDEX: u32 = 14;
const RESUB_WAIT_TIME_MULTIPLIER_MS: u64 = 10_000;
const RESUB_MAX_RETRY_WAIT_INTERVAL_MS: u64 = 5_538_000;
const RESUB_MIN_WAIT_PERCENT: u64 = 30;

/// Approximation of chip's `roundTripTimeout`, added to the negotiated max
/// interval to form a subscription's liveness deadline. chip derives it from the
/// session MRP params + `kExpectedIMProcessingTime`; 5 s is a safe, tunable
/// stand-in (too small ⇒ spurious resubscribes).
const LIVENESS_GRACE: std::time::Duration = std::time::Duration::from_secs(5);

/// How long the resubscribe watch waits before retrying a subtype browse that
/// failed to open ([`Actor::reconcile_resubscribe_watch`]). Bounds what a
/// daemon that keeps refusing costs — one attempt and one `debug!` line per
/// interval — while still recovering promptly once it accepts.
const WATCH_OPEN_RETRY: std::time::Duration = std::time::Duration::from_secs(10);

/// How often the loop drains the fabric-subtype browse while the resubscribe
/// watch is all that holds it open (no resolve parked).
///
/// The watch waits for a device to re-announce itself, which takes seconds to
/// minutes, so it does not need [`RESOLVE_POLL_INTERVAL`]'s 250 ms: one wake a
/// second per controller with a subscription waiting costs nothing, and adds
/// at most a second to a recovery that was going to take minutes. For
/// [`REQUERY_FAST_DRAIN`] after each watch re-query the drain runs at
/// [`RESOLVE_POLL_INTERVAL`] instead.
const ADVERT_WATCH_POLL_INTERVAL: std::time::Duration = std::time::Duration::from_secs(1);

/// Minimum time between two **advert-triggered** pulls of one subscription
/// ([`Actor::trigger_resubscribe`]).
///
/// A pull resets the backoff, so a device that re-announces in a burst, or
/// keeps appearing and failing, must not hold its retries at the shortest step
/// forever. 30 s is the default response deadline: a pulled attempt has normally
/// succeeded or failed by then. `resubscribe_now` ignores it (the caller asked)
/// but its pulls still count toward it.
const ADVERT_PULL_COOLDOWN: std::time::Duration = std::time::Duration::from_secs(30);

/// How long after any subtype-browse open its found events are discarded.
///
/// Opening a browse makes the mDNS daemon flush every PTR it already caches to
/// it as found events: those are not devices re-announcing, they are the cache.
/// Judged by when the event is drained (`poll_found` returns it), not when it
/// arrived; at the 250 ms / 1 s drain cadences the difference is immaterial.
/// The cost is that a device returning within this window of an open has its
/// advert discarded and recovers on the backoff.
#[cfg(not(test))]
const ADVERT_QUIET_WINDOW: std::time::Duration = std::time::Duration::from_secs(5);
/// Shortened under `cfg(test)` so the in-crate end-to-end test need not sleep
/// 5 s; unit tests use the constant, never a literal. Integration tests link
/// the lib without `cfg(test)` and get 5 s.
#[cfg(test)]
const ADVERT_QUIET_WINDOW: std::time::Duration = std::time::Duration::from_millis(500);

/// How long after the resubscribe watch starts holding the subtype browse it
/// first re-queries it, and the first step of its re-query cadence
/// ([`Actor::drive_watch_requery`], spec 2026-10-04).
///
/// mdns-sd accepts a response only if it answers one of its active queriers,
/// and re-sends a browse's query on a doubling schedule capped at an hour. A
/// device whose announcement the subtype querier did not take is otherwise
/// seen only at that next scheduled query — up to an hour late (`WeaveHome`
/// field report on 0.16). A fresh query carries known answers (the cached
/// PTRs not past half their TTL), so devices whose fresh PTR the daemon holds
/// stay silent, and a returning device answers with a new PTR: exactly the
/// advert the watch acts on. A live device past that half-life may answer too;
/// its PTR is not new, so it is not an advert.
#[cfg(not(test))]
const ADVERT_REQUERY_FIRST: std::time::Duration = std::time::Duration::from_secs(30);
/// Shortened under `cfg(test)`, keeping production's 1 : 10 ratio to
/// [`ADVERT_REQUERY_MAX`], so the in-crate end-to-end test recovers in
/// seconds; unit tests use the constant, never a literal.
#[cfg(test)]
const ADVERT_REQUERY_FIRST: std::time::Duration = std::time::Duration::from_millis(300);

/// The re-query cadence doubles from [`ADVERT_REQUERY_FIRST`] up to this cap:
/// 30, 60, 120, 240 s apart, then every 300 s (maintainer decision,
/// 2026-10-04). It backs off in the spirit of RFC 6762 §5.2, but stops
/// doubling at 5 min rather than at the 60 min §5.2 sets, because 5 min bounds
/// the controller's own detection of a long outage; an application's own browse
/// calling `resubscribe_now` stays the fast path. Each re-query also restarts
/// the resolver's own 1, 2, 4 … s query chain, so at the cap mdns-sd sends
/// about nine small queries per 5-minute step instead of about one an hour.
#[cfg(not(test))]
const ADVERT_REQUERY_MAX: std::time::Duration = std::time::Duration::from_secs(300);
/// Shortened under `cfg(test)` with [`ADVERT_REQUERY_FIRST`].
#[cfg(test)]
const ADVERT_REQUERY_MAX: std::time::Duration = std::time::Duration::from_secs(3);

/// How long after a watch re-query the subtype browse is drained every
/// [`RESOLVE_POLL_INTERVAL`] instead of every [`ADVERT_WATCH_POLL_INTERVAL`]
/// ([`Actor::drive_pending_resolves`]).
///
/// A re-query makes mdns-sd replay every PTR it caches for the subtype, about
/// `2N + 1` events for `N` cached instances, onto the browse's channel. The
/// daemon does not wait for it to be drained, but the channel holds 1000
/// events, and mdns-sd closes a browse whose channel fills (the transport
/// re-opens it, losing events). Draining every 250 ms keeps that backlog
/// short, and a device answering the restarted chain is acted on within
/// 250 ms rather than up to a second. 15 s spans the restarted query chain's
/// first burst (queries about 0, 1, 3, 7 and 15 s after the re-query), so the
/// answers it draws are drained briskly too, and stays shorter than
/// [`ADVERT_REQUERY_FIRST`], so the watch is back on its 1 s cadence between
/// re-queries.
///
/// Not shortened under `cfg(test)`: the unit tests reach past the window with
/// synthetic instants, and under the shortened re-query cadence the in-crate
/// end-to-end test only drains more often for it, never less.
const REQUERY_FAST_DRAIN: std::time::Duration = std::time::Duration::from_secs(15);

/// chip `GetFibonacciForIndex` (F(0)=0, F(1)=1, F(2)=1, F(3)=2, …).
fn fibonacci(n: u32) -> u64 {
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 0..n {
        let next = a + b;
        a = b;
        b = next;
    }
    a
}

/// chip `ComputeTimeTillNextSubscription(retry_count)`: a Fibonacci-stepped max
/// wait (capped at [`RESUB_MAX_RETRY_WAIT_INTERVAL_MS`]), then a uniform jitter
/// in `[30%, 100%]` of it. `retry_count` 0 yields zero (immediate first retry).
fn resubscribe_backoff(rng: &dyn NocRng, retry_count: u32) -> std::time::Duration {
    let max_wait_ms = if retry_count <= RESUB_MAX_FIBONACCI_STEP_INDEX {
        fibonacci(retry_count).saturating_mul(RESUB_WAIT_TIME_MULTIPLIER_MS)
    } else {
        RESUB_MAX_RETRY_WAIT_INTERVAL_MS
    };
    let min_wait_ms = (RESUB_MIN_WAIT_PERCENT * max_wait_ms) / 100;
    let span = max_wait_ms - min_wait_ms;
    let jitter = if span == 0 {
        0
    } else {
        let mut buf = [0u8; 8];
        // RNG failure is effectively impossible for `SystemNocRng`; fall back to 0.
        let _ = rng.fill(&mut buf);
        u64::from_le_bytes(buf) % span
    };
    std::time::Duration::from_millis(min_wait_ms + jitter)
}

/// Ensure a resubscribe's event filters exclude everything already handed to
/// the consumer: with a delivery watermark `w`, no filter may request events
/// below `w + 1`. Empty caller filters (the only in-tree case — `Node::subscribe`
/// sends none) become a single minimal filter.
fn bump_event_filters(
    mut filters: Vec<matter_interaction::EventFilter>,
    watermark: Option<u64>,
) -> Vec<matter_interaction::EventFilter> {
    let Some(w) = watermark else {
        return filters;
    };
    let min = w.saturating_add(1);
    if filters.is_empty() {
        return vec![matter_interaction::EventFilter::from_event_min(min)];
    }
    for f in &mut filters {
        f.event_min = f.event_min.max(min);
    }
    filters
}

/// Controller-assigned stable subscription handle id. Survives auto-resubscribes
/// (the device's wire `subscription_id` changes on each re-establish, this does
/// not), so the consumer's [`Subscription`] stays valid across a resubscribe.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub(crate) struct SubId(pub(crate) u64);

/// The actor's two senders into one consumer [`Subscription`], plus the
/// per-subscription dropped-report counter.
///
/// Steady-state reports go on a **bounded** channel (`report_tx`,
/// [`SUBSCRIPTION_CHANNEL_CAP`]) and are dropped — never blocked on — when full,
/// so a device that floods reports cannot grow controller memory or stall the
/// actor loop. Control events ([`SubscriptionEvent::Established`] /
/// [`SubscriptionEvent::Resubscribing`]) go on a separate, reliable, low-volume
/// channel (`ctrl_tx`) so they are never dropped by report backpressure.
struct ReportSink {
    /// Bounded report channel (capacity [`SUBSCRIPTION_CHANNEL_CAP`]).
    report_tx: mpsc::Sender<SubscriptionEvent>,
    /// Reliable control-event channel ([`SubscriptionEvent::Established`] /
    /// [`SubscriptionEvent::Resubscribing`]).
    ctrl_tx: mpsc::UnboundedSender<SubscriptionEvent>,
    /// Reports dropped (buffer full) since the last delivered `Lagged`.
    dropped: usize,
    /// Highest event number handed toward the consumer (delivered OR dropped
    /// on a full buffer — a dropped event must not be replayed late either,
    /// so "attempted" is the right semantics for the resubscribe filter).
    max_event_delivered: Option<u64>,
}

impl ReportSink {
    /// Try to forward a steady-state report without ever blocking the actor.
    ///
    /// On a full buffer the report is dropped and counted; the loss is later
    /// surfaced as a single coalesced [`SubscriptionEvent::Lagged`] once capacity
    /// frees. Returns `false` only if the consumer's report receiver is gone
    /// (closed), signalling the subscription should be reaped.
    fn try_send_report(&mut self, report: AttributeReport) -> bool {
        // Flush a pending Lagged first so the consumer learns of prior drops as
        // soon as there is room; if it still doesn't fit, fold this into dropped.
        if self.dropped > 0 {
            match self.report_tx.try_send(SubscriptionEvent::Lagged {
                dropped: self.dropped,
            }) {
                Ok(()) => self.dropped = 0,
                Err(mpsc::error::TrySendError::Closed(_)) => return false,
                Err(mpsc::error::TrySendError::Full(_)) => {}
            }
        }
        match self.report_tx.try_send(SubscriptionEvent::Report(report)) {
            Ok(()) => true,
            // Buffer full: drop this report and count it (coalesced Lagged later).
            Err(mpsc::error::TrySendError::Full(_)) => {
                self.dropped += 1;
                true
            }
            // Consumer gone: reap the subscription.
            Err(mpsc::error::TrySendError::Closed(_)) => false,
        }
    }

    /// Like [`try_send_report`](Self::try_send_report) but for an event report.
    /// Shares the bounded report channel + `Lagged` accounting (events are
    /// report-volume and the device controls their cadence, so they must be
    /// bounded the same way). Returns `false` only if the consumer's report
    /// receiver is gone (closed), signalling the subscription should be reaped.
    fn try_send_event(&mut self, event: matter_interaction::EventReport) -> bool {
        // Watermark tracks *attempted* delivery, including a drop below on a
        // full buffer — see the field doc on `max_event_delivered`. Update
        // this before the send attempt so every code path below sees it.
        if let matter_interaction::EventReport::Data(item) = &event {
            self.max_event_delivered = Some(
                self.max_event_delivered
                    .map_or(item.event_number, |m| m.max(item.event_number)),
            );
        }
        // Flush a pending Lagged first (mirrors try_send_report).
        if self.dropped > 0 {
            match self.report_tx.try_send(SubscriptionEvent::Lagged {
                dropped: self.dropped,
            }) {
                Ok(()) => self.dropped = 0,
                Err(mpsc::error::TrySendError::Closed(_)) => return false,
                Err(mpsc::error::TrySendError::Full(_)) => {}
            }
        }
        match self.report_tx.try_send(SubscriptionEvent::Event(event)) {
            Ok(()) => true,
            // Buffer full: drop this event and count it (coalesced Lagged later).
            Err(mpsc::error::TrySendError::Full(_)) => {
                self.dropped += 1;
                true
            }
            // Consumer gone: reap the subscription.
            Err(mpsc::error::TrySendError::Closed(_)) => false,
        }
    }

    /// Deliver a control event reliably. Returns `false` if the consumer's
    /// control receiver is gone (the subscription should be reaped).
    fn send_control(&self, event: SubscriptionEvent) -> bool {
        self.ctrl_tx.send(event).is_ok()
    }

    /// Whether the consumer dropped BOTH receivers, so nothing can observe this
    /// subscription again. The reap test `attempt_resubscribe` and
    /// `reschedule_resubscribe` apply; an entry like this is reaped the next
    /// time it fires.
    fn consumer_gone(&self) -> bool {
        self.report_tx.is_closed() && self.ctrl_tx.is_closed()
    }
}

/// Per-subscription routing + resubscribe state, keyed by [`SubId`].
struct SubEntry {
    /// Channels to the consumer's [`Subscription`].
    tx: ReportSink,
    /// Operational peer address (for `StatusResponse` acks).
    peer: SocketAddr,
    /// Reassembles a chunked steady-state notification before delivery.
    reassembler: ReportReassembler,
    /// Current device session + wire subscription id (both change on resubscribe).
    session_id: SessionId,
    wire_sub_id: u32,
    /// Subscribe params, retained to re-issue the `SubscribeRequest` on resubscribe.
    node_id: u64,
    paths: Vec<matter_interaction::ReadPath>,
    event_paths: Vec<matter_interaction::EventPath>,
    event_filters: Vec<matter_interaction::EventFilter>,
    min_interval: u16,
    /// The max interval the device NEGOTIATED in its `SubscribeResponse` — its
    /// agreed reporting cadence, which drives the liveness deadline.
    max_interval: u16,
    /// The caller's requested `MaxIntervalCeiling`, re-sent unchanged on every
    /// resubscribe (chip's `ReadClient` re-sends its retained
    /// `ReadPrepareParams`). Never the negotiated value: re-requesting that
    /// would pin every later subscription to whatever the device once chose.
    max_interval_ceiling: u16,
    /// Re-subscribe if no report arrives by this instant.
    liveness_deadline: Instant,
}

/// A steady-state report that cannot be delivered: the subscription id it
/// carried, if any, why (for the log), and the IM status it is answered with.
struct StrayReport {
    subscription_id: Option<u32>,
    reason: &'static str,
    status: u8,
}

/// A scheduled resubscribe attempt, fired by the timer arm when due.
struct PendingResubscribe {
    sub_id: SubId,
    attempt_at: Instant,
    node_id: u64,
    paths: Vec<matter_interaction::ReadPath>,
    event_paths: Vec<matter_interaction::EventPath>,
    event_filters: Vec<matter_interaction::EventFilter>,
    min_interval: u16,
    /// The caller's requested ceiling (`SubEntry::max_interval_ceiling`), not
    /// the value last negotiated.
    max_interval: u16,
    retry_count: u32,
    tx: ReportSink,
}

/// Why one subscribe attempt failed.
///
/// Every failure of an attempt whose `SubscribeRequest` is out — an answer on
/// its exchange that is malformed, a rejection or unexpected, and for a
/// resubscribe either of the two timeouts — goes through
/// [`Actor::fail_subscribe_attempt`] with one of these. An initial subscribe's
/// timeouts keep the reconnect-and-re-send-once path. Failures before the
/// request is out do not come here: a resubscribe whose connect, send or sole
/// fabric lookup fails goes straight to [`Actor::reschedule_resubscribe`], and
/// an initial subscribe whose session or send fails returns that error to the
/// caller. `Display` feeds the resubscribe failure log; for an initial
/// subscribe, [`Self::into_initial_error`] is what the caller gets.
///
/// Replaces 0.16's `PendingTimeoutCause`, which named only the two timeouts.
/// [`Actor::on_pending_timeout`] takes one for every pending kind, as it took
/// `PendingTimeoutCause`; only a subscribe attempt reads it.
#[derive(Debug)]
enum SubscribeFailure {
    /// MRP retransmitted the request its full budget and it was never
    /// acknowledged: the device is unreachable, or no longer holds the session.
    MrpExpired,
    /// The request was acknowledged but no Interaction Model response arrived
    /// within the response deadline.
    ResponseDeadline,
    /// The `SubscribeResponse`, a priming `ReportData`, or a `StatusResponse`
    /// on the exchange did not parse. A `StatusResponse` that is not a bare
    /// status (`parse_status_response` → `Ok(None)`) counts as one.
    Malformed(matter_interaction::ImError),
    /// The device answered with a `StatusResponse` carrying this non-success
    /// IM status (e.g. 0x89 `ResourceExhausted`).
    Rejected(u8),
    /// Any other Interaction Model message on the exchange, carrying this
    /// opcode — including a Success `StatusResponse`, which is no answer to a
    /// `SubscribeRequest` (chip: `CHIP_ERROR_INVALID_MESSAGE_TYPE`).
    UnexpectedMessage(u8),
    /// The device closed the session the attempt ran on, with a Secure
    /// Channel `CloseSession` (Matter 1.4 Core §4.11.1.4).
    SessionClosed,
}

impl SubscribeFailure {
    /// Whether a message on the exchange caused this failure, so it is
    /// answered with `StatusResponse(InvalidAction)` — chip's
    /// `ReadClient::OnMessageReceived` does that on every error exit. A
    /// timeout has nothing to answer.
    fn arrived_on_the_wire(&self) -> bool {
        matches!(
            self,
            Self::Malformed(_) | Self::Rejected(_) | Self::UnexpectedMessage(_)
        )
    }

    /// The error an initial subscribe's caller gets for this failure.
    fn into_initial_error(self) -> Error {
        match self {
            Self::Malformed(e) => Error::InteractionModel(e),
            Self::Rejected(status) => Error::SubscribeRejected(status),
            // The existing precedent: `resolve_chunked_write` reports an
            // unexpected opcode the same way, so no new `ImError` variant.
            Self::UnexpectedMessage(opcode) => Error::Operational(format!(
                "unexpected message to a subscribe request: opcode 0x{opcode:02x}"
            )),
            // Not reached: an initial subscribe's timeouts keep their own paths
            // (MRP expiry reconnects and re-sends once, the response deadline
            // fails it with `ResponseTimeout`) and never come here.
            Self::MrpExpired => Error::Operational(Self::MrpExpired.to_string()),
            Self::ResponseDeadline => Error::Operational(Self::ResponseDeadline.to_string()),
            // Not reached: `on_peer_close_session` re-sends an initial
            // subscribe once through `on_pending_timeout`'s reconnect path and
            // fails a retried one directly.
            Self::SessionClosed => Error::Operational(Self::SessionClosed.to_string()),
        }
    }
}

impl std::fmt::Display for SubscribeFailure {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::MrpExpired => {
                f.write_str("MRP retransmissions exhausted: the request was never acknowledged")
            }
            Self::ResponseDeadline => f.write_str(
                "response deadline elapsed: the request was acknowledged but never answered",
            ),
            Self::SessionClosed => f.write_str("the device closed the session (CloseSession)"),
            Self::Malformed(e) => write!(f, "malformed response: {e}"),
            Self::Rejected(status) => write!(f, "rejected by the device: IM status 0x{status:02x}"),
            Self::UnexpectedMessage(opcode) => write!(
                f,
                "unexpected message on the subscribe exchange: opcode 0x{opcode:02x}"
            ),
        }
    }
}

/// What asked [`Actor::trigger_resubscribe`] to pull resubscribes forward.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum TriggerSource {
    /// The resubscribe watch saw the node publish a new operational PTR record.
    /// Subject to [`ADVERT_PULL_COOLDOWN`].
    Advert,
    /// `MatterController::resubscribe_now`. Not throttled: the caller asked.
    Api,
}

/// An in-flight request awaiting its response, keyed in `pending` by
/// `(session, exchange)`. The actor owns recv centrally, so a round-trip/read
/// cannot block on its own response — it registers one of these and the central
/// [`Actor::handle_inbound`] resolves it.
struct Pending {
    /// Node this op targets, for the reconnect-once retry on timeout.
    node_id: u64,
    /// Peer the request was sent to.
    peer: SocketAddr,
    /// When to give up waiting for the Interaction Model response.
    ///
    /// MRP bounds *delivery*, not *response*: once the peer ACKs the request
    /// the retransmit entry is dropped, so a device that accepts a request and
    /// never answers it leaves `MrpEvent::Expired` unable to fire and this op
    /// waiting forever (issue #113's sibling, #119 — reproduced on a Tapo H100
    /// bridge, which silently drops the 9th consecutive read on a session).
    /// This deadline is the independent application-level bound.
    response_deadline: Instant,
    /// The request bytes, retained to re-send once after a transparent
    /// reconnect when the cached session was stale.
    request: PendingRequest,
    /// Has this op already been retried once after a reconnect?
    retried: bool,
    /// Our message counter for the most recent reliable message sent on this
    /// op's exchange: the request, a timed action, a write chunk, or a
    /// `StatusResponse` asking for the next read chunk or answering a priming
    /// report. `None` while none is recorded (an op parked for a reconnect).
    ///
    /// [`Self::drive_mrp`](Actor::drive_mrp) treats an `MrpEvent::Expired` as
    /// this op's own only when its counter is this one. The event names the
    /// exchange by id alone, and a device may start its own exchange with the
    /// same id (Matter 1.4 Core §4.10.2); the expiry of one of our reliable
    /// answers there must not take this op's reconnect-and-re-send path,
    /// which would re-send a request the device already received. Our counter
    /// names exactly one message in the session, so it names the exchange and
    /// its role. MRP keeps at most one reliable message in flight per
    /// exchange, so the latest is the only one that can expire. A send site
    /// that forgot to record its counter fails safe: the op's real expiry is
    /// ignored and the op is handled at its `response_deadline` under the
    /// deadline policy instead ([`Actor::drive_response_deadlines`]: a read is
    /// re-sent once, a resubscribe rescheduled, anything else failed), which
    /// never re-sends a request the device may have executed.
    last_reliable_send: Option<MessageCounter>,
    /// Where the resolved result is delivered.
    reply: PendingReply,
}

/// The original request, kept so a timed-out op on a stale cached session can be
/// re-sent once on a freshly re-established session.
struct PendingRequest {
    opcode: u8,
    protocol_id: ProtocolId,
    payload: Vec<u8>,
}

/// Reply ownership follows an action through queues, reconnects and timed fallback.
pub(crate) struct ActionReply {
    tx: oneshot::Sender<Result<Vec<u8>, Error>>,
    deadline: Option<std::time::Instant>,
}
impl From<oneshot::Sender<Result<Vec<u8>, Error>>> for ActionReply {
    fn from(tx: oneshot::Sender<Result<Vec<u8>, Error>>) -> Self {
        Self { tx, deadline: None }
    }
}
impl ActionReply {
    pub(crate) fn before(
        tx: oneshot::Sender<Result<Vec<u8>, Error>>,
        deadline: std::time::Instant,
    ) -> Self {
        Self {
            tx,
            deadline: Some(deadline),
        }
    }
    fn stopped(&self) -> bool {
        self.tx.is_closed()
            || self
                .deadline
                .is_some_and(|d| std::time::Instant::now() >= d)
    }
    async fn until_stopped<T>(
        &mut self,
        send: impl std::future::Future<Output = Result<T, Error>>,
    ) -> Result<T, Error> {
        if self.stopped() {
            return Err(Error::Operational(
                "action deadline elapsed or caller dropped".into(),
            ));
        }
        let deadline = self.deadline;
        tokio::select! {
            biased;
            () = self.tx.closed() => Err(Error::Operational("action caller dropped".into())),
            () = async {
                match deadline {
                    Some(d) => tokio::time::sleep_until(tokio::time::Instant::from_std(d)).await,
                    None => std::future::pending().await,
                }
            } => Err(Error::Operational("action deadline elapsed".into())),
            result = send => result,
        }
    }
    fn send(self, value: Result<Vec<u8>, Error>) -> Result<(), Result<Vec<u8>, Error>> {
        self.tx.send(value)
    }
}
impl PendingReply {
    fn action_reply_mut(&mut self) -> Option<&mut ActionReply> {
        match self {
            Self::Action { reply, .. }
            | Self::TimedAction { reply, .. }
            | Self::RoundTrip(reply) => Some(reply),
            _ => None,
        }
    }
    fn action_stopped(&self) -> bool {
        match self {
            Self::Action { reply, .. }
            | Self::TimedAction { reply, .. }
            | Self::RoundTrip(reply) => reply.stopped(),
            _ => false,
        }
    }
}

/// Where a resolved pending op delivers its result.
enum PendingReply {
    /// Single request/response (`Node::round_trip`).
    RoundTrip(ActionReply),
    /// Timed handshake: a `TimedRequest` is in flight. On `StatusResponse(SUCCESS)`
    /// the actor sends `action_payload` (opcode `action_opcode`) on the SAME
    /// exchange and converts this pending into a [`RoundTrip`](Self::RoundTrip)
    /// awaiting the action's response, which resolves `reply`.
    TimedAction {
        action_opcode: u8,
        action_payload: Vec<u8>,
        reply: ActionReply,
    },
    /// A plain write/invoke awaiting its response. On a `NEEDS_TIMED_INTERACTION`
    /// rejection the actor records `keys` in the learned timed-cache and retries
    /// the action timed (invoking `timed_payload`, which encodes the timed
    /// variant only at that point); otherwise it resolves `reply` with the
    /// response bytes and the unused closure is dropped. (See
    /// [`Actor::resolve_action`].)
    Action {
        opcode: u8,
        timed_payload: TimedPayload,
        keys: Vec<(u32, u32)>,
        timeout_ms: u16,
        node_id: u64,
        reply: ActionReply,
    },
    /// Chunked write: ONE `WriteRequest` chunk is in flight at a time on this
    /// exchange (chip's `WriteClient`: exactly one outstanding reliable
    /// message per exchange — Matter §8.7.4 / §10.6). `remaining` holds the
    /// chunks not yet sent, in order; `statuses` accumulates every chunk's
    /// parsed per-path statuses as they arrive.
    ///
    /// chip's `WriteClient` does NOT abort on a non-Success element status —
    /// it forwards every status to its callback and unconditionally sends the
    /// next chunk (`WriteClient.cpp:583-593`). So each `WriteResponse` (opcode
    /// [`OP_WRITE_RESPONSE`]) is parsed, its statuses appended to `statuses`,
    /// and — if `remaining` is non-empty — the next chunk is sent on the SAME
    /// exchange regardless of what those statuses were; the final chunk's
    /// `WriteResponse` (`remaining` empty) resolves `reply` with the FULL
    /// accumulated `statuses`.
    ///
    /// This is terminal (drops `remaining`, resolves `reply` with an `Err`)
    /// on: a malformed `WriteResponse` (parse failure — chip only aborts on a
    /// malformed response, not a bad element status); a message that is not a
    /// `WriteResponse` at all (a device that rejects a chunk outright — e.g.
    /// Busy 0x9C — replies with a message-level `StatusResponse` instead,
    /// which chip's `WriteHandler` sends via `StatusResponse::Send` then
    /// `Close`; parsing that as a `WriteResponse` would misread it as
    /// `Ok(vec![])`, a vacuous "all Success"); a send failure for the next
    /// chunk; or a pending timeout.
    ChunkedWrite {
        reply: oneshot::Sender<
            Result<
                Vec<(
                    matter_interaction::AttributePath,
                    matter_interaction::ImStatus,
                )>,
                Error,
            >,
        >,
        /// Chunks not yet sent, in order; popped from the front as each
        /// preceding chunk's `WriteResponse` arrives.
        remaining: VecDeque<Vec<u8>>,
        /// Per-path statuses accumulated across every chunk's `WriteResponse`
        /// so far, in arrival order.
        statuses: Vec<(
            matter_interaction::AttributePath,
            matter_interaction::ImStatus,
        )>,
    },
    /// Chunked read: accumulate parsed `ReportData` chunks; resolve on the
    /// final chunk. Each chunk is parsed exactly once here (in the actor's
    /// receive path) and handed to `Node::read` already decoded, so the read
    /// path does not walk the TLV a second time.
    Read {
        reply: oneshot::Sender<Result<Vec<matter_interaction::ReportData>, Error>>,
        chunks: Vec<matter_interaction::ReportData>,
        total_bytes: usize,
    },
    /// Subscribe handshake: buffer/ack priming reports until `SubscribeResponse`.
    /// `reply`/`report_rx` are `Some` for an initial subscribe and `None` for a
    /// resubscribe attempt (the consumer keeps its existing receiver).
    Subscribe {
        sub_id: SubId,
        reply: Option<oneshot::Sender<Result<SubEstablished, Error>>>,
        report_tx: ReportSink,
        /// The consumer's receivers, handed back on the initial `Established`.
        /// `None` for a resubscribe (the consumer keeps its existing receivers).
        report_rx: Option<SubReceivers>,
        // Boxed to keep the `Command` enum compact: the reassembler embeds a
        // `ReportAccumulator` (HashMaps + size-cap bookkeeping) that would
        // otherwise dominate every other variant's footprint.
        priming: Box<ReportReassembler>,
        node_id: u64,
        paths: Vec<matter_interaction::ReadPath>,
        event_paths: Vec<matter_interaction::EventPath>,
        event_filters: Vec<matter_interaction::EventFilter>,
        min_interval: u16,
        /// The requested `MaxIntervalCeiling` — the caller's, on an initial
        /// subscribe and on every resubscribe alike.
        max_interval: u16,
        retry_count: u32,
    },
}

/// The consumer-side receivers for one subscription: the bounded report channel
/// and the reliable control-event channel.
pub(crate) struct SubReceivers {
    /// Bounded report receiver (capacity [`SUBSCRIPTION_CHANNEL_CAP`]).
    pub(crate) report_rx: mpsc::Receiver<SubscriptionEvent>,
    /// Reliable control-event receiver.
    pub(crate) ctrl_rx: mpsc::UnboundedReceiver<SubscriptionEvent>,
}

/// What `handle_subscribe` returns to `Node::subscribe`: the report receivers
/// and the `(session, subscription_id)` key (the `Node` adds the command sender
/// to build the public [`Subscription`]).
pub(crate) type SubEstablished = (SubReceivers, SubId);

/// Maximum non-final chunks a single subscription notification may span before
/// [`ReportReassembler`] drops the partial accumulation. Bounds memory against a
/// device that streams `MoreChunkedMessages=true` without ever finalising; far
/// above any conformant notification (a handful of chunks at most).
const MAX_SUB_CHUNKS: usize = 64;

/// Accumulates a chunked `ReportData` *sequence* (one logical notification) and
/// yields the merged attributes only when the final chunk arrives
/// (`MoreChunkedMessages` clear). A single-message report flushes immediately.
/// This is the streaming-subscription analogue of the read path's per-call
/// [`ReportAccumulator`](matter_interaction::ReportAccumulator) use: it merges
/// `Replace`/`Append` (`ListIndex`=null) items across a notification's chunks
/// before delivery, so list attributes and list-appends are not lost.
///
/// LIMITATION: there is no on-the-wire marker for a notification boundary, so a
/// chunked sequence whose final chunk never arrives (a device that dies
/// mid-notification) leaves a partial accumulation that would merge into the
/// *next* notification's flush. The [`MAX_SUB_CHUNKS`] cap bounds the memory of
/// such a runaway sequence; the stale-merge window itself is closed by the
/// liveness tracking + auto-resubscribe (an abandoned notification means
/// no complete report within `max_interval`, so liveness fires and we
/// re-subscribe to a fresh priming snapshot). Conformant devices do not start a
/// new notification before the prior chunked sequence completes, so this
/// requires non-conformant behaviour.
#[derive(Default)]
struct ReportReassembler {
    acc: matter_interaction::ReportAccumulator,
    /// Non-final chunks accumulated since the last flush.
    pending_chunks: usize,
}

impl ReportReassembler {
    /// Push one already-parsed `ReportData` chunk. Returns `Some(merged
    /// attributes)` when this chunk is the final one
    /// (`more_chunked_messages == false`), resetting for the next notification;
    /// returns `None` while more chunks are pending, the chunk cap was
    /// exceeded, or the accumulator's in-crate total-size ceiling was exceeded
    /// (partial dropped in all three cases).
    ///
    /// This is the single-parse entry point: the caller (`deliver_report` /
    /// the priming path) parses the inbound datagram exactly once and hands the
    /// struct in by value, so the steady-state subscription hot path does not
    /// walk the TLV twice.
    fn push_parsed(
        &mut self,
        rd: matter_interaction::ReportData,
    ) -> Option<Vec<(matter_interaction::AttributePath, matter_codec::Value)>> {
        let more = rd.more_chunked_messages;
        if self.acc.push(rd).is_err() {
            // The accumulator's total-size ceiling was hit (a peer streaming an
            // unbounded report set). Drop the partial — same posture as the
            // chunk-count cap below — and wait for liveness/resubscribe to
            // recover a clean snapshot.
            self.acc = matter_interaction::ReportAccumulator::default();
            self.pending_chunks = 0;
            return None;
        }
        if !more {
            self.pending_chunks = 0;
            return Some(std::mem::take(&mut self.acc).finish());
        }
        self.pending_chunks += 1;
        if self.pending_chunks > MAX_SUB_CHUNKS {
            // Runaway non-finalising sequence — drop the partial to bound memory.
            self.acc = matter_interaction::ReportAccumulator::default();
            self.pending_chunks = 0;
        }
        None
    }

    /// Parse one `ReportData` chunk payload and merge it via [`push_parsed`]. A
    /// malformed chunk is dropped (prior accumulation kept). Retained for tests
    /// that exercise the reassembler from raw bytes.
    ///
    /// [`push_parsed`]: ReportReassembler::push_parsed
    #[cfg(test)]
    fn push(
        &mut self,
        payload: &[u8],
    ) -> Option<Vec<(matter_interaction::AttributePath, matter_codec::Value)>> {
        // Drop a malformed chunk; keep prior accumulation.
        let rd = matter_interaction::parse_report_data(payload).ok()?;
        self.push_parsed(rd)
    }
}

/// Lazily-built timed-variant payload for a write/invoke `Action`. The plain
/// payload is pre-encoded (it is always sent, except on a known-timed path);
/// the timed variant is built only when the device actually demands a timed
/// interaction (`NEEDS_TIMED_INTERACTION` escalation or learned-timed cache
/// hit) — the rare path. The common case drops this closure unused, so the
/// timed encode never runs.
pub(crate) type TimedPayload = Box<dyn FnOnce() -> Vec<u8> + Send>;

/// Messages the handles send to the owning task. Each carries a `oneshot`
/// reply sender; a dropped reply sender means the caller gave up.
pub(crate) enum Command {
    CreateFabric {
        cfg: FabricConfig,
        reply: oneshot::Sender<Result<u64, Error>>,
    },
    /// Raw secured IM round-trip to `node_id`. A generic primitive retained for
    /// tests that exercise the actor's connect/cache/demux without IM payloads;
    /// the production verbs use `Read`/`Action`/`Subscribe`/`TimedRoundTrip`.
    #[cfg(test)]
    RoundTrip {
        node_id: u64,
        opcode: u8,
        protocol_id: matter_transport::ProtocolId,
        payload: Vec<u8>,
        reply: ActionReply,
    },
    /// Chunked secured read to `node_id` — returns every `ReportData` chunk
    /// already parsed, in order (the `Node` reassembles them via
    /// `ReportAccumulator`). Each chunk is TLV-parsed exactly once, inside the
    /// actor's receive path. Used by `Node::read`; a non-chunked read yields a
    /// single-element `Vec`.
    Read {
        node_id: u64,
        payload: Vec<u8>,
        reply: oneshot::Sender<Result<Vec<matter_interaction::ReportData>, Error>>,
    },
    /// Commission a device from a parsed setup payload; returns the resulting
    /// [`NodeInfo`](crate::NodeInfo) (with `vendor_id`/`product_id` left `None`
    /// — the controller fills those best-effort via a `BasicInformation` read
    /// after this reply resolves).  `label` is an opaque caller-supplied string
    /// persisted on the resulting `DeviceEntry` (set atomically with the rest
    /// of the entry, so it can never observably land only on a later save).
    Commission {
        setup_payload: matter_commissioning::SetupPayload,
        label: Option<String>,
        reply: oneshot::Sender<Result<crate::NodeInfo, Error>>,
    },
    /// Commission a device over BLE/BTP from a parsed setup payload and required
    /// network (Wi-Fi or Thread) credentials; returns the resulting
    /// [`NodeInfo`](crate::NodeInfo) (feature `ble`). Runs on its own spawned
    /// task exactly like [`Command::Commission`], but the task first scans BLE,
    /// opens a BTP session, and drives `commission_ble`. `label` is the same
    /// opaque caller-supplied string as [`Command::Commission`]'s.
    #[cfg(feature = "ble")]
    CommissionBle {
        setup_payload: matter_commissioning::SetupPayload,
        network: matter_commissioning::NetworkCredentials,
        label: Option<String>,
        reply: oneshot::Sender<Result<crate::NodeInfo, Error>>,
    },
    /// Persist `vendor_id`/`product_id` (from a post-commission `BasicInformation`
    /// read) onto the commissioned device `node_id`'s entry. Best-effort: a
    /// missing device is a no-op success. Used only by the commission
    /// orchestration, which has already reported success — this just enriches
    /// the stored metadata.
    SetNodeVidPid {
        node_id: u64,
        vendor_id: Option<u16>,
        product_id: Option<u16>,
        reply: oneshot::Sender<Result<(), Error>>,
    },
    /// Establish a subscription to `paths` on `node_id`; returns the report
    /// receiver + `(session, exchange)` key for the `Node` to wrap.
    Subscribe {
        node_id: u64,
        paths: Vec<matter_interaction::ReadPath>,
        event_paths: Vec<matter_interaction::EventPath>,
        event_filters: Vec<matter_interaction::EventFilter>,
        min_interval: u16,
        max_interval: u16,
        reply: oneshot::Sender<Result<SubEstablished, Error>>,
    },
    /// A write/invoke that auto-handles timed interactions: if any `keys`
    /// `(cluster, id)` is in the learned timed-cache, go straight to a timed
    /// interaction; otherwise send `plain_payload`, and on a
    /// `NEEDS_TIMED_INTERACTION (0xc6)` rejection record the `keys` and transparently
    /// retry with `timed_payload` (built lazily, only on those two paths).
    /// Returns the final response bytes. (Explicit timed is
    /// [`Command::TimedRoundTrip`] via `write_timed`/`invoke_timed`.)
    Action {
        node_id: u64,
        opcode: u8, // OP_WRITE_REQUEST | OP_INVOKE_REQUEST
        plain_payload: Vec<u8>,
        timed_payload: TimedPayload,
        keys: Vec<(u32, u32)>,
        timeout_ms: u16,
        reply: ActionReply,
    },
    /// Timed round-trip: send a `TimedRequest`, await `StatusResponse(SUCCESS)`,
    /// then send `action_opcode`/`action_payload` on the SAME exchange and return
    /// its response bytes. Used by `Node::write_timed`/`invoke_timed` and the
    /// timed-escalation path of [`Command::Action`].
    TimedRoundTrip {
        node_id: u64,
        timeout_ms: u16,
        action_opcode: u8,
        action_payload: Vec<u8>,
        reply: ActionReply,
    },
    /// Send a chunked write as N `WriteRequestMessage`s on ONE exchange, ONE
    /// chunk in flight at a time — chip's `WriteClient` allows exactly one
    /// outstanding reliable message per exchange, gating each chunk on the
    /// device's `WriteResponse` to the previous one (see
    /// `Actor::handle_chunked_write` / `Actor::resolve_chunked_write`). All
    /// but the last chunk carry `MoreChunkedMessages=true`; every chunk is
    /// sent reliably (MRP). The device replies with a `WriteResponse` to
    /// EVERY chunk; every chunk's statuses are accumulated and the next chunk
    /// is sent UNCONDITIONALLY (chip's `WriteClient` pumps every chunk
    /// regardless of individual element statuses — it does not abort on a
    /// non-Success status). Terminal failure (no further chunks, `reply`
    /// resolves `Err`) happens only on a malformed `WriteResponse`, a
    /// non-`WriteResponse` reply (e.g. the device rejecting a chunk with a
    /// `StatusResponse`), a send failure, or a timeout. A single
    /// [`PendingReply::ChunkedWrite`] occupies `(session, exchange)` at any
    /// time — inserted after the first chunk, re-inserted after each
    /// subsequent chunk — and resolves with the FULL accumulated per-path
    /// status list on success.
    ChunkedWrite {
        node_id: u64,
        chunks: Vec<Vec<u8>>,
        reply: oneshot::Sender<
            Result<
                Vec<(
                    matter_interaction::AttributePath,
                    matter_interaction::ImStatus,
                )>,
                Error,
            >,
        >,
    },
    /// Return the actor's stored commissioner node id (the sole fabric's
    /// `commissioner.node_id`). Used by the ACL lockout guard, which must avoid
    /// writing an ACL that would lock the commissioner itself out.
    CommissionerNodeId {
        reply: oneshot::Sender<Result<u64, Error>>,
    },
    /// Enumerate all commissioned nodes across every fabric as typed
    /// [`NodeInfo`](crate::NodeInfo) — the snapshot-decoupled accessor.
    ListNodes {
        reply: oneshot::Sender<Vec<crate::NodeInfo>>,
    },
    /// Enumerate every fabric this controller has created as typed
    /// [`FabricInfo`](crate::FabricInfo) — the snapshot-decoupled accessor.
    /// Lets a caller check which `fabric_id`s already exist before calling
    /// [`Command::CreateFabric`] (issue #110).
    ListFabrics {
        reply: oneshot::Sender<Result<Vec<crate::FabricInfo>, Error>>,
    },
    /// Drop ALL of the controller's own local state for `node_id` — the
    /// persisted `DeviceEntry`, its cached CASE session, and any parked
    /// connect bookkeeping — WITHOUT contacting the device. A local-state
    /// verb like [`Command::ListNodes`]/[`Command::SetNodeVidPid`]: handled
    /// only in [`Actor::dispatch_ready`], never routed through
    /// `command_target_node` (routing it as a node-addressed verb would try
    /// to open a CASE session to a node we are trying to forget, which may
    /// be unreachable or already reset). `reply` carries whether a device
    /// was actually found and removed.
    ForgetNode {
        node_id: u64,
        reply: oneshot::Sender<Result<bool, Error>>,
    },
    /// Return the sole fabric's stored CASE resumption record bytes for
    /// `node_id` (serialized [`matter_crypto::ResumptionRecord`], see
    /// [`crate::resumption`]), or `None` if the device has none. Read from the
    /// actor's live in-memory state — not the store — so a record written by a
    /// connect that JUST completed (e.g. the `serve_ota` announce) is visible
    /// without racing the offloaded persist.
    ///
    /// Returns the parsed record rather than the stored bytes: the
    /// commissioner-identity check that decides whether it may be used at all
    /// is only possible on the actor, which owns the fabric state.
    #[cfg(any(feature = "ota", test))]
    ResumptionRecordFor {
        node_id: u64,
        reply: oneshot::Sender<Result<Option<matter_crypto::ResumptionRecord>, Error>>,
    },
    /// Store `record` as the sole fabric's CASE resumption record for
    /// `node_id` (best-effort persist). Invoked from `serve_ota` via the provider
    /// server's `record_sink`, once per completed CASE accept.
    ///
    /// Carries the record itself rather than pre-serialized bytes: the
    /// commissioner-identity fingerprint stamped alongside it is only knowable
    /// on the actor, which owns the fabric state.
    #[cfg(feature = "ota")]
    StoreResumptionRecord {
        node_id: u64,
        // Boxed: a `ResumptionRecord` embeds a full `MatterCertificate`, and an
        // inline copy would make every `Command` that large.
        record: Box<matter_crypto::ResumptionRecord>,
        reply: oneshot::Sender<Result<(), Error>>,
    },
    /// Drop every cached CASE resumption record on `fabric_id` and durably
    /// save. See
    /// [`MatterController::invalidate_resumption_records`](crate::MatterController::invalidate_resumption_records).
    InvalidateResumptionRecords {
        fabric_id: u64,
        reply: oneshot::Sender<Result<usize, Error>>,
    },
    /// Persist an ICD client registration on the sole fabric (replacing any
    /// prior registration for the same node), then durably save. Used by
    /// `Node::register_icd_client` after a successful `RegisterClient`.
    PersistIcdRegistration {
        registration: crate::icd::IcdRegistration,
        reply: oneshot::Sender<Result<(), Error>>,
    },
    /// Mint a fresh 16-byte group epoch key, append a
    /// [`GroupKeySetConfig`](crate::state::GroupKeySetConfig) to
    /// the sole fabric's `group_keys`, durably persist, and return the
    /// corresponding [`GroupKeySet`](crate::GroupKeySet) so the caller can
    /// program it onto devices via `Node::write_group_key_set`.
    CreateGroup {
        key_set_id: u16,
        epoch_start_time: u64,
        reply: oneshot::Sender<Result<crate::GroupKeySet, Error>>,
    },
    /// Fire-and-forget multicast group invoke. The actor derives the operational
    /// group key + session id from the persisted `key_set_id`, takes the next
    /// outbound group counter from a **durably reserved block** (extending and
    /// persisting the reservation BEFORE sending when the block runs out),
    /// encodes a group-secured `InvokeRequest`, and multicasts it. No pending is
    /// registered and no response is awaited (group sends are unacknowledged).
    InvokeGroup {
        group_id: u16,
        key_set_id: u16,
        path: matter_interaction::CommandPath,
        fields_tlv: Vec<u8>,
        reply: oneshot::Sender<Result<(), Error>>,
    },
    /// Cancel the subscription identified by its `(session, subscription_id)` key.
    CancelSubscription { key: SubId },
    /// Pull every resubscribe episode of `node_id` forward: a scheduled retry
    /// fires now with its backoff reset, one in progress keeps running with its
    /// backoff reset. Replies with how many subscriptions were affected. See
    /// [`MatterController::resubscribe_now`](crate::MatterController::resubscribe_now).
    /// A local-state verb: `command_target_node` returns `None` for it (its `_`
    /// arm, as for `CancelSubscription`), so it never starts a connect itself.
    ResubscribeNow {
        node_id: u64,
        reply: oneshot::Sender<usize>,
    },
    /// Test/diagnostic: how many live cached sessions exist.
    #[cfg(test)]
    SessionCount { reply: oneshot::Sender<usize> },
    /// Test-only: set the retry count and next attempt time (`now +
    /// attempt_in`) of every QUEUED resubscribe of `node_id`, replying with how
    /// many were changed. Lets an end-to-end test put a subscription deep into
    /// its backoff without waiting the real minutes.
    #[cfg(test)]
    SetResubscribeSchedule {
        node_id: u64,
        retry_count: u32,
        attempt_in: Duration,
        reply: oneshot::Sender<usize>,
    },
}

/// A cached operational session to one device.
struct CachedSession {
    session_id: SessionId,
    peer: std::net::SocketAddr,
}

/// A serialized snapshot plus its ordering sequence.
///
/// Fully owned (no borrow of the actor): the actor is non-`Sync`, so anything
/// held across an `.await` — or moved into `spawn_blocking` — must own its
/// inputs, else the actor future is non-`Send` and unspawnable.
///
/// Saves are applied in **sequence order**, not in whichever order the blocking
/// pool happens to schedule them. Without this, a *detached* best-effort save
/// (see [`Actor::persist_best_effort`]) that was serialized first but
/// descheduled could win the store's atomic `rename` over a later durable save
/// and silently roll persisted state backwards. A job whose `seq` is older than
/// the last-written snapshot is therefore skipped.
struct SaveJob {
    store: Arc<dyn ControllerStore>,
    bytes: Vec<u8>,
    /// Serialize-time sequence from [`Actor::snapshot_seq`] (monotonic).
    seq: u64,
    /// Last-written sequence, shared by every save path of one actor. A `std`
    /// mutex, not a Tokio one, because it is only ever locked inside
    /// `spawn_blocking` — never on an async task, so it cannot block a runtime
    /// worker holding it across an await point.
    gate: Arc<std::sync::Mutex<u64>>,
}

impl SaveJob {
    /// Write the snapshot, unless a newer one already landed.
    ///
    /// Runs on the blocking pool. The gate lock is held across the store's
    /// write+fsync+rename deliberately: serializing writers *is* the ordering
    /// guarantee — releasing it earlier would let two renames interleave and
    /// leave the older bytes on disk. A stale job returns `Ok(())`: skipping is
    /// the intended outcome, not a failure.
    ///
    /// ## Why `Ok(())` on skip is sound for DURABLE saves
    ///
    /// A durable caller (`durable_save_inputs` + [`save_offloaded`]) treats
    /// `Ok(())` as "my state is on disk", so a skip must never lose a
    /// durability-critical write. Two things make that hold:
    ///
    /// 1. Durable saves are **serialized on the actor loop** — every one of them
    ///    is awaited inside a `select!` *arm body*, which runs to completion and
    ///    is never a cancellable branch future. No other save of this actor can
    ///    be serialized between a durable job's serialize and its write, so a
    ///    durable job is never actually skipped in today's code.
    /// 2. Even if one were, the snapshot is **whole-state**: a newer snapshot
    ///    already contains everything the skipped one did (sequences advance
    ///    monotonically from the same actor state), so "a newer write landed
    ///    first" and "my write landed" are indistinguishable on disk.
    ///
    /// NEW CALLERS MUST NOT issue durable saves from spawned tasks without
    /// revisiting this: off-loop saves can interleave with the loop's own, and
    /// point 1 — the property that makes the skip trivially unobservable — would
    /// no longer hold.
    ///
    /// A poisoned gate (a previous job panicked mid-save) is recovered rather
    /// than propagated: the protected value is a plain `u64` that a panic
    /// cannot leave in a torn state, and refusing every subsequent save would
    /// be strictly worse than continuing to order them.
    fn run(self) -> Result<(), crate::store::StoreError> {
        let mut last = match self.gate.lock() {
            Ok(guard) => guard,
            Err(poisoned) => poisoned.into_inner(),
        };
        if self.seq < *last {
            return Ok(());
        }
        self.store.save(&self.bytes)?;
        *last = self.seq;
        Ok(())
    }
}

/// Await a [`SaveJob`] on the Tokio blocking pool.
///
/// Free function (owns its inputs) so the actor never holds a `&self` borrow
/// across the `.await`: that would make the actor future non-`Send` and so
/// unspawnable. A panic inside `save` surfaces as a `JoinError`, mapped to an
/// operational persistence error rather than unwinding the actor loop.
async fn save_offloaded(job: SaveJob) -> Result<(), Error> {
    match tokio::task::spawn_blocking(move || job.run()).await {
        Ok(saved) => Ok(saved?),
        Err(join_err) => Err(Error::Operational(format!(
            "persistence task failed: {join_err}"
        ))),
    }
}

/// Owns all mutable state. Generic over transport + discovery so tests can
/// inject `InMemoryDatagram` + a mock `Discovery`.
pub(crate) struct Actor<T: AsyncDatagram, D: Discovery> {
    transport: T,
    discovery: D,
    sessions: SessionManager,
    /// Standalone ACKs a deliberate session release took before removing the
    /// session ([`Self::release_session`]), with the address each goes to,
    /// waiting for [`Self::send_queued_acks`] at the top of the next loop turn
    /// (or the channel-close flush).
    queued_acks: Vec<(SocketAddr, Vec<u8>)>,
    store: Arc<dyn ControllerStore>,
    rng: Arc<dyn NocRng>,
    state: ControllerState,
    cache: HashMap<(u64, u64), CachedSession>, // (fabric_id, node_id) -> session
    /// Attestation trust, `Arc`-wrapped so it can be cheaply shared into the
    /// spawned commission task (which runs off the actor loop — see
    /// [`Self::spawn_commission`]) without cloning the cert stores.
    trust: Option<Arc<crate::trust::AttestationTrust>>,
    admin_vendor_id: u16,
    /// Active subscriptions, keyed by the stable [`SubId`]. Each entry tracks its
    /// current device `(session, wire_sub_id)`; steady-state `ReportData` is
    /// routed by matching those (see [`Self::deliver_report`]).
    subscriptions: HashMap<SubId, SubEntry>,
    /// Secondary index over `subscriptions`: the device-facing identity
    /// `(session, wire subscription id)` → our stable [`SubId`]. Maintained
    /// exclusively by [`Self::insert_subscription`]/[`Self::remove_subscription`]
    /// so `deliver_report` resolves a steady-state report in O(1) instead of
    /// scanning every subscription per report.
    sub_index: HashMap<(SessionId, u32), SubId>,
    /// In-flight round-trips/reads/subscribe-handshakes, keyed by
    /// `(session, exchange)`. Resolved by [`Self::handle_inbound`], or failed
    /// by [`Self::drive_response_deadlines`] if the device never answers.
    ///
    /// Every entry is an exchange WE started (its id comes from
    /// `encode_outbound(.., None, ..)` in [`Self::send_request`]), so the key
    /// leaves out the role: only a message with the `I` flag clear can belong
    /// to one, and every send or flush on a pending exchange names it as ours.
    pending: HashMap<(SessionId, u16), Pending>,
    /// How long an operational request may wait for its response before
    /// [`Self::drive_response_deadlines`] fails it. See
    /// [`DEFAULT_RESPONSE_DEADLINE`].
    response_deadline: std::time::Duration,
    /// Monotonic source of stable [`SubId`]s.
    next_sub_id: u64,
    /// Monotonic snapshot sequence, bumped on every serialize. Stamped onto the
    /// resulting [`SaveJob`] so saves are applied in serialize order.
    snapshot_seq: u64,
    /// Sequence of the last snapshot actually written, shared by every save
    /// path (durable and best-effort) so they order against each other. See
    /// [`SaveJob::run`].
    save_gate: Arc<std::sync::Mutex<u64>>,
    /// Scheduled resubscribe attempts (fired from the timer arm when due).
    resubscribes: Vec<PendingResubscribe>,
    /// When each subscription was last pulled forward by
    /// [`Self::trigger_resubscribe`], for [`ADVERT_PULL_COOLDOWN`].
    ///
    /// Kept here rather than on [`PendingResubscribe`] because
    /// [`Self::on_pending_timeout`] rebuilds a `PendingResubscribe` from a
    /// `PendingReply::Subscribe`, which would drop a per-entry field. Pruned
    /// wherever a subscription leaves its resubscribe episode — established
    /// (`resolve_subscribe`), cancelled, forgotten, or reaped
    /// (`begin_resubscribe`, `attempt_resubscribe`, `reschedule_resubscribe`) —
    /// so it never outlives the episodes it describes.
    resubscribe_pulled_at: HashMap<SubId, Instant>,
    /// Learned set of `(cluster_id, attr_or_command_id)` paths the device has
    /// rejected with `NEEDS_TIMED_INTERACTION` — a write/invoke to one of these
    /// skips the (wasted) plain attempt and goes straight to a timed interaction.
    /// Populated on a `0xc6` rejection; covers manufacturer/ungenerated clusters
    /// and survives for the controller's lifetime.
    timed_paths: std::collections::HashSet<(u32, u32)>,
    /// Sender half of the spawned-commission completions channel: cloned into
    /// each [`Self::spawn_commission`] task.
    commission_tx: mpsc::Sender<CommissionCompletion>,
    /// Receiver half, drained by an arm of the [`Self::run`] `select!`.
    commission_rx: mpsc::Receiver<CommissionCompletion>,
    /// Event-driven connect: work waiting on an in-flight CASE connect,
    /// coalesced per device node id. A key's presence means a connect to that
    /// node is running on a spawned task; the queued [`ConnectWaiter`]s are
    /// resumed (on success) or resolved/rescheduled (on error) when it
    /// completes. See [`Self::enqueue_connect_waiter`] /
    /// [`Self::handle_connect_done`].
    pending_connects: HashMap<u64, Vec<ConnectWaiter>>,
    /// Peer MRP config (from the operational mDNS `SII`/`SAI`/`SAT`) captured
    /// when a connect is spawned, applied to the session at
    /// [`Self::handle_connect_done`] so retransmits are sized to the peer, not
    /// our defaults. Keyed by node id; removed when the connect
    /// completes or the node is forgotten.
    connect_mrp: HashMap<u64, matter_transport::MrpConfig>,
    /// Operational resolves waiting on mDNS, polled from the timer arm by
    /// [`Self::drive_pending_resolves`]. A connect whose record is not already
    /// known parks here instead of blocking the loop on a poll loop; at most one
    /// entry per node (`pending_connects` coalesces concurrent connects).
    pending_resolves: Vec<PendingResolve>,
    /// When the next drain of the operational browses is due.
    ///
    /// mDNS results arrive by *polling*, so unlike every other timer source the
    /// drain tick has no naturally-occurring deadline — but it must still be an
    /// ABSOLUTE instant rather than a `now + interval` computed per iteration:
    /// any other `select!` arm that fires more often than the interval (a busy
    /// device, or a transport whose `recv_from` returns errors back-to-back)
    /// would otherwise push a relative tick forward forever and starve
    /// discovery. Advanced by [`Self::drive_pending_resolves`], which picks the
    /// interval: [`RESOLVE_POLL_INTERVAL`] while a resolve is parked, and for
    /// [`REQUERY_FAST_DRAIN`] after a watch re-query
    /// (`requery_fast_drain_until`); [`ADVERT_WATCH_POLL_INTERVAL`] while only
    /// the resubscribe watch holds the subtype browse. Consulted only in those
    /// two states.
    next_resolve_poll: Instant,
    /// Consecutive `recv_from` errors in the current run.
    ///
    /// Reset to zero by every `Ok` from the transport, and by a quiet gap of
    /// more than [`RECV_ERROR_DECAY`] between two errors (see
    /// [`recv_error_run_broken`] — without that decay the counter would only
    /// ever rise across the life of a controller whose peer is simply offline).
    /// It exists to size [`recv_error_backoff`], which is what stops a transport
    /// that errors forever from spinning the loop.
    consecutive_recv_errors: u32,
    /// When the most recent `recv_from` error arrived, or `None` if the last
    /// receive succeeded. Only used to age out a run of errors
    /// ([`RECV_ERROR_DECAY`]).
    last_recv_error_at: Option<Instant>,
    /// Which edge-triggered `warn!` about the current run of transient errors has
    /// already fired, so a permanently wedged transport is visible at default log
    /// levels without emitting a line per failed receive. See [`RecvWarnStage`].
    recv_warn_stage: RecvWarnStage,
    /// While `Some`, the `select!`'s recv arm is disabled until this instant —
    /// the backoff imposed after [`RECV_ERROR_FREE_RETRIES`] consecutive
    /// `recv_from` errors.
    ///
    /// Held as a deadline rather than a `sleep` inside the arm so a wedged
    /// transport never delays commands, MRP or subscription liveness: it is one
    /// more component of [`Self::next_timer_deadline`], and it is cleared at the
    /// top of every [`Self::run`] iteration once it has elapsed (an
    /// already-passed value here would make the loop's overdue-timer guard fire
    /// on every pass — the very spin this whole mechanism exists to prevent).
    recv_backoff_until: Option<Instant>,
    /// The ONE `_matter._tcp` browse shared by every parked resolve — the
    /// **delayed fallback**, opened only once the subtype browse has run for
    /// [`SUBTYPE_ONLY_WINDOW`] without settling anything (see
    /// [`Self::resolve_base_after`]), and stopped when the last entry leaves.
    ///
    /// It must be shared: [`Discovery::stop_query`] stops the daemon-side browse
    /// for the whole [`ServiceKind`], so per-resolve handles would cancel each
    /// other's browse as they completed. One handle also means one
    /// [`Discovery::poll_results`] drain per tick serving all entries.
    resolve_query: Option<QueryHandle>,
    /// The ONE compressed-fabric **subtype** browse
    /// (`_I<compressed-fabric-id>._sub._matter._tcp`,
    /// [`Discovery::query_operational_fabric`]) shared by every parked resolve.
    /// This is the browse a resolve normally opens and settles on; it is opened
    /// the moment the first entry parks, always through
    /// [`Self::open_subtype_browse`]. It is also the **resubscribe watch**:
    /// while any subscription is waiting to be re-established
    /// ([`Self::resubscribe_watch_needed`]) it is kept open after the last
    /// resolve settles, so a device that re-announces itself is seen.
    ///
    /// The subtype is the fast, reliable one: it narrows the browse to our own
    /// fabric, so a resolver that completes SRV/address resolution one discovered
    /// instance per query cycle (mdns-sd does) reaches our node at once instead
    /// of possibly never — issue #113. That narrowing is the entire fix, which is
    /// why the base type is NOT opened next to it; see [`SUBTYPE_ONLY_WINDOW`].
    ///
    /// May equal `resolve_query` when the injected [`Discovery`] does not
    /// override `query_operational_fabric` (the trait default opens a base-type
    /// browse); the poll path deduplicates equal handles.
    resolve_query_fabric: Option<QueryHandle>,
    /// When the base-type fallback browse becomes due, while it is still to be
    /// opened. `Some(deadline)` means: a subtype browse is running, no parked
    /// resolve has settled off it yet, and [`Self::drive_pending_resolves`] must
    /// open [`Self::resolve_query`] once `Instant::now()` reaches `deadline`.
    ///
    /// `None` means there is nothing to do — either no resolve is parked, or the
    /// base browse is already open, or it was opened up front because the subtype
    /// browse could not be opened at all.
    ///
    /// Holding a deadline (rather than spawning a timer or a task) is what keeps
    /// the delayed open on the existing poll arm: the loop already wakes every
    /// [`RESOLVE_POLL_INTERVAL`] while resolves are parked, so the fallback opens
    /// within one tick of becoming due and the actor gains no new timer source.
    resolve_base_after: Option<Instant>,
    /// The compressed fabric id the held subtype browse (`resolve_query_fabric`)
    /// was opened for, recorded by [`Self::open_subtype_browse`]. `None` when no
    /// subtype browse is held, or once [`Self::reconcile_resubscribe_watch`]
    /// found the sole fabric no longer matches it: found events from such a
    /// handle are never counted as adverts.
    resolve_query_fabric_cfid: Option<[u8; 8]>,
    /// When the resubscribe watch may next retry a subtype browse that failed to
    /// open; `None` when no retry is pending. See [`WATCH_OPEN_RETRY`].
    watch_open_retry_at: Option<Instant>,
    /// Found events drained from the subtype browse before this instant are
    /// discarded ([`ADVERT_QUIET_WINDOW`]); set at every subtype open, by
    /// whichever opener, and cleared when it closes.
    advert_quiet_until: Option<Instant>,
    /// When the resubscribe watch next re-queries the subtype browse
    /// ([`Self::drive_watch_requery`]). `None` while the watch has no schedule:
    /// no browse held, no subscription waiting, or a handle `spawn_connect`
    /// opened that the watch has not adopted yet. Cleared by
    /// [`Self::close_subtype_browse`] and whenever no subscription waits (even
    /// if a parked resolve keeps the browse), so every episode starts at
    /// [`ADVERT_REQUERY_FIRST`].
    watch_requery_at: Option<Instant>,
    /// The cadence step `watch_requery_at` was scheduled with; the next step is
    /// double this, capped at [`ADVERT_REQUERY_MAX`].
    watch_requery_interval: Duration,
    /// The nodes in a resubscribe episode as of the previous
    /// [`Self::drive_watch_requery`] pass, sorted and deduplicated
    /// ([`Self::resubscribe_episode_nodes`]). Refreshed on every such pass —
    /// every timer pass while the watch is needed and the subtype browse is
    /// held — not only when a re-query goes out. A node missing from it has
    /// just been lost, and restarts the cadence at its first step.
    watch_episode_nodes: Vec<u64>,
    /// End of the fast-drain window a watch re-query opens: set to
    /// [`REQUERY_FAST_DRAIN`] after the re-query, and until then every
    /// [`Self::drive_pending_resolves`] pass re-arms the drain tick at
    /// [`RESOLVE_POLL_INTERVAL`] instead of [`ADVERT_WATCH_POLL_INTERVAL`].
    /// mdns-sd replays its cache for the
    /// re-issued browse onto a channel that holds 1000 events, so the replay
    /// is drained briskly ([`REQUERY_FAST_DRAIN`]). A deadline rather
    /// than an earlier `next_resolve_poll`: reconcile runs just before
    /// `drive_pending_resolves`, which re-arms the tick first thing and would
    /// overwrite it in the same pass. Left in place once passed (it is inert
    /// then); `None` when no re-query has run since the subtype browse was
    /// opened, and cleared by [`Self::close_subtype_browse`].
    requery_fast_drain_until: Option<Instant>,
    /// Operational records drained from that browse, keyed by ASCII-lowercased
    /// instance name. A drain consumes what it returns, so every record is
    /// cached — not just the ones a resolve is parked for right now — or a
    /// record that arrived before its resolve did would be lost. Bounded by
    /// [`SEEN_RECORD_CAP`], aged out by [`SEEN_RECORD_TTL`].
    seen_records: HashMap<String, SeenRecord>,
    /// IPv6 multicast egress interface for group sends (destination scope
    /// id). Set via `MatterControllerBuilder::multicast_interface`; `None`
    /// falls back to the `MATTER_MULTICAST_IF` env var, then kernel default.
    multicast_if: Option<u32>,
    /// Live next outbound group message counter per fabric id.
    ///
    /// **Never serialized.** The persisted
    /// [`FabricEntry::outbound_group_counter`](crate::state::FabricEntry) holds
    /// the reserved *ceiling* instead; this map hands out the values below it
    /// without touching the store, and initializes from the ceiling on restart
    /// (see [`GROUP_COUNTER_BLOCK`] and [`Self::handle_invoke_group`]).
    ///
    /// Entries are never removed because fabrics are never removed from
    /// `state.fabrics` locally — `Node::remove_fabric` removes *us* from a
    /// device's fabric table, and `forget_node` drops a device, not a fabric.
    /// If a local fabric-removal path is ever added it MUST drop the matching
    /// entry, or a re-created fabric with the same id would restart mid-block
    /// against a fresh (zero) persisted ceiling.
    group_counters: HashMap<u64, u32>,
    /// Derived group key material per fabric id, so a burst of group sends
    /// costs one set of HKDFs instead of four per packet
    /// ([`Self::handle_invoke_group`]).
    ///
    /// Same lifecycle note as `group_counters`: entries are never removed
    /// because fabrics are never removed locally. A future local
    /// fabric-removal path SHOULD still drop the matching entry: correctness
    /// does not depend on it (a re-created fabric changes either its epoch key
    /// or its RCAC public key, and [`Self::group_keys_for`] compares both), but
    /// leaving it keeps derived key material alive for a fabric that is gone.
    group_key_cache: HashMap<u64, GroupKeyCacheEntry>,
    /// Per-in-flight-connect inbound queue (keyed by node id): the actor forwards
    /// the device's unsecured handshake replies here for the spawned task to
    /// consume via its [`HandshakeSocket`](crate::handshake_socket::HandshakeSocket).
    connect_inbound: HashMap<u64, mpsc::Sender<(Vec<u8>, SocketAddr)>>,
    /// Peer-address → node-id route for in-flight handshakes. An inbound
    /// unsecured datagram from a mapped peer is a handshake reply and is
    /// forwarded to that connect. Installed when the actor sends the connect's
    /// first datagram, so it is always in place before any reply arrives.
    connect_routes: HashMap<SocketAddr, u64>,
    /// Shared outbound channel: spawned connect tasks push their handshake
    /// datagrams here; the actor sends each on its own socket (and installs the
    /// peer route). Kept on the actor so `recv` never closes.
    connect_outbound_tx: mpsc::Sender<crate::handshake_socket::HandshakeOutbound>,
    /// Receiver half, drained by an arm of the [`Self::run`] `select!`.
    connect_outbound_rx: mpsc::Receiver<crate::handshake_socket::HandshakeOutbound>,
    /// Connect-completion channel: a finished connect task hands its established
    /// session (or error) back here for registration + waiter resolution.
    connect_done_tx: mpsc::Sender<ConnectCompletion>,
    /// Receiver half, drained by an arm of the [`Self::run`] `select!`.
    connect_done_rx: mpsc::Receiver<ConnectCompletion>,
    /// Test hook: the cause passed to every [`Self::reschedule_resubscribe`],
    /// with its subscription, so tests can assert on the value each call site
    /// passes without capturing logs.
    #[cfg(test)]
    reschedule_causes: Vec<(SubId, String)>,
    /// Test hook: the size of the resubscribe episode set at the top of every
    /// [`Self::attempt_resubscribe`], so a test can prove the entries not yet
    /// attempted stay visible during a `drive_resubscribes` pass.
    #[cfg(test)]
    episode_sizes_at_attempt: Vec<usize>,
}

/// Derived group-key material for a fabric, computed once per
/// `(epoch_key, root_public_key)` pair.
///
/// Every value below is a pure function of `(epoch_key, root_public_key,
/// fabric_id)`. `fabric_id` is the map key, and the other two are **both**
/// stamped on the entry and compared on every use
/// ([`Actor::group_keys_for`]), which makes that pair the complete
/// invalidation condition. A key rotation (`create_group` / `KeySetWrite`)
/// changes the epoch key; a fabric that is ever removed and re-created under
/// the same id would change the RCAC public key. Either one forces
/// re-derivation, so an entry can never outlive the inputs it was derived
/// from — including under a future local fabric-removal path, which does not
/// exist today.
///
/// Deliberately keyed by fabric id alone, not by `(fabric_id, key_set_id)`:
/// nothing derived here depends on the key set id — it only selects WHICH
/// epoch key the caller passes in. Alternating sends between two key sets on
/// one fabric therefore stay correct (each send sees a different `epoch_key`
/// and re-derives), and in the degenerate case where two key sets hold the
/// same epoch key the cached material is the material both need anyway. The
/// cost of alternating is a re-derivation per send, i.e. today's behaviour.
///
/// The compressed fabric id is deliberately NOT stored: nothing reads it after
/// `op_group_key` is derived, and it is itself a pure function of the two
/// stamps above, so keeping it would only add a field that can go stale.
///
/// **Secret hygiene:** this holds derived key material long-lived and
/// unzeroized. That is acceptable because it is derived from the epoch key,
/// which is already resident unzeroized in
/// [`ControllerState`](crate::state::ControllerState) for as long as the
/// controller is open — dropping an entry removes no guarantee the caller had.
/// This is NOT a secret-erasure boundary (same position as
/// [`matter_crypto::aead::SessionAead`]): a caller that needs group key
/// material scrubbed must scrub the stored epoch keys.
struct GroupKeyCacheEntry {
    /// The epoch key these values were derived from — half the invalidation
    /// stamp.
    epoch_key: [u8; 16],
    /// The fabric's RCAC public key (SEC1 uncompressed), the compressed fabric
    /// id — and hence `op_group_key` — was derived from: the other half of the
    /// stamp. Fixed for a given fabric today; compared anyway so that a fabric
    /// re-created under the same id with a NEW root can never be served this
    /// entry's keys (which would put undecryptable frames on the wire).
    root_public_key: [u8; 65],
    /// Operational group key: the AES-CCM key for group messages.
    op_group_key: [u8; 16],
    /// Group session id carried in the group message header.
    group_session_id: u16,
    /// Privacy key for the header obfuscation (§4.8.3), derived from
    /// `op_group_key`.
    privacy_key: [u8; 16],
}

/// A completed spawned CASE connect (event-driven connect), delivered
/// back to the actor loop for session registration + waiter resolution. On
/// success it carries the established [`CaseSessionOutput`] (the actor registers
/// it — the task has no `SessionManager`) and the resolved device address.
///
/// [`CaseSessionOutput`]: matter_crypto::CaseSessionOutput
struct ConnectCompletion {
    node_id: u64,
    result: Result<(matter_crypto::CaseSessionOutput, SocketAddr), Error>,
    /// The peer's advertised MRP config this handshake was sized to, carried
    /// back rather than re-read from `connect_mrp`: the map entry can be
    /// cleared mid-flight by a resolve expiry or a forget, and re-reading it
    /// silently substituted a default.
    peer_mrp: matter_transport::MrpConfig,
    /// Whether `peer_mrp` came from the device's own TXT record.
    provenance: matter_transport::MrpProvenance,
    /// True when this attempt's Sigma1 carried resumption fields. Read only on
    /// the failure path, to tell "the stored record is unusable" apart from a
    /// genuine connect failure.
    attempted_resumption: bool,
    /// The device's own `SessionParameters` if it sent any, refining
    /// `peer_mrp` for the registered session. More trustworthy than the mDNS
    /// TXT record, which can be stale, cached, or absent.
    peer_session_params: Option<matter_crypto::SessionParameters>,
}

/// True when `err` is specifically "the responder proved a different shared
/// secret for the resumption id we offered".
///
/// Matched structurally through the error chain rather than on a string: the
/// variant travels `matter_crypto::Error` -> `DriverError::Crypto` ->
/// `Error::Driver`, and both intermediate enums are `#[non_exhaustive]`, so a
/// wildcard arm is required but the path itself is stable.
///
/// Deliberately narrow. `EphemeralKeyGenerationFailed` also covers HKDF
/// failures inside the resume-key derivation and must NOT be treated as a bad
/// record — discarding usable resumption state on an unrelated internal error
/// would be a silent, self-inflicted performance regression.
fn is_resumption_mac_mismatch(err: &Error) -> bool {
    matches!(
        err,
        Error::Driver(matter_commissioning::driver::DriverError::Crypto(
            matter_crypto::Error::ResumptionMacMismatch
        ))
    )
}

/// A connect whose device has not been seen on mDNS yet, parked on the actor's
/// timer arm ([`Actor::drive_pending_resolves`]) instead of blocking the loop.
///
/// The connect's waiters already sit in `pending_connects` under `node_id`, so
/// this carries only what turning an mDNS hit into a spawned handshake needs.
struct PendingResolve {
    fabric_id: u64,
    node_id: u64,
    /// The operational instance name to match, case-insensitively:
    /// `<compressed-fabric-id>-<node-id>`.
    target: String,
    /// When to give up and fail the node's waiters.
    deadline: Instant,
}

/// One operational record drained from the shared browse, already reduced to
/// what a connect needs. Kept in `seen_records` so a record that arrives before
/// anyone is waiting for it is not thrown away — see [`SEEN_RECORD_TTL`].
struct SeenRecord {
    peer: SocketAddr,
    peer_mrp: matter_transport::MrpConfig,
    /// When this record was last drained; ages the entry out.
    seen: Instant,
    /// Which browse last surfaced this record — [`BROWSE_SUBTYPE`] (the
    /// fabric-scoped `_I<id>._sub._matter._tcp` browse) or [`BROWSE_BASE`] (the
    /// unfiltered `_matter._tcp` one). Diagnostics only: it is what a log shows
    /// when a resolve is satisfied, so a field report says which browse did the
    /// work (issue #113).
    source: &'static str,
}

/// Labels for the two operational browses the actor runs concurrently, used in
/// its resolve diagnostics.
const BROWSE_SUBTYPE: &str = "subtype";
const BROWSE_BASE: &str = "base";

/// How many observed instance names a discovery-failure message quotes.
const SEEN_SAMPLE_MAX: usize = 5;

/// Character bound on each quoted instance name. A Matter operational instance
/// name is 33 characters (`<16 hex>-<16 hex>`); anything longer is a foreign
/// record and is elided, so no advertisement on the network can make our error
/// message unbounded.
const SEEN_NAME_MAX: usize = 48;

/// Build the "not found" text for a failed operational resolve, appending a
/// bounded summary of the operational records that *were* seen.
///
/// The `not found via mDNS` substring is preserved verbatim — callers (and our
/// own tests) match on it. What follows is diagnosis: a non-empty `seen` means
/// the browse works and this particular node was absent from it (device
/// offline, different fabric, stale node id). `seen` is expected pre-sorted for
/// a stable message.
///
/// An **empty** `seen` is deliberately worded as the weaker claim it is. It
/// means nothing was *counted*, which covers both "no `_matter._tcp` response
/// reached this host" (firewall, no multicast on the interface, wrong network)
/// and "responses arrived and were discarded upstream of the count" — the mDNS
/// adapter drops a record whose `ty_domain` it does not recognise (a Matter
/// `_I<fabric>._sub._matter._tcp` subtype, say) or that resolved with no
/// addresses, and this caller's own filters drop more. The record-by-record
/// trace under `matter_transport::mdns` is what separates the two.
///
/// Bounded on both axes ([`SEEN_SAMPLE_MAX`] names, [`SEEN_NAME_MAX`]
/// characters each) so the message cannot grow with the size of the network.
///
/// A sibling of this lives in `matter_commissioning::driver::case`, which
/// produces the same error from the inline (commissioning-time) resolver; the
/// two are deliberately duplicated rather than shared through new public API.
/// The *text* they produce is identical, but the populations they count are
/// **not**: this one is fed from the actor's `seen_records`, which holds only
/// records that survived address selection, while the commissioning resolver
/// counts every record its poll returned. Neither sees a record the adapter
/// discarded during translation. So the counts are not comparable across the
/// two messages, and neither is a measure of what arrived on the wire.
fn discovery_failure_message(target: &str, seen: &[&str]) -> String {
    use std::fmt::Write as _;

    let mut msg = format!("operational node {target} not found via mDNS");
    if seen.is_empty() {
        msg.push_str(
            " (saw 0 operational mDNS records — either no _matter._tcp response \
             reached this host, or responses arrived and were discarded before \
             being counted; RUST_LOG=matter_transport::mdns=debug distinguishes \
             the two)",
        );
        return msg;
    }
    // Writing to a String is infallible; the Result exists only to satisfy the
    // `fmt::Write` signature.
    let _ = write!(
        msg,
        " (saw {} operational mDNS record(s), none matching: ",
        seen.len()
    );
    for (i, name) in seen.iter().take(SEEN_SAMPLE_MAX).enumerate() {
        if i > 0 {
            msg.push_str(", ");
        }
        if name.chars().count() > SEEN_NAME_MAX {
            msg.extend(name.chars().take(SEEN_NAME_MAX));
            msg.push('…');
        } else {
            msg.push_str(name);
        }
    }
    if seen.len() > SEEN_SAMPLE_MAX {
        let _ = write!(msg, ", … {} more", seen.len() - SEEN_SAMPLE_MAX);
    }
    msg.push(')');
    msg
}

/// A unit of work parked behind an in-flight CASE connect. On connect
/// success each is resumed on the freshly-established `(session, peer)`; on
/// failure each is resolved/rescheduled per its kind ([`Actor::handle_connect_done`]
/// / [`Actor::fail_connect_waiters`]). This lets the two timer-arm recovery
/// reconnects share the same off-loop connect as the steady-state verb path, so
/// no CASE handshake runs inline on the actor loop.
enum ConnectWaiter {
    /// A device verb parked before dispatch (the steady-state path): re-dispatch
    /// on success (its `session_for` now cache-hits), fail its caller on error.
    Command(Command),
    /// A timed-out pending op to re-send on the fresh session (pending-retry
    /// recovery, from [`Actor::on_pending_timeout`]).
    ResendPending(Pending),
    /// A stranded subscription to re-establish on the fresh session (resubscribe
    /// recovery, from [`Actor::attempt_resubscribe`]); reschedule on failure.
    Resubscribe(PendingResubscribe),
}

/// Canonicalize a peer address for the in-flight-handshake route table.
///
/// The address we *resolve* (from mDNS) and the address a datagram *arrives*
/// from can differ in representation for the same peer, so keying the route map
/// on the raw [`SocketAddr`] would miss:
/// - **IPv4-mapped IPv6:** on a dual-stack IPv6 socket, `TokioUdpTransport`
///   sends to an IPv4 peer as `::ffff:a.b.c.d` and `recv_from` reports the reply
///   `from` in that same mapped form, while the resolved `peer` is plain
///   `a.b.c.d`. Unmap so the two compare equal.
/// - **IPv6 scope id:** `recv_from` stamps a link-local `from` with the arrival
///   interface's scope id, which the resolved `peer` lacks. `IpAddr` carries no
///   scope id, so rebuilding through it drops the scope.
///
/// The port is preserved (a Matter device replies from the operational port it
/// received on), so distinct devices sharing an IP — e.g. two loopback DUTs —
/// still route independently.
fn route_key(addr: SocketAddr) -> SocketAddr {
    let ip = match addr.ip() {
        IpAddr::V6(v6) => v6.to_ipv4_mapped().map_or(IpAddr::V6(v6), IpAddr::V4),
        IpAddr::V4(v4) => IpAddr::V4(v4),
    };
    SocketAddr::new(ip, addr.port())
}

/// The device node id a command opens a session to, or `None` if it needs no
/// per-device session (fabric/group/ICD/diagnostic commands). Used by
/// [`Actor::dispatch`] to park a verb behind an off-loop connect instead of
/// running the handshake inline.
fn command_target_node(cmd: &Command) -> Option<u64> {
    match cmd {
        Command::Read { node_id, .. }
        | Command::Action { node_id, .. }
        | Command::TimedRoundTrip { node_id, .. }
        | Command::ChunkedWrite { node_id, .. }
        | Command::Subscribe { node_id, .. } => Some(*node_id),
        #[cfg(test)]
        Command::RoundTrip { node_id, .. } => Some(*node_id),
        _ => None,
    }
}

/// Resolve a parked verb's caller with `err` when its connect fails. Only the
/// verb variants [`command_target_node`] parks are handled; other commands are
/// never enqueued as connect waiters, so they fall through as a no-op.
fn fail_command(cmd: Command, err: Error) {
    // Arms are grouped by reply payload type (the `oneshot::Sender<Result<_,_>>`
    // differs per verb), so they cannot merge into one `|` pattern.
    match cmd {
        Command::Read { reply, .. } => {
            let _ = reply.send(Err(err));
        }
        Command::Action { reply, .. } | Command::TimedRoundTrip { reply, .. } => {
            let _ = reply.send(Err(err));
        }
        // Distinct arm: `ChunkedWrite`'s reply carries parsed per-path
        // statuses, not raw bytes, so it cannot merge into the arm above.
        Command::ChunkedWrite { reply, .. } => {
            let _ = reply.send(Err(err));
        }
        Command::Subscribe { reply, .. } => {
            let _ = reply.send(Err(err));
        }
        #[cfg(test)]
        Command::RoundTrip { reply, .. } => {
            let _ = reply.send(Err(err));
        }
        _ => {}
    }
}

/// Run a CASE (SIGMA-I) handshake to an already-resolved `peer` **off the actor
/// loop**, driving it over a
/// [`HandshakeSocket`](crate::handshake_socket::HandshakeSocket) whose datagrams
/// flow through the actor's own socket (this task never touches a socket).
/// Reports the established session (or error) back over `done_tx`. Takes only
/// owned inputs so the future is `'static + Send` and can be `tokio::spawn`ed.
///
/// The device's address is resolved on the actor, via its injected discovery,
/// before this task is spawned ([`Actor::spawn_connect`] on a cached mDNS hit,
/// [`Actor::drive_pending_resolves`] once a parked lookup lands) — so only the
/// multi-round-trip handshake runs here.
#[allow(clippy::too_many_arguments)]
async fn run_connect_task(
    node_id: u64,
    fabric_id: u64,
    local_session_id: u16,
    credentials: matter_crypto::CaseCredentials,
    roots: matter_cert::TrustedRoots,
    now: matter_cert::MatterTime,
    peer: SocketAddr,
    peer_mrp: matter_transport::MrpConfig,
    provenance: matter_transport::MrpProvenance,
    resumption_record: Option<matter_crypto::ResumptionRecord>,
    inbound_rx: mpsc::Receiver<(Vec<u8>, SocketAddr)>,
    outbound_tx: mpsc::Sender<crate::handshake_socket::HandshakeOutbound>,
    done_tx: mpsc::Sender<ConnectCompletion>,
) {
    let socket = crate::handshake_socket::HandshakeSocket::new(node_id, outbound_tx, inbound_rx);
    let attempted_resumption = resumption_record.is_some();
    let mut opts = matter_commissioning::driver::CaseEstablishOptions::new(
        local_session_id,
        credentials,
        roots,
        node_id,
        fabric_id,
        now,
    )
    .with_peer_mrp(peer_mrp)
    .with_session_params(local_session_params());
    if let Some(record) = resumption_record {
        opts = opts.with_resumption_record(record);
    }
    let established = matter_commissioning::driver::run_case_establish_with(&socket, peer, opts)
        .await
        .map_err(Error::from);

    let (result, peer_session_params) = match established {
        Ok(e) => {
            if e.resumed {
                tracing::debug!(
                    target: "matter_controller::actor",
                    node_id,
                    "CASE resumed from a stored record (no Sigma3)"
                );
            }
            let params = e.peer_session_params;
            (Ok((e.output, peer)), params)
        }
        Err(e) => (Err(e), None),
    };
    let _ = done_tx
        .send(ConnectCompletion {
            node_id,
            result,
            peer_mrp,
            provenance,
            attempted_resumption,
            peer_session_params,
        })
        .await;
}

/// What this controller advertises about itself in Sigma1's
/// `initiatorSessionParams` (context tag 5).
///
/// Both reference implementations always send this; chip treats a missing
/// local config as a hard error. Omitting it is conformant but costs us — the
/// device then sizes its own Sigma2/Sigma3-ack retransmits to the spec
/// defaults rather than to us, and there is no mDNS channel for a
/// *commissioner's* MRP parameters.
///
/// Each claim is what we actually implement, not what would look best:
///
/// - **MRP intervals**: our own `MrpConfig::default()`, i.e. the spec's
///   500/300/4000. chip likewise sends `GetLocalMRPConfig()` — its own
///   timings, never the peer's.
/// - **`interaction_model_revision`**: sourced from
///   [`matter_interaction::IM_REVISION`] so it cannot drift from the value we
///   put at IM context tag `0xFF`. Advertising one number while emitting
///   another is a self-contradiction a peer may act on.
/// - **`data_model_revision` 19**: matter.js pairs Data Model 19 with
///   specification 1.4, and chip also reports 19.
/// - **`specification_version` `0x0104_0000`** (Matter 1.4.0): what the
///   protocol implementation here targets. Our cluster definitions are
///   generated from a 1.5.1 model dump, but over-claiming invites a peer to
///   enable behaviour we do not handle, whereas under-claiming only makes it
///   down-shift — the safe direction.
/// - **`max_paths_per_invoke` 1**: we do not batch invokes.
fn local_session_params() -> matter_crypto::SessionParameters {
    let mrp = matter_transport::MrpConfig::default();
    let ms = |d: std::time::Duration| u32::try_from(d.as_millis()).unwrap_or(u32::MAX);
    matter_crypto::SessionParameters::new()
        .with_session_idle_interval_ms(ms(mrp.initial_idle))
        .with_session_active_interval_ms(ms(mrp.initial_active))
        .with_session_active_threshold_ms(
            u16::try_from(mrp.idle_threshold.as_millis()).unwrap_or(u16::MAX),
        )
        .with_data_model_revision(19)
        .with_interaction_model_revision(u16::from(matter_interaction::IM_REVISION))
        .with_specification_version(0x0104_0000)
        .with_max_paths_per_invoke(1)
}

/// A completed spawned commission, delivered back to the actor loop
/// over the completions channel for persistence + reply resolution.
struct CommissionCompletion {
    fabric_id: u64,
    result: Result<matter_commissioning::CommissionedFabric, Error>,
    /// Caller-supplied label to persist on the device entry, carried through
    /// from `Command::Commission`/`CommissionBle` (see there).
    label: Option<String>,
    reply: oneshot::Sender<Result<crate::NodeInfo, Error>>,
}

/// Run a full commission on a **freshly-bound socket + discovery**, off the actor
/// loop. Takes only owned inputs so the future is `'static` + `Send` and
/// can be `tokio::spawn`ed. `commission()` binds nothing itself here — the
/// transient PASE/CASE handshakes run on this task's own socket.
#[allow(clippy::too_many_arguments)]
async fn run_commission_task(
    setup_payload: matter_commissioning::SetupPayload,
    trust: Arc<crate::trust::AttestationTrust>,
    fabric_record: matter_commissioning::FabricRecord,
    commissioner_node_id: u64,
    ipk_epoch_key: [u8; 16],
    commissioner_noc: matter_cert::MatterCertificate,
    commissioner_pkcs8: Vec<u8>,
    assigned_node_id: u64,
    admin_vendor_id: u16,
    now: matter_cert::MatterTime,
    rng: Arc<dyn matter_commissioning::NocRng>,
    multicast_if: Option<u32>,
) -> Result<matter_commissioning::CommissionedFabric, Error> {
    use matter_commissioning::driver::{commission, DriverConfig};
    use matter_commissioning::CommissionerConfig;

    // Honour the builder's `multicast_interface` on this task-local socket
    // too (the main actor socket already binds with it); `None` keeps the
    // `MATTER_MULTICAST_IF` env fallback inside the transport.
    let transport = matter_transport::TokioUdpTransport::bind_with_multicast_if(0, multicast_if)
        .await
        .map_err(|e| Error::Operational(format!("commission bind: {e}")))?;
    let mut discovery = matter_transport::MdnsSdDiscovery::new()
        .map_err(|e| Error::Operational(format!("commission mdns: {e}")))?;

    let commissioner = CommissionerConfig {
        pase_attestation_challenge: [0u8; 16], // commission() overwrites from live PASE
        fabric: &fabric_record,
        setup_payload: &setup_payload,
        paa_trust_store: &trust.paa,
        cd_signing_roots: &trust.cd,
        commissioner_node_id,
        assigned_node_id,
        ipk_epoch_key,
        case_admin_subject: commissioner_node_id,
        admin_vendor_id,
        now,
        rng,
        network: matter_commissioning::NetworkCredentials::AlreadyOnNetwork,
    };
    let config = DriverConfig {
        commissioner,
        commissionable_addr: None, // discover via mDNS using the discriminator
        passcode: setup_payload.passcode.as_u32(),
        commissioner_noc: &commissioner_noc,
        commissioner_signer_pkcs8: &commissioner_pkcs8,
    };
    commission(&transport, &mut discovery, config)
        .await
        .map_err(Error::from)
}

impl<T: AsyncDatagram, D: Discovery> Actor<T, D> {
    pub(crate) fn new(
        transport: T,
        discovery: D,
        store: Arc<dyn ControllerStore>,
        rng: Arc<dyn NocRng>,
        state: ControllerState,
        trust: Option<crate::trust::AttestationTrust>,
        admin_vendor_id: u16,
    ) -> Self {
        Self::new_inner(
            transport,
            discovery,
            store,
            rng,
            state,
            trust,
            admin_vendor_id,
        )
    }

    /// Set the IPv6 multicast egress interface for group sends (the
    /// destination scope id). `None` falls back to `MATTER_MULTICAST_IF`,
    /// then the kernel default. See
    /// `MatterControllerBuilder::multicast_interface`.
    pub(crate) fn with_multicast_if(mut self, multicast_if: Option<u32>) -> Self {
        self.multicast_if = multicast_if;
        self
    }

    /// Bound how long an operational request waits for its Interaction Model
    /// response. See `MatterControllerBuilder::response_deadline` and
    /// [`DEFAULT_RESPONSE_DEADLINE`].
    pub(crate) fn with_response_deadline(mut self, response_deadline: Duration) -> Self {
        self.response_deadline = response_deadline;
        self
    }

    #[allow(clippy::too_many_arguments)] // mirrors `new`.
    fn new_inner(
        transport: T,
        discovery: D,
        store: Arc<dyn ControllerStore>,
        rng: Arc<dyn NocRng>,
        state: ControllerState,
        trust: Option<crate::trust::AttestationTrust>,
        admin_vendor_id: u16,
    ) -> Self {
        let (commission_tx, commission_rx) = mpsc::channel(8);
        let (connect_outbound_tx, connect_outbound_rx) = mpsc::channel(64);
        let (connect_done_tx, connect_done_rx) = mpsc::channel(8);
        Self {
            transport,
            discovery,
            sessions: SessionManager::new(),
            queued_acks: Vec::new(),
            store,
            rng,
            state,
            cache: HashMap::new(),
            trust: trust.map(Arc::new),
            admin_vendor_id,
            subscriptions: HashMap::new(),
            sub_index: HashMap::new(),
            pending: HashMap::new(),
            response_deadline: DEFAULT_RESPONSE_DEADLINE,
            next_sub_id: 1,
            snapshot_seq: 0,
            save_gate: Arc::new(std::sync::Mutex::new(0)),
            resubscribes: Vec::new(),
            resubscribe_pulled_at: HashMap::new(),
            timed_paths: std::collections::HashSet::new(),
            commission_tx,
            commission_rx,
            pending_connects: HashMap::new(),
            connect_mrp: HashMap::new(),
            pending_resolves: Vec::new(),
            next_resolve_poll: Instant::now(),
            consecutive_recv_errors: 0,
            last_recv_error_at: None,
            recv_warn_stage: RecvWarnStage::Quiet,
            recv_backoff_until: None,
            resolve_query: None,
            resolve_query_fabric: None,
            resolve_base_after: None,
            resolve_query_fabric_cfid: None,
            watch_open_retry_at: None,
            advert_quiet_until: None,
            watch_requery_at: None,
            watch_requery_interval: ADVERT_REQUERY_FIRST,
            watch_episode_nodes: Vec::new(),
            requery_fast_drain_until: None,
            seen_records: HashMap::new(),
            multicast_if: None,
            group_counters: HashMap::new(),
            group_key_cache: HashMap::new(),
            connect_inbound: HashMap::new(),
            connect_routes: HashMap::new(),
            connect_outbound_tx,
            connect_outbound_rx,
            connect_done_tx,
            connect_done_rx,
            #[cfg(test)]
            reschedule_causes: Vec::new(),
            #[cfg(test)]
            episode_sizes_at_attempt: Vec::new(),
        }
    }

    /// The task loop. A single `select!` owns `recv_from()` continuously: it
    /// dispatches commands, routes every inbound datagram through
    /// [`Self::handle_inbound`] (resolving pending round-trips/reads by
    /// `(session, exchange)` and delivering subscription reports by
    /// `(session, subscriptionId)`), and drives MRP for all sessions in the
    /// timer arm. Because round-trips/reads register a pending op and return to
    /// the loop instead of owning recv, a steady-state report arriving during a
    /// concurrent round-trip is delivered, not dropped.
    ///
    /// ## Long handlers run off the loop
    ///
    /// The two multi-round-trip protocol flows — **commission** and **CASE
    /// connect** — no longer run inline on this task. Each is driven on a
    /// `tokio::spawn`ed task and reports back over a channel the `select!`
    /// drains, so the loop keeps servicing every other session's inbound, MRP
    /// retransmits, and subscription-liveness checks for the whole handshake
    /// window (found in the 2026-06-12 audit, resolved). Concretely:
    ///
    /// - **Commission** ([`Self::spawn_commission`]) runs on its own freshly
    ///   bound socket + discovery; on completion the device is persisted and the
    ///   caller's reply resolved ([`Self::handle_commission_completion`]).
    /// - **CASE connect** parks the triggering verb in `pending_connects` and
    ///   spawns [`run_connect_task`], whose handshake I/O flows through *this*
    ///   actor's socket via a [`HandshakeSocket`](crate::handshake_socket::HandshakeSocket):
    ///   its outbound datagrams are drained by the `connect_outbound_rx` arm
    ///   (which sends them and installs the peer route), and inbound handshake
    ///   replies are demuxed to the task by [`Self::handle_inbound`]. On
    ///   completion ([`Self::handle_connect_done`]) the session is registered and
    ///   the parked verbs re-dispatched. Because every datagram still leaves and
    ///   arrives on this socket, the session lives here from the first message —
    ///   no second socket, no session migration. The device's address comes from
    ///   the injected discovery, drained non-blockingly: a cached record spawns
    ///   the handshake at once, and an unknown one parks a [`PendingResolve`]
    ///   polled on the timer arm ([`Self::drive_pending_resolves`]), so an
    ///   unreachable device costs the loop nothing while it is looked up.
    ///
    /// **Residual:** the two low-frequency *recovery* connects — a pending
    /// round-trip's post-timeout reconnect and a stranded subscription's
    /// resubscribe, both driven from the timer arm — still use the inline
    /// [`Self::connect`]. They briefly pause the loop; decoupling them the same
    /// way is a possible future refinement, not a steady-state concern.
    ///
    /// ## Timer fairness under sustained inbound load
    ///
    /// The `select!` is `biased`, so its arms are polled top-to-bottom and the
    /// future completes on the first ready arm. A device flooding `ReportData`
    /// keeps `recv_from()` perpetually ready. To stop that flood from starving
    /// the timer arm (which would delay MRP retransmits and subscription-liveness
    /// checks past their deadlines), the timer work is gated on an *explicit
    /// overdue check* evaluated at the top of every iteration BEFORE the
    /// `select!`: [`Self::next_timer_deadline`] computes the earliest moment any
    /// timer work is due, and whenever that moment has already passed we run
    /// [`Self::drive_mrp`]/[`Self::check_liveness`]/[`Self::drive_resubscribes`]/
    /// [`Self::drive_pending_resolves`] immediately, then `continue`, regardless
    /// of how much inbound is pending.
    ///
    /// This guarantees deadlines are honoured under continuous inbound: each
    /// inbound packet costs one loop iteration, and at the start of the next
    /// iteration any deadline that came due is serviced before the next recv.
    /// It does not starve recv — the overdue path only fires when a timer is
    /// actually due (bounded by how many deadlines elapse, not by inbound rate),
    /// and otherwise we fall through to the `select!` where a ready recv is
    /// served. The trade-off versus simply dropping `biased` (letting tokio
    /// randomize) is determinism: the explicit check gives a hard "timers fire
    /// within one inbound-packet of their deadline" bound rather than a
    /// probabilistic one, which matters for MRP retransmit timing.
    ///
    /// ## Parking on the computed deadline
    ///
    /// The park is not periodic. Every iteration recomputes the deadline from
    /// the *scheduled work that actually exists* — MRP retransmit/ack-flush
    /// deadlines, subscription liveness deadlines, and pending resubscribe
    /// attempt times — with one exception: mDNS results arrive by polling rather
    /// than on a deadline, so while `pending_resolves` is non-empty, or the
    /// resubscribe watch holds the subtype browse, the deadline also includes
    /// the polling anchor `next_resolve_poll` ([`RESOLVE_POLL_INTERVAL`] /
    /// [`ADVERT_WATCH_POLL_INTERVAL`]), and a failed watch open's retry instant
    /// while it can still happen — and, while a receive backoff is in force, the
    /// instant it expires (`recv_backoff_until`, see below).
    /// With nothing at all scheduled the loop parks on [`IDLE_PARK_MAX`];
    /// because all seven sources ([`Self::next_timer_deadline`]: MRP
    /// retransmit/ack-flush, subscription liveness, resubscribe attempt times,
    /// the mDNS drain tick, application response deadlines, the receive
    /// backoff, and a failed watch open's retry) are re-derived from live state
    /// after every iteration, work scheduled by any other `select!` arm
    /// shortens the very next park, so the backstop only bounds an
    /// unenumerated source.
    ///
    /// The consequence is that a fully idle controller (no in-flight MRP, no
    /// subscriptions, no parked resolves) wakes essentially never, instead of
    /// four times a second as the earlier fixed liveness tick did.
    ///
    /// ## Transport receive errors
    ///
    /// `recv_from` failures are classified rather than discarded. Discarding
    /// them (the original code) meant a transport whose error is *permanent*
    /// made the recv arm instantly ready forever and pegged a core — measured at
    /// ~447 000 error returns in 6 s (~75 000 per second) against an
    /// [`InMemoryDatagram`](matter_commissioning::driver::InMemoryDatagram)
    /// whose peer half had dropped.
    ///
    /// - A **terminal** kind ([`recv_error_is_terminal`]) means the socket will
    ///   never deliver again, so the actor shuts down through the same
    ///   [`Self::shutdown_discovery`] path a dropped command channel takes.
    /// - Anything else is **transient** and merely logged, because a socket
    ///   surfaces isolated, recoverable errors (`EINTR`, spurious wakeups, ICMP
    ///   errors queued on a connected socket) that must not kill a controller,
    ///   and because `ErrorKind` is `#[non_exhaustive]`: a kind we failed to
    ///   anticipate must back off, not stop the actor. To keep "transient" from
    ///   re-introducing the spin, [`RECV_ERROR_FREE_RETRIES`] consecutive errors
    ///   with no successful receive between them start a doubling backoff
    ///   ([`recv_error_backoff`]) that disables the recv arm until
    ///   `recv_backoff_until`. Because that is a deadline the loop parks on
    ///   rather than a sleep inside the arm, commands, MRP and liveness continue
    ///   at full speed while a wedged transport is backed off.
    ///
    /// A run of transient errors also decays ([`RECV_ERROR_DECAY`]), so a
    /// controller that sees one error every few seconds never creeps up to the
    /// backoff ceiling and stays there; and it escalates to `warn` on the edges
    /// of the condition ([`RecvWarnStage`]), so a transport that is wedged
    /// *transiently* — which leaves the controller unable to receive anything,
    /// at `debug` — is diagnosable at default log levels.
    pub(crate) async fn run(mut self, mut rx: mpsc::Receiver<Command>) {
        loop {
            // ACKs a deliberate session release queued from a synchronous path
            // (`release_session`).
            if !self.queued_acks.is_empty() {
                self.send_queued_acks().await;
            }
            let now = Instant::now();

            // Retire an elapsed recv backoff BEFORE the deadline is computed.
            // `recv_backoff_until` feeds `next_timer_deadline`, so a value left
            // behind in the past would make the overdue guard below fire on
            // every iteration — a spin of exactly the kind the backoff exists to
            // prevent. Cleared here, the field is only ever a future instant.
            if self.recv_backoff_until.is_some_and(|until| until <= now) {
                self.recv_backoff_until = None;
            }
            let recv_enabled = self.recv_backoff_until.is_none();

            let next_deadline = self.next_timer_deadline();

            // Fairness guard: if timer work is already due, service it before
            // draining any more inbound. This is what prevents a sustained
            // inbound flood (which keeps `recv_from()` perpetually ready) from
            // starving the timer arm and pushing MRP retransmits / subscription
            // liveness past their deadlines. It only fires when a deadline has
            // actually elapsed, so it cannot starve recv or busy-loop: each pass
            // advances every deadline forward — MRP `handle_timeout` reschedules
            // or drops, liveness/resubscribe entries are consumed or re-armed,
            // and `drive_pending_resolves` re-arms `next_resolve_poll` — so the
            // guard yields back to recv on the next iteration. Two of the seven
            // sources (see `next_timer_deadline`) are future-only by
            // construction and so can never be seen here as due: the
            // recv-backoff deadline, retired above, and the watch-open retry,
            // which counts only while it is still in the future.
            if next_deadline.is_some_and(|d| d <= now) {
                self.drive_mrp().await;
                self.drive_response_deadlines().await;
                self.check_liveness();
                self.drive_resubscribes().await;
                self.reconcile_resubscribe_watch(Instant::now());
                self.drive_pending_resolves();
                continue;
            }

            let sleep_for =
                next_deadline.map_or(IDLE_PARK_MAX, |d| d.saturating_duration_since(now));
            tokio::select! {
                biased;
                maybe = rx.recv() => {
                    let Some(cmd) = maybe else {
                        // Every controller handle is gone: send any ACK still
                        // owed, then shut down. chip's shutdown has no such
                        // flush (`ExchangeMgr.cpp:90-103`) because every close
                        // already flushed (`DoClose` → `FlushAcks`,
                        // `ExchangeContext.cpp:239` at master 5cd2917a, `:237`
                        // at v1.4.2.0); here it covers a release's queued ACK
                        // or a displaced ACK not yet pumped. Best effort: it does not run if the runtime
                        // is being dropped, which is why every terminal branch
                        // flushes before answering its caller.
                        self.send_queued_acks().await;
                        for event in self.sessions.flush_pending_acks() {
                            self.send_ack_event(event, None).await;
                        }
                        return self.shutdown_discovery();
                    };
                    self.dispatch(cmd).await;
                }
                // M9-G-d: a spawned commission finished — persist + resolve its
                // reply. This arm keeps the loop responsive to other sessions
                // for the whole commission window.
                Some(completion) = self.commission_rx.recv() => {
                    self.handle_commission_completion(completion).await;
                }
                // M9-G-d event-driven connect: a spawned CASE handshake wants a
                // datagram put on the wire — the actor owns the socket, so it
                // sends it (and installs the peer route). Above the inbound arm
                // so an inbound flood cannot starve handshake progress.
                Some(out) = self.connect_outbound_rx.recv() => {
                    self.handle_connect_outbound(out).await;
                }
                // A spawned CASE connect completed — register the session (or
                // fail the parked verbs) and re-dispatch the waiters.
                Some(done) = self.connect_done_rx.recv() => {
                    self.handle_connect_done(done).await;
                }
                recv = self.transport.recv_from(), if recv_enabled => match recv {
                    Ok((packet, from)) => {
                        // Close the edge as loudly as it was opened: whoever saw
                        // "this transport is wedged" at `warn` must be able to
                        // see it recover at the same filter level. Bounded to one
                        // line per wedge, because the stage only leaves `Quiet`
                        // via the edge-triggered warnings below.
                        if self.recv_warn_stage > RecvWarnStage::Quiet {
                            tracing::warn!(
                                target: "matter_controller::actor",
                                after_consecutive_errors = self.consecutive_recv_errors,
                                "transport recv_from recovered; the controller is receiving again",
                            );
                        }
                        self.consecutive_recv_errors = 0;
                        self.last_recv_error_at = None;
                        self.recv_warn_stage = RecvWarnStage::Quiet;
                        self.handle_inbound(&packet, from).await;
                    }
                    // The transport is gone for good — leave through exactly the
                    // path a dropped command channel uses, so the shared mDNS
                    // browse is released rather than left running.
                    Err(e) if recv_error_is_terminal(e.kind()) => {
                        tracing::warn!(
                            target: "matter_controller::actor",
                            error = %e,
                            "transport recv_from failed terminally; stopping the actor loop",
                        );
                        return self.shutdown_discovery();
                    }
                    // Transient: keep serving, but back the recv arm off once a
                    // run of errors says the transport is not merely blipping.
                    Err(e) => self.note_transient_recv_error(&e, Instant::now()),
                },
                () = tokio::time::sleep(sleep_for) => {
                    tracing::trace!(target: "matter_controller::actor", "timer wake");
                    self.drive_mrp().await;
                    self.drive_response_deadlines().await;
                    self.check_liveness();
                    self.drive_resubscribes().await;
                    self.reconcile_resubscribe_watch(Instant::now());
                    self.drive_pending_resolves();
                }
            }
        }
    }

    /// Record a transient `recv_from` failure that arrived at `at`: age out a
    /// stale run, extend the current one, arm the backoff, and log it.
    ///
    /// Split out of [`Self::run`]'s `select!` so the loop body stays readable;
    /// `at` is a parameter (rather than an inner `Instant::now()`) so the
    /// decay's timing is testable.
    fn note_transient_recv_error(&mut self, e: &std::io::Error, at: Instant) {
        // Errors far enough apart are unrelated blips, not a run: decay first,
        // so the free-retry budget is genuinely restored rather than being a
        // once-per-process allowance.
        if recv_error_run_broken(self.last_recv_error_at, at) {
            self.consecutive_recv_errors = 0;
            self.recv_warn_stage = RecvWarnStage::Quiet;
        }
        self.last_recv_error_at = Some(at);
        self.consecutive_recv_errors = self.consecutive_recv_errors.saturating_add(1);
        let backoff = recv_error_backoff(self.consecutive_recv_errors);
        if let Some(backoff) = backoff {
            self.recv_backoff_until = Some(at + backoff);
        }
        // Edge-triggered escalation: `warn` exactly once when the run stops
        // looking like a blip, and once more when the backoff saturates. A
        // transport wedged on a transient kind makes the controller deaf, which
        // must not be invisible at `info` — but it must not be a log flood
        // either, so every other error stays at `debug`.
        let stage = recv_error_warn_stage(backoff);
        if stage > self.recv_warn_stage {
            self.recv_warn_stage = stage;
            let outlook = if stage == RecvWarnStage::Saturated {
                "the transport looks wedged for good; requests will time out until it recovers"
            } else {
                "backing the receive arm off; the controller receives nothing while this persists"
            };
            tracing::warn!(
                target: "matter_controller::actor",
                error = %e,
                kind = ?e.kind(),
                consecutive = self.consecutive_recv_errors,
                backoff = ?backoff,
                "transport recv_from keeps failing: {outlook}",
            );
        } else {
            tracing::debug!(
                target: "matter_controller::actor",
                error = %e,
                consecutive = self.consecutive_recv_errors,
                "transport recv_from failed transiently; continuing",
            );
        }
    }

    /// Earliest instant any timer work is due: MRP retransmit/ack-flush,
    /// subscription liveness, scheduled resubscribes — plus a polling tick while
    /// mDNS resolves are parked ([`RESOLVE_POLL_INTERVAL`]) or the resubscribe
    /// watch holds the subtype browse ([`ADVERT_WATCH_POLL_INTERVAL`]), because
    /// discovery results arrive by polling, not by deadline, plus a failed watch
    /// open's retry instant while it is in the future and could happen, and plus
    /// the recv
    /// backoff deadline while the recv arm is suppressed (else a loop with no
    /// other scheduled work would park past it and leave the arm disabled).
    /// `None` means nothing is scheduled and the loop parks on inbound/commands
    /// alone (bounded by [`IDLE_PARK_MAX`]).
    ///
    /// Recomputed from live state on every loop iteration, so any work
    /// scheduled by another `select!` arm is reflected in the very next park —
    /// there is no cached deadline to invalidate. Every component is an
    /// ABSOLUTE instant (including the resolve anchor, see
    /// `next_resolve_poll`), never `now + interval`: a relative component would
    /// be pushed forward by every unrelated wakeup and could be starved
    /// indefinitely by a busy loop.
    fn next_timer_deadline(&self) -> Option<Instant> {
        let now = Instant::now();
        let mrp = self.sessions.poll_timeout();
        let liveness = self
            .subscriptions
            .values()
            .map(|e| e.liveness_deadline)
            .min();
        let resub = self.resubscribes.iter().map(|pr| pr.attempt_at).min();
        // The drain tick: while a resolve is parked, and while the subtype
        // browse is held (by the resubscribe watch) — both are served by
        // polling, not by a deadline.
        let resolve = if self.pending_resolves.is_empty() && self.resolve_query_fabric.is_none() {
            None
        } else {
            Some(self.next_resolve_poll)
        };
        // A failed watch open is retried at `watch_open_retry_at`, but only a
        // retry still in the FUTURE that could actually happen counts. A
        // past-due or impossible one (no sole fabric, nothing waiting, a browse
        // already held, a base browse live) would make the overdue guard in
        // `run` fire on every pass — the spin `recv_backoff_until` is retired
        // early to avoid.
        let watch_retry = self.watch_open_retry_at.filter(|at| {
            *at > now
                && self.resolve_query_fabric.is_none()
                && self.resolve_query.is_none()
                && self.sole_fabric().is_ok()
                && self.resubscribe_watch_needed()
        });
        // Application-level response deadlines. Independent of `mrp` above:
        // once a request is ACKed its MRP entry is gone, so this is the only
        // remaining source that can bound a device which accepts a request and
        // never answers it.
        let response = self.pending.values().map(|p| p.response_deadline).min();
        [
            mrp,
            liveness,
            resub,
            resolve,
            response,
            self.recv_backoff_until,
            watch_retry,
        ]
        .into_iter()
        .flatten()
        .min()
    }

    /// Process one command, parking device verbs behind an off-loop connect.
    ///
    /// If `cmd` targets a device with no live cached session, the CASE
    /// handshake is run on a spawned task ([`Self::spawn_connect`]) and the
    /// command is queued in `pending_connects`; the actor loop returns
    /// immediately and stays responsive to every other session for the whole
    /// handshake. When the connect completes the queued verbs are re-dispatched
    /// through [`Self::dispatch_ready`] (their `session_for` now cache-hits).
    /// Commands that need no per-device session — and any verb whose session is
    /// already cached — run inline via [`Self::dispatch_ready`].
    async fn dispatch(&mut self, cmd: Command) {
        if matches!(&cmd, Command::Action { reply, .. } | Command::TimedRoundTrip { reply, .. } if reply.stopped())
        {
            fail_command(
                cmd,
                Error::Operational("action deadline elapsed or caller dropped".into()),
            );
            return;
        }
        if let Some(node_id) = command_target_node(&cmd) {
            if let Ok(fabric_id) = self.sole_fabric().map(|f| f.fabric_id) {
                if !self.cache.contains_key(&(fabric_id, node_id)) {
                    self.enqueue_connect_waiter(fabric_id, node_id, ConnectWaiter::Command(cmd));
                    return;
                }
            }
        }
        self.dispatch_ready(cmd).await;
    }

    /// Process one command whose device session (if any) is already established.
    // A flat command dispatcher: one arm per `Command` variant, each a thin
    // delegation to a handler. Length tracks the verb count, not branching
    // complexity, so the line cap does not apply meaningfully here.
    #[allow(clippy::too_many_lines)]
    async fn dispatch_ready(&mut self, cmd: Command) {
        match cmd {
            Command::CreateFabric { cfg, reply } => {
                let _ = reply.send(self.handle_create_fabric(&cfg).await);
            }
            #[cfg(test)]
            Command::RoundTrip {
                node_id,
                opcode,
                protocol_id,
                payload,
                reply,
            } => {
                self.start_round_trip(node_id, opcode, protocol_id, payload, reply)
                    .await;
            }
            Command::Read {
                node_id,
                payload,
                reply,
            } => {
                self.start_read(node_id, payload, reply).await;
            }
            Command::Commission {
                setup_payload,
                label,
                reply,
            } => {
                // M9-G-d: spawn on its own socket + return to the loop
                // immediately; the result is resolved later via the completions
                // channel, so a multi-second commission no longer pauses other
                // sessions' MRP/liveness.
                self.spawn_commission(setup_payload, label, reply);
            }
            #[cfg(feature = "ble")]
            Command::CommissionBle {
                setup_payload,
                network,
                label,
                reply,
            } => {
                // Same off-loop pattern as `Command::Commission`, but the
                // spawned task scans BLE + opens a BTP session first.
                self.spawn_commission_ble(setup_payload, network, label, reply);
            }
            Command::Subscribe {
                node_id,
                paths,
                event_paths,
                event_filters,
                min_interval,
                max_interval,
                reply,
            } => {
                self.start_subscribe(
                    node_id,
                    paths,
                    event_paths,
                    event_filters,
                    min_interval,
                    max_interval,
                    reply,
                )
                .await;
            }
            Command::Action {
                node_id,
                opcode,
                plain_payload,
                timed_payload,
                keys,
                timeout_ms,
                reply,
            } => {
                self.handle_action(
                    node_id,
                    opcode,
                    plain_payload,
                    timed_payload,
                    keys,
                    timeout_ms,
                    reply,
                )
                .await;
            }
            Command::TimedRoundTrip {
                node_id,
                timeout_ms,
                action_opcode,
                action_payload,
                reply,
            } => {
                self.start_timed_round_trip(
                    node_id,
                    timeout_ms,
                    action_opcode,
                    action_payload,
                    reply,
                )
                .await;
            }
            Command::ChunkedWrite {
                node_id,
                chunks,
                reply,
            } => {
                self.handle_chunked_write(node_id, chunks, reply).await;
            }
            Command::CommissionerNodeId { reply } => {
                let _ = reply.send(self.sole_fabric().map(|f| f.commissioner.node_id));
            }
            Command::ListNodes { reply } => {
                let nodes = self
                    .state
                    .fabrics
                    .iter()
                    .flat_map(|f| {
                        f.devices.iter().map(move |d| crate::NodeInfo {
                            node_id: d.node_id,
                            fabric_id: f.fabric_id,
                            vendor_id: d.vendor_id,
                            product_id: d.product_id,
                            label: d.label.clone(),
                        })
                    })
                    .collect();
                let _ = reply.send(nodes);
            }
            Command::ListFabrics { reply } => {
                let fabrics: Result<Vec<crate::FabricInfo>, Error> = self
                    .state
                    .fabrics
                    .iter()
                    .map(|f| {
                        // The same derivation `sole_compressed_fabric_id` names
                        // the fabric's subtype and instance names with.
                        let cfid = matter_crypto::derive_compressed_fabric_id(
                            f.rcac_cert.public_key().as_bytes(),
                            f.fabric_id,
                        )
                        .map_err(|e| Error::Operational(e.to_string()))?;
                        Ok(crate::FabricInfo {
                            fabric_id: f.fabric_id,
                            commissioner_node_id: f.commissioner.node_id,
                            node_count: f.devices.len(),
                            icac_enabled: f.icac.is_some(),
                            compressed_fabric_id: u64::from_be_bytes(cfid),
                        })
                    })
                    .collect();
                let _ = reply.send(fabrics);
            }
            Command::ForgetNode { node_id, reply } => {
                // Drop all LOCAL state for this node — no device round-trip, so
                // it works even when the device is unreachable or already reset.
                let mut removed = false;
                let mut released = Vec::new();
                for fabric in &mut self.state.fabrics {
                    let before = fabric.devices.len();
                    let fabric_id = fabric.fabric_id;
                    fabric.devices.retain(|d| d.node_id != node_id);
                    if fabric.devices.len() != before {
                        removed = true;
                        // Evict the cached session (+ its dead MRP retransmits).
                        if let Some(c) = self.cache.remove(&(fabric_id, node_id)) {
                            released.push(c.session_id);
                        }
                    }
                }
                // Released after the loop, which borrows `self.state`.
                for sid in released {
                    self.release_session(sid);
                }
                // This node's resubscribe waiters are deleted below (the
                // `resubscribes.retain`), so drop them here rather than let
                // `fail_connect_waiters` reschedule them first — that would log
                // "next attempt scheduled" for attempts that will never happen.
                if let Some(waiters) = self.pending_connects.get_mut(&node_id) {
                    waiters.retain(|w| !matches!(w, ConnectWaiter::Resubscribe(_)));
                }
                // Fail any parked waiters and drop the connect bookkeeping for
                // this node. Reuse the existing helper — it removes
                // `connect_inbound`, `connect_routes`, AND `pending_connects`
                // and fails/reschedules each waiter by kind (do NOT hand-roll
                // this; a hand-rolled loop misses `connect_routes`).
                self.fail_connect_waiters(node_id, &Error::Operational("node forgotten".into()));
                // Drop any live subscriptions, scheduled resubscribes, and
                // in-flight pending ops for the node. This is essential to the
                // "no device contact" guarantee: a surviving `SubEntry` would,
                // on its next liveness deadline, drive the resubscribe engine to
                // open a fresh CASE handshake to the very node we just forgot —
                // reintroducing the exact hazard the local-only routing avoids.
                self.remove_subscriptions_for_node(node_id);
                self.resubscribes.retain(|pr| pr.node_id != node_id);
                self.pending.retain(|_, p| p.node_id != node_id);
                // Their advert cooldowns go with the episodes.
                let live = self.resubscribe_episode_sub_ids();
                self.resubscribe_pulled_at
                    .retain(|sub_id, _| live.contains(sub_id));
                let outcome = if removed {
                    match self.durable_save_inputs() {
                        Ok(job) => save_offloaded(job).await.map(|()| true),
                        Err(e) => Err(e),
                    }
                } else {
                    Ok(false)
                };
                let _ = reply.send(outcome);
            }
            Command::SetNodeVidPid {
                node_id,
                vendor_id,
                product_id,
                reply,
            } => {
                let _ = reply.send(
                    self.handle_set_node_vid_pid(node_id, vendor_id, product_id)
                        .await,
                );
            }
            #[cfg(any(feature = "ota", test))]
            Command::ResumptionRecordFor { node_id, reply } => {
                // Same identity binding as the outbound path. Here we are the
                // RESPONDER: the device will present this record's id to our
                // provider server, and accepting it would revive an
                // authorization snapshot taken under a commissioner identity
                // that may no longer hold.
                let result = self
                    .sole_fabric()
                    .map(|f| f.fabric_id)
                    .map(|fabric_id| self.usable_resumption_record(fabric_id, node_id));
                let _ = reply.send(result);
            }
            #[cfg(feature = "ota")]
            Command::StoreResumptionRecord {
                node_id,
                record,
                reply,
            } => {
                let _ = reply.send(self.handle_store_resumption_record(node_id, &record));
            }
            Command::InvalidateResumptionRecords { fabric_id, reply } => {
                let result = self.handle_invalidate_resumption_records(fabric_id).await;
                let _ = reply.send(result);
            }
            Command::PersistIcdRegistration {
                registration,
                reply,
            } => {
                let _ = reply.send(self.handle_persist_icd_registration(registration).await);
            }
            Command::CreateGroup {
                key_set_id,
                epoch_start_time,
                reply,
            } => {
                let _ = reply.send(self.handle_create_group(key_set_id, epoch_start_time).await);
            }
            Command::InvokeGroup {
                group_id,
                key_set_id,
                path,
                fields_tlv,
                reply,
            } => {
                let _ = reply.send(
                    self.handle_invoke_group(group_id, key_set_id, path, &fields_tlv)
                        .await,
                );
            }
            Command::CancelSubscription { key } => {
                self.remove_subscription(key);
                // Also drop the subscription's resubscribe wherever it sits:
                // queued, on the wire (purged, its exchange aborted), or waiting
                // on a connect (its waiter dropped). Nothing of it survives to
                // send a request or re-insert a SubEntry later.
                self.resubscribes.retain(|pr| pr.sub_id != key);
                self.purge_inflight_resubscribe(key).await;
                self.resubscribe_pulled_at.remove(&key);
            }
            Command::ResubscribeNow { node_id, reply } => {
                let _ = reply.send(self.trigger_resubscribe(
                    node_id,
                    TriggerSource::Api,
                    Instant::now(),
                ));
            }
            #[cfg(test)]
            Command::SessionCount { reply } => {
                let _ = reply.send(self.cache.len());
            }
            #[cfg(test)]
            Command::SetResubscribeSchedule {
                node_id,
                retry_count,
                attempt_in,
                reply,
            } => {
                let attempt_at = Instant::now() + attempt_in;
                let mut changed = 0usize;
                for pr in self
                    .resubscribes
                    .iter_mut()
                    .filter(|pr| pr.node_id == node_id)
                {
                    pr.retry_count = retry_count;
                    pr.attempt_at = attempt_at;
                    changed += 1;
                }
                let _ = reply.send(changed);
            }
        }
    }

    async fn handle_create_fabric(&mut self, cfg: &FabricConfig) -> Result<u64, Error> {
        // Refuse a duplicate `fabric_id` before any key generation (issue
        // #110): loading a store that already has this fabric and calling
        // `create_fabric` unconditionally used to push a second `FabricEntry`
        // with the same id, after which `sole_fabric()` sees "multiple
        // fabrics" and every subsequent commission attempt fails opaquely.
        if self
            .state
            .fabrics
            .iter()
            .any(|f| f.fabric_id == cfg.fabric_id)
        {
            return Err(Error::FabricAlreadyExists(cfg.fabric_id));
        }
        // Clock-relative half of the validity check (issue #111's worse cases:
        // a `not_before` far in the future — typically a millisecond timestamp
        // — or an already-expired `not_after`). It lives here rather than in
        // `crate::fabric` so that `create_fabric` stays a pure function of its
        // inputs; this is the layer that already owns a clock reading.
        validate_validity_against_clock(cfg.validity, current_matter_time())?;
        let entry = crate::fabric::create_fabric(cfg, self.rng.as_ref())?;
        let fabric_id = entry.fabric_id;
        self.state.fabrics.push(entry);
        // Durability-critical: the caller must not consider the fabric created
        // (and its private keys safe) until the snapshot is on disk. Serialize
        // under `&self`, then drop the borrow before awaiting the offloaded save.
        let result = match self.durable_save_inputs() {
            Ok(job) => save_offloaded(job).await,
            Err(error) => Err(error),
        };
        if let Err(error) = result {
            self.state.fabrics.pop();
            return Err(error);
        }
        Ok(fabric_id)
    }

    /// Persist an ICD client registration on the sole fabric, replacing any
    /// prior registration for the same device node, then durably save.
    async fn handle_persist_icd_registration(
        &mut self,
        registration: crate::icd::IcdRegistration,
    ) -> Result<(), Error> {
        let fabric = self.sole_fabric_mut()?;
        fabric
            .icd_clients
            .retain(|r| r.node_id != registration.node_id);
        fabric.icd_clients.push(registration);
        let job = self.durable_save_inputs()?;
        save_offloaded(job).await?;
        Ok(())
    }

    /// Kick off a commission on a **spawned task with its own socket**.
    ///
    /// Commissioning is the longest protocol handler (PASE + attestation + CSR +
    /// NOC + operational CASE + config — multiple seconds). Running it inline on
    /// the actor loop would pause every other session's MRP retransmits and
    /// liveness for that whole window (found in the 2026-06-12 audit). Instead we
    /// snapshot the owned inputs, spawn `run_commission_task` on a fresh socket,
    /// and return to the loop immediately; the result arrives later on the
    /// completions channel ([`Self::handle_commission_completion`]), which
    /// persists the device and resolves `reply`. `commission()` establishes only
    /// a transient session it does not hand back (the first post-commission
    /// invoke reconnects), so no session hand-off is needed here.
    fn spawn_commission(
        &mut self,
        setup_payload: matter_commissioning::SetupPayload,
        label: Option<String>,
        reply: oneshot::Sender<Result<crate::NodeInfo, Error>>,
    ) {
        let Some(trust) = self.trust.clone() else {
            let _ = reply.send(Err(Error::NoTrust));
            return;
        };
        let admin_vendor_id = self.admin_vendor_id;
        let snapshot = match self.sole_fabric() {
            Ok(fabric) => match fabric.to_fabric_record() {
                Ok(fabric_record) => Ok((
                    fabric_record,
                    fabric.fabric_id,
                    fabric.commissioner.node_id,
                    fabric.ipk,
                    fabric.commissioner.noc.clone(),
                    fabric.commissioner.operational_pkcs8.clone(),
                    crate::commission::next_device_node_id(fabric),
                )),
                Err(e) => Err(e),
            },
            Err(e) => Err(e),
        };
        let (
            fabric_record,
            fabric_id,
            commissioner_node_id,
            ipk_epoch_key,
            commissioner_noc,
            commissioner_pkcs8,
            assigned_node_id,
        ) = match snapshot {
            Ok(s) => s,
            Err(e) => {
                let _ = reply.send(Err(e));
                return;
            }
        };
        let now = match current_matter_time() {
            Ok(n) => n,
            Err(e) => {
                let _ = reply.send(Err(e));
                return;
            }
        };
        let rng = self.rng.clone();
        let tx = self.commission_tx.clone();
        let multicast_if = self.multicast_if;

        tokio::spawn(async move {
            let result = run_commission_task(
                setup_payload,
                trust,
                fabric_record,
                commissioner_node_id,
                ipk_epoch_key,
                commissioner_noc,
                commissioner_pkcs8,
                assigned_node_id,
                admin_vendor_id,
                now,
                rng,
                multicast_if,
            )
            .await;
            let _ = tx
                .send(CommissionCompletion {
                    fabric_id,
                    result,
                    label,
                    reply,
                })
                .await;
        });
    }

    /// Spawn a BLE/BTP commission on its own task (feature `ble`), mirroring
    /// [`Self::spawn_commission`]: snapshot the same fabric inputs, then
    /// `tokio::spawn` [`crate::ble_commission::run_commission_ble_task`] (which
    /// constructs its own `BleCentral` — the macOS TCC point — plus BTP channel,
    /// UDP socket, and mDNS discovery). The completion is reported over the same
    /// [`CommissionCompletion`] channel as the IP path, so persistence + reply
    /// resolution reuse [`Self::handle_commission_completion`] unchanged. A
    /// btleplug-internal panic in the task drops the `reply`, surfacing to the
    /// caller as [`Error::ControllerStopped`] rather than hanging.
    #[cfg(feature = "ble")]
    fn spawn_commission_ble(
        &mut self,
        setup_payload: matter_commissioning::SetupPayload,
        network: matter_commissioning::NetworkCredentials,
        label: Option<String>,
        reply: oneshot::Sender<Result<crate::NodeInfo, Error>>,
    ) {
        let Some(trust) = self.trust.clone() else {
            let _ = reply.send(Err(Error::NoTrust));
            return;
        };
        let admin_vendor_id = self.admin_vendor_id;
        let snapshot = match self.sole_fabric() {
            Ok(fabric) => match fabric.to_fabric_record() {
                Ok(fabric_record) => Ok((
                    fabric_record,
                    fabric.fabric_id,
                    fabric.commissioner.node_id,
                    fabric.ipk,
                    fabric.commissioner.noc.clone(),
                    fabric.commissioner.operational_pkcs8.clone(),
                    crate::commission::next_device_node_id(fabric),
                )),
                Err(e) => Err(e),
            },
            Err(e) => Err(e),
        };
        let (
            fabric_record,
            fabric_id,
            commissioner_node_id,
            ipk_epoch_key,
            commissioner_noc,
            commissioner_pkcs8,
            assigned_node_id,
        ) = match snapshot {
            Ok(s) => s,
            Err(e) => {
                let _ = reply.send(Err(e));
                return;
            }
        };
        let now = match current_matter_time() {
            Ok(n) => n,
            Err(e) => {
                let _ = reply.send(Err(e));
                return;
            }
        };
        let rng = self.rng.clone();
        let tx = self.commission_tx.clone();

        tokio::spawn(async move {
            let result = crate::ble_commission::run_commission_ble_task(
                setup_payload,
                trust,
                fabric_record,
                commissioner_node_id,
                ipk_epoch_key,
                commissioner_noc,
                commissioner_pkcs8,
                assigned_node_id,
                admin_vendor_id,
                now,
                rng,
                network,
            )
            .await;
            let _ = tx
                .send(CommissionCompletion {
                    fabric_id,
                    result,
                    label,
                    reply,
                })
                .await;
        });
    }

    /// Handle a completed spawned commission: on success persist the
    /// `DeviceEntry` + durably save, then resolve the original `reply`.
    async fn handle_commission_completion(&mut self, completion: CommissionCompletion) {
        let CommissionCompletion {
            fabric_id,
            result,
            label,
            reply,
        } = completion;
        let outcome = match result {
            Ok(commissioned) => {
                let mut device = crate::commission::device_entry_from_commissioned(&commissioned);
                device.label = label;
                // Build the NodeInfo to return. `vendor_id`/`product_id` are
                // `None` here — the controller fills them best-effort via a
                // BasicInformation read after this reply resolves (a device
                // read cannot run from inside the actor's completion handler).
                let info = crate::NodeInfo {
                    node_id: device.node_id,
                    fabric_id,
                    vendor_id: None,
                    product_id: None,
                    label: device.label.clone(),
                };
                if let Some(fabric) = self
                    .state
                    .fabrics
                    .iter_mut()
                    .find(|f| f.fabric_id == fabric_id)
                {
                    fabric.devices.push(device);
                }
                // Durability-critical: report success only after the device
                // entry is durably persisted (same guarantee as the old inline
                // path).
                match self.durable_save_inputs() {
                    Ok(job) => save_offloaded(job).await.map(|()| info),
                    Err(e) => Err(e),
                }
            }
            Err(e) => Err(e),
        };
        let _ = reply.send(outcome);
    }

    /// Persist `vendor_id`/`product_id` onto the commissioned device `node_id`'s
    /// entry (from the controller's post-commission `BasicInformation` read). A
    /// device that is not found is a no-op success — the metadata is enrichment,
    /// not a correctness-critical write, and the commission itself has already
    /// been reported successful. Persists only if a field actually changed.
    async fn handle_set_node_vid_pid(
        &mut self,
        node_id: u64,
        vendor_id: Option<u16>,
        product_id: Option<u16>,
    ) -> Result<(), Error> {
        let mut changed = false;
        for fabric in &mut self.state.fabrics {
            if let Some(device) = fabric.devices.iter_mut().find(|d| d.node_id == node_id) {
                if vendor_id.is_some() && device.vendor_id != vendor_id {
                    device.vendor_id = vendor_id;
                    changed = true;
                }
                if product_id.is_some() && device.product_id != product_id {
                    device.product_id = product_id;
                    changed = true;
                }
                break;
            }
        }
        if !changed {
            return Ok(());
        }
        let job = self.durable_save_inputs()?;
        save_offloaded(job).await
    }

    /// Prepare the inputs for a durable, await-to-completion snapshot save.
    ///
    /// The actual blocking save (`File::create` + `write_all` + `fsync` +
    /// `rename` in the default [`FileStore`](crate::store::FileStore)) is run by
    /// [`save_offloaded`] on the Tokio blocking pool via
    /// [`spawn_blocking`](tokio::task::spawn_blocking), so a multi-millisecond
    /// fsync never runs on the actor task itself. The caller `await`s the
    /// returned save so it only sees success once the bytes are durable, and any
    /// [`StoreError`](crate::store::StoreError) propagates.
    ///
    /// Use this for state changes the caller relies on being durable before the
    /// operation is reported successful: fabric creation and commissioning. For
    /// best-effort updates (e.g. the per-connect address hint) use
    /// [`Self::persist_best_effort`].
    ///
    /// Returns a fully owned [`SaveJob`] to feed to [`save_offloaded`]. The
    /// split is deliberate: serializing under `&mut self` and awaiting the save
    /// are kept in separate statements, and the job borrows nothing from the
    /// actor, so no borrow of the (non-`Sync`) actor is held across the
    /// `.await` — that would make the actor future non-`Send` and so
    /// unspawnable. Callers do `let job = self.durable_save_inputs()?;
    /// save_offloaded(job).await?;`.
    ///
    /// The job also carries the serialize-order sequence, so a concurrently
    /// detached best-effort save cannot overwrite it with older bytes.
    fn durable_save_inputs(&mut self) -> Result<SaveJob, Error> {
        let bytes = snapshot::serialize(&self.state)?;
        Ok(self.save_job(bytes))
    }

    /// Stamp already-serialized snapshot `bytes` with the next sequence and the
    /// shared write gate. The single place [`Actor::snapshot_seq`] advances, so
    /// every save path — durable and best-effort — is ordered against the rest.
    fn save_job(&mut self, bytes: Vec<u8>) -> SaveJob {
        self.snapshot_seq += 1;
        SaveJob {
            store: self.store.clone(),
            bytes,
            seq: self.snapshot_seq,
            gate: self.save_gate.clone(),
        }
    }

    /// Persist the snapshot best-effort, off the actor loop, without awaiting.
    ///
    /// The serialized bytes are handed to [`spawn_blocking`](tokio::task::spawn_blocking)
    /// and the join handle is dropped: the actor neither blocks on the fsync nor
    /// waits for its result. Use this only for updates a failed write may safely
    /// lose — currently just the per-connect last-known-address hint, which is a
    /// cache the controller can rebuild via mDNS. Durability-critical state must
    /// use [`Self::durable_save_inputs`] + [`save_offloaded`] (await-to-durable)
    /// instead.
    ///
    /// Detached does not mean unordered: the job carries its serialize-time
    /// sequence, so if a durable save lands first this write is skipped rather
    /// than rolling persisted state back to these older bytes
    /// ([`SaveJob::run`]).
    fn persist_best_effort(&mut self) {
        // Serialization failure here is purely best-effort state; dropping it
        // must not abort the connection that triggered it.
        let Ok(bytes) = snapshot::serialize(&self.state) else {
            return;
        };
        let job = self.save_job(bytes);
        // Fire-and-forget: detach the blocking save. The actor loop returns
        // immediately and never observes the fsync latency or its outcome.
        // (No logging facility is wired into this crate yet; a write error is
        // silently dropped, which is acceptable for a rebuildable address cache.)
        drop(tokio::task::spawn_blocking(move || {
            let _ = job.run();
        }));
    }

    /// The sole fabric, or an error if not exactly one (single-fabric only;
    /// multi-fabric `fabric(id).node(id)` addressing is deferred).
    fn sole_fabric(&self) -> Result<&crate::state::FabricEntry, Error> {
        match self.state.fabrics.as_slice() {
            [one] => Ok(one),
            [] => Err(Error::NotCommissioned("no fabric created yet".into())),
            _ => Err(Error::NotCommissioned(
                "multiple fabrics; fabric(id).node(id) addressing is not in M8.2".into(),
            )),
        }
    }

    /// The sole fabric (mutable), or an error if not exactly one. Mirrors
    /// [`Self::sole_fabric`] for the group-key mutation paths.
    fn sole_fabric_mut(&mut self) -> Result<&mut crate::state::FabricEntry, Error> {
        match self.state.fabrics.as_mut_slice() {
            [one] => Ok(one),
            [] => Err(Error::NotCommissioned("no fabric created yet".into())),
            _ => Err(Error::NotCommissioned(
                "multiple fabrics; fabric(id).node(id) addressing is not in M8.2".into(),
            )),
        }
    }

    /// Mint a fresh group key set: generate a 16-byte epoch key from the CSPRNG,
    /// append a [`GroupKeySetConfig`](crate::state::GroupKeySetConfig) to the
    /// sole fabric's `group_keys`, durably persist the snapshot, and return the
    /// corresponding [`GroupKeySet`](crate::GroupKeySet) for the caller to
    /// program onto devices (`Node::write_group_key_set`).
    ///
    /// The epoch key never leaves the controller as plaintext on the wire — the
    /// returned `GroupKeySet` carries it so the caller can run the (CASE-secured)
    /// `KeySetWrite`; the key set is stored locally for outbound group encryption.
    async fn handle_create_group(
        &mut self,
        key_set_id: u16,
        epoch_start_time: u64,
    ) -> Result<crate::GroupKeySet, Error> {
        // Generate the 16-byte epoch key from the CSPRNG. The fixed-size array
        // type `[u8; 16]` guarantees the buffer is exactly 16 bytes.
        let mut epoch_key = [0u8; 16];
        matter_crypto::random_bytes(&mut epoch_key)
            .map_err(|e| Error::Operational(format!("group epoch-key generation failed: {e}")))?;

        // Upsert the persisted key-set config on the sole fabric. Re-creating
        // an existing `key_set_id` REPLACES it: a plain append would leave the
        // old epoch key first in the list, and the outbound path would keep
        // encrypting under the stale key while devices hold the newly
        // provisioned one — every group send would then fail to decrypt on the
        // device (found on real hardware, 2026-07-20). The retain also heals
        // stores already poisoned with duplicates by older builds.
        let fabric = self.sole_fabric_mut()?;
        fabric.group_keys.retain(|k| k.key_set_id != key_set_id);
        fabric.group_keys.push(crate::state::GroupKeySetConfig::new(
            key_set_id,
            epoch_key,
            epoch_start_time,
        ));

        // Durability-critical: the caller relies on the key set being persisted
        // before it programs the key onto devices (so a crash mid-provision can
        // resume from a known key). Serialize under `&self`, then drop the
        // borrow before awaiting the offloaded save.
        let job = self.durable_save_inputs()?;
        save_offloaded(job).await?;

        Ok(crate::GroupKeySet::new(
            key_set_id,
            epoch_key.to_vec(),
            epoch_start_time,
        ))
    }

    /// The fabric's derived group-key material, computed on first use and
    /// re-derived whenever the inputs it was derived from change.
    ///
    /// Four HKDFs (compressed fabric id → operational group key → group session
    /// id, plus the privacy key the framing layer would otherwise derive per
    /// packet) are pure overhead on a burst of group commands, since all four
    /// are a pure function of `(epoch_key, root_public_key, fabric_id)`.
    /// `fabric_id` is the cache key and the other two are compared here on
    /// every send — see [`GroupKeyCacheEntry`] for why that pair is the
    /// complete invalidation rule. A rotated key set (`create_group` /
    /// `KeySetWrite`) therefore re-derives before anything is sent under it.
    ///
    /// # Errors
    ///
    /// [`Error::Operational`] if any derivation fails (not expected: the inputs
    /// are fixed-size key material).
    fn group_keys_for(
        &mut self,
        fabric_id: u64,
        root_public_key: &[u8; 65],
        epoch_key: [u8; 16],
    ) -> Result<&GroupKeyCacheEntry, Error> {
        use std::collections::hash_map::Entry;
        match self.group_key_cache.entry(fabric_id) {
            // Hit: same fabric, same epoch key, same root key — every derived
            // value below is still exactly what a fresh derivation would
            // produce.
            Entry::Occupied(e)
                if e.get().epoch_key == epoch_key
                    && &e.get().root_public_key == root_public_key =>
            {
                Ok(e.into_mut())
            }
            // Miss (cold), or stale because the key set was rotated or the
            // fabric's root changed: derive the whole set.
            slot => {
                let compressed_fabric_id =
                    matter_crypto::derive_compressed_fabric_id(root_public_key, fabric_id)
                        .map_err(|e| Error::Operational(format!("compressed fabric id: {e}")))?;
                let op_group_key =
                    matter_crypto::derive_operational_ipk(&epoch_key, &compressed_fabric_id)
                        .map_err(|e| Error::Operational(format!("operational group key: {e}")))?;
                let group_session_id = matter_crypto::derive_group_session_id(&op_group_key)
                    .map_err(|e| Error::Operational(format!("group session id: {e}")))?;
                let privacy_key = matter_crypto::derive_group_privacy_key(&op_group_key)
                    .map_err(|e| Error::Operational(format!("group privacy key: {e}")))?;
                let fresh = GroupKeyCacheEntry {
                    epoch_key,
                    root_public_key: *root_public_key,
                    op_group_key,
                    group_session_id,
                    privacy_key,
                };
                // Replace the stale entry (or fill the empty slot) — the map
                // holds at most one entry per fabric either way.
                Ok(match slot {
                    Entry::Occupied(mut e) => {
                        e.insert(fresh);
                        e.into_mut()
                    }
                    Entry::Vacant(e) => e.insert(fresh),
                })
            }
        }
    }

    /// Fire-and-forget multicast group invoke (see [`Command::InvokeGroup`]).
    ///
    /// Derives the operational group key + group session id from the persisted
    /// `key_set_id`, allocates the next outbound group counter from a durably
    /// reserved block — **extending and persisting the reservation before
    /// sending** whenever the block is exhausted, since a reused counter
    /// weakens replay protection — builds a group-secured `InvokeRequest`, and
    /// multicasts it to the group's site-local address. Returns `Ok(())` as soon
    /// as the datagram is handed to the socket — no response is awaited.
    async fn handle_invoke_group(
        &mut self,
        group_id: u16,
        key_set_id: u16,
        path: matter_interaction::CommandPath,
        fields_tlv: &[u8],
    ) -> Result<(), Error> {
        // --- Gather everything from the sole fabric into owned locals so no
        // borrow of `self` is held across the persist `.await` below. ---
        let (fabric_id, source_node_id, root_public_key, epoch_key, ceiling) = {
            let fabric = self.sole_fabric()?;
            // (a) Look up the epoch key for this key set. Take the LAST match:
            // `create_group` upserts so duplicates no longer occur, but stores
            // written by older builds may still carry several entries for one
            // `key_set_id` — the most recently appended one is the key that was
            // last programmed onto devices via `KeySetWrite`, so it is the only
            // one the devices can decrypt.
            let epoch_key = fabric
                .group_keys
                .iter()
                .rfind(|k| k.key_set_id == key_set_id)
                .map(|k| k.epoch_key)
                .ok_or(Error::GroupNotProvisioned(key_set_id))?;
            // The RCAC root public key (SEC1 uncompressed) for the compressed
            // fabric id derivation (read straight off the stored root cert, as
            // the CASE credentials path does).
            let root_public_key = *fabric.rcac_cert.public_key().as_bytes();
            // (f) The persisted field is the reserved CEILING (see
            // `GROUP_COUNTER_BLOCK`), read here under the same borrow as the
            // rest. Exhaustion is detected at the reservation below — the only
            // place the ceiling can fail to advance — so there is no separate
            // pre-check: a ceiling of `u32::MAX` still has its last block's
            // counters left to burn.
            (
                fabric.fabric_id,
                fabric.commissioner.node_id,
                root_public_key,
                epoch_key,
                fabric.outbound_group_counter,
            )
        };

        // (b-e) Crypto derivations (reuse E2; never hand-rolled), computed once
        // per epoch key and cached per fabric — see `group_keys_for`.
        let entry = self.group_keys_for(fabric_id, &root_public_key, epoch_key)?;
        let op_group_key = entry.op_group_key;
        let group_session_id = entry.group_session_id;
        let privacy_key = entry.privacy_key;
        let mcast = matter_crypto::group_multicast_ipv6(fabric_id, group_id);

        // (f) Take the next counter from the reserved block, and PERSIST A NEW
        // RESERVATION BEFORE SENDING only when the block is exhausted.
        //
        // A counter reused after a crash would let an attacker replay an old
        // group message, so no datagram may carry a counter the store does not
        // already cover. The serialized `outbound_group_counter` therefore holds
        // the reservation CEILING, never the live value: any snapshot taken by
        // any save path — including a detached best-effort one that fires
        // mid-block — is safe, because a restart resumes at the ceiling, above
        // every counter this run could have sent.
        //
        // The live counter (`self.group_counters`) is deliberately NOT
        // serialized: persisting it is exactly the per-send fsync this replaces.
        //
        // No reentrancy: `handle_invoke_group` runs in a `select!` arm body on
        // the actor loop, which runs to completion, so no second group send can
        // interleave with the `.await` below and slip past the reservation.
        let next = *self.group_counters.entry(fabric_id).or_insert(ceiling);
        if next >= ceiling {
            // Extend the reservation. `checked_add` guards the wrap; when the
            // block would overflow we still reserve the remaining tail up to
            // `u32::MAX`, and only a `next` already AT `u32::MAX` is exhausted.
            let new_ceiling = next
                .checked_add(GROUP_COUNTER_BLOCK)
                .or_else(|| (next < u32::MAX).then_some(u32::MAX))
                .ok_or_else(|| {
                    Error::Operational("group counter exhausted — re-key the group".into())
                })?;
            self.sole_fabric_mut()?.outbound_group_counter = new_ceiling;
            let saved = match self.durable_save_inputs() {
                Ok(job) => save_offloaded(job).await,
                Err(e) => Err(e),
            };
            if let Err(e) = saved {
                // The raised ceiling never reached the store. Roll it back so a
                // later send cannot treat it as reserved — leaving it raised
                // in memory would hand out counters a crash would hand out
                // again. Nothing above `ceiling` was sent, so resuming there
                // stays sound.
                //
                // The lookup cannot fail: the identical call succeeded a few
                // lines above and the fabric set cannot change across the
                // awaited save (arm-body execution — see the reentrancy note).
                // It stays fallible-but-total rather than `?` so the store's
                // error, not a lookup error, is what the caller sees.
                debug_assert!(
                    self.sole_fabric().is_ok(),
                    "the fabric that was just reserved against must still exist"
                );
                if let Ok(fabric) = self.sole_fabric_mut() {
                    fabric.outbound_group_counter = ceiling;
                }
                return Err(e);
            }
        }
        // `saturating_add` cannot actually saturate below `u32::MAX`: `next` is
        // strictly below the (freshly extended) ceiling here, and `next ==
        // u32::MAX` already returned the exhaustion error above.
        self.group_counters
            .insert(fabric_id, next.saturating_add(1));
        let counter = next;

        // (g) Build the InvokeRequest IM payload (SuppressResponse=true — group
        // commands are unacknowledged) and a fresh-exchange protocol header.
        let payload = matter_interaction::build_invoke_request_group(path, fields_tlv);
        let mut eid = [0u8; 2];
        matter_crypto::random_bytes(&mut eid)
            .map_err(|e| Error::Operational(format!("exchange-id generation failed: {e}")))?;
        let protocol_header = ProtocolHeader {
            // The controller initiates the group exchange; no ack is piggybacked
            // (group sends are unreliable, so `ack_counter` is `None`).
            exchange_flags: matter_transport::ExchangeFlags::INITIATOR,
            opcode: crate::node::OP_INVOKE_REQUEST,
            exchange_id: u16::from_le_bytes(eid),
            protocol_id: ProtocolId::INTERACTION_MODEL,
            ack_counter: None,
        };

        // (h) Encode the group-secured wire message (`matter-transport`'s framing).
        // The privacy-key variant: ours is cached above, so the framing layer
        // does not re-derive it for every packet.
        let wire = matter_transport::encode_group_secured_with_privacy_key(
            &op_group_key,
            &privacy_key,
            group_session_id,
            source_node_id,
            group_id,
            counter,
            &protocol_header,
            &payload,
        )?;

        // (i) Multicast to the group address on the Matter group port (5540).
        // The transport's multicast hop limit was raised at bind time.
        // Egress interface for the admin-local `ff35:` group address: on a
        // multi-homed/macOS host the kernel resolves the outgoing interface from
        // the destination's scope id; without it the send fails with "No route
        // to host". The builder's `multicast_interface` supplies it; the
        // `MATTER_MULTICAST_IF` env var remains a compat fallback
        // (0 = kernel default).
        let scope_id = self.multicast_if.filter(|&i| i != 0).unwrap_or_else(|| {
            std::env::var("MATTER_MULTICAST_IF")
                .ok()
                .and_then(|s| s.parse::<u32>().ok())
                .unwrap_or(0)
        });
        let dest = SocketAddr::V6(std::net::SocketAddrV6::new(
            mcast,
            MATTER_GROUP_PORT,
            0,
            scope_id,
        ));
        self.transport
            .send_to(&wire, dest)
            .await
            .map_err(|e| Error::Operational(format!("group send: {e}")))?;

        // (j) Fire-and-forget: no pending, no MRP, no response awaited.
        Ok(())
    }

    /// Queue `waiter` behind an off-loop connect to `node_id`, starting the
    /// connect if this is the first waiter. Concurrent work targeting
    /// the same not-yet-connected node coalesces onto a single handshake.
    fn enqueue_connect_waiter(&mut self, fabric_id: u64, node_id: u64, waiter: ConnectWaiter) {
        let already_connecting = self.pending_connects.contains_key(&node_id);
        self.pending_connects
            .entry(node_id)
            .or_default()
            .push(waiter);
        if !already_connecting {
            self.spawn_connect(fabric_id, node_id);
        }
    }

    /// Start a connect to `node_id`: look its operational record up on the
    /// actor's injected discovery and, once found, spawn the CASE handshake on a
    /// task ([`run_connect_task`]) whose I/O flows through the actor's socket.
    ///
    /// The lookup NEVER blocks the loop: the connect parks as a
    /// [`PendingResolve`] and is settled by a single non-sleeping
    /// [`Self::drive_pending_resolves`] pass — which usually resolves it on the
    /// spot, since the record is typically already in the browse's buffer (and
    /// which is what keeps the injected-discovery tests synchronous). Otherwise
    /// it stays parked for the timer arm. Previously this polled inline for the
    /// whole [`RESOLVE_DEADLINE`], stalling every other session behind one
    /// unreachable device.
    ///
    /// When the subtype browse was already held (usually by the resubscribe
    /// watch) and the target has no fresh cached record, the browse's records
    /// are first replayed through a short-lived second handle
    /// ([`Self::replay_subtype_records`]), as a freshly opened browse would.
    ///
    /// Only a credential/clock/query-setup failure fails the parked waiters here;
    /// a device that simply never answers fails at its deadline instead.
    fn spawn_connect(&mut self, fabric_id: u64, node_id: u64) {
        // Naming the record needs ONLY the compressed fabric id, so derive just
        // that — the full credential build (signer reconstruction from PKCS#8,
        // IPK derivation, cert clones) happens once, in `finish_spawn_connect`,
        // which may run many seconds later and wants a fresh validation clock.
        let compressed = match self.sole_compressed_fabric_id() {
            Ok(c) => c,
            Err(e) => {
                self.fail_connect_waiters(node_id, &e);
                return;
            }
        };
        let target = matter_commissioning::driver::operational_instance_name(compressed, node_id);
        tracing::debug!(
            target: "matter_controller::actor",
            node_id,
            instance = %target,
            browse_open = self.resolve_query.is_some(),
            subtype_browse_open = self.resolve_query_fabric.is_some(),
            subtype = %matter_transport::operational_fabric_subtype(compressed),
            "connect: resolving operational record",
        );

        // The fabric subtype ALONE to begin with (see `resolve_query_fabric`):
        // it narrows the browse to our own nodes, which is what makes a resolve
        // land promptly on a link crowded with other fabrics' operational
        // records (issue #113). The base type is deliberately NOT opened next to
        // it — that would re-discover every instance on the link and starve our
        // nodes in the resolver's shared resolution queue, undoing the
        // narrowing. It is armed as a delayed fallback instead
        // (`resolve_base_after`, opened by `drive_pending_resolves`).
        //
        // A failure to open EITHER browse is only fatal if we end up with
        // neither: a daemon that refuses the subtype must not cost us the
        // base-type resolve that works today, so that case opens the base
        // browse at once rather than after the window — there is nothing left
        // to wait for.
        let mut open_error: Option<Error> = None;
        let subtype_was_held = self.resolve_query_fabric.is_some();
        if self.resolve_query_fabric.is_none() {
            if let Err(e) = self.open_subtype_browse(compressed) {
                tracing::debug!(
                    target: "matter_controller::actor",
                    node_id,
                    error = %e,
                    "connect: fabric-subtype browse could not be opened; \
                     falling back to the base-type browse",
                );
                open_error = Some(Error::from(
                    matter_commissioning::driver::DriverError::Transport(e),
                ));
            }
        }
        if self.resolve_query.is_none() {
            if self.resolve_query_fabric.is_some() {
                // Subtype browse up: defer the base type. Only arm the deadline
                // if it is not already armed, so a second connect parking behind
                // a first cannot push the first's fallback further out.
                self.resolve_base_after
                    .get_or_insert_with(|| Instant::now() + SUBTYPE_ONLY_WINDOW);
            } else {
                match self.discovery.query(ServiceKind::Operational) {
                    Ok(h) => self.resolve_query = Some(h),
                    Err(e) => {
                        open_error = Some(Error::from(
                            matter_commissioning::driver::DriverError::Transport(e),
                        ));
                    }
                }
            }
        }
        if self.resolve_query.is_none() && self.resolve_query_fabric.is_none() {
            let err = open_error.unwrap_or_else(|| {
                Error::from(matter_commissioning::driver::DriverError::Discovery(
                    "no mDNS browse could be opened".to_string(),
                ))
            });
            self.fail_connect_waiters(node_id, &err);
            return;
        }
        // A browse held from before this connect (usually the resubscribe
        // watch) will not hand us records it already delivered; a freshly
        // opened one replays them by itself. See `replay_subtype_records`.
        if subtype_was_held
            && self.resolve_query_fabric_cfid == Some(compressed)
            && !self.has_fresh_record(&target)
        {
            self.replay_subtype_records(compressed, node_id);
        }
        self.park_resolve(fabric_id, node_id, target);
        // Settle immediately rather than draining the browse here: every
        // `poll_results` call CONSUMES the records it returns, so a drain that
        // only looked for `target` would silently discard records other parked
        // resolves are waiting on. One settle pass owns every drain — and it
        // also consults `seen_records`, so a record drained before this connect
        // existed still resolves it on the spot.
        self.drive_pending_resolves();
    }

    /// Park an unresolved connect for the timer arm, with the
    /// [`RESOLVE_DEADLINE`] budget. The node's waiters stay in
    /// `pending_connects` and are resolved when the record lands or the deadline
    /// passes.
    ///
    /// Re-arms the polling anchor when this is the FIRST entry to park.
    /// `next_resolve_poll` is only consulted while `pending_resolves` is
    /// non-empty, so between resolves it goes stale (an instant far in the
    /// past); becoming due the moment the list refills would make
    /// [`Self::run`]'s overdue-timer guard spend one pass on a poll that was
    /// just performed. Re-arming here makes the invariant "the anchor is fresh
    /// whenever `pending_resolves` becomes non-empty" hold locally, instead of
    /// resting on the caller happening to call
    /// [`Self::drive_pending_resolves`] (which re-arms as its first statement)
    /// afterwards. Entries that join a non-empty list leave the existing anchor
    /// alone, so parking a second resolve cannot postpone the first's poll.
    fn park_resolve(&mut self, fabric_id: u64, node_id: u64, target: String) {
        if self.pending_resolves.is_empty() {
            self.next_resolve_poll = Instant::now() + RESOLVE_POLL_INTERVAL;
        }
        tracing::debug!(
            target: "matter_controller::actor",
            node_id,
            instance = %target,
            deadline_secs = RESOLVE_DEADLINE.as_secs(),
            "resolve parked on the mDNS poll arm",
        );
        self.pending_resolves.push(PendingResolve {
            fabric_id,
            node_id,
            target,
            deadline: Instant::now() + RESOLVE_DEADLINE,
        });
    }

    /// Whether `seen_records` holds an entry for `instance_name` that is still
    /// inside [`SEEN_RECORD_TTL`] — i.e. one the next settle pass would match.
    /// An older entry is about to be aged out by that pass's
    /// [`record_seen`](Self::record_seen), so it counts as absent.
    fn has_fresh_record(&self, instance_name: &str) -> bool {
        let now = Instant::now();
        self.seen_records
            .get(&Self::record_key(instance_name))
            .is_some_and(|r| now.saturating_duration_since(r.seen) < SEEN_RECORD_TTL)
    }

    /// Re-read the held subtype browse's records through a second, short-lived
    /// handle, for a connect whose target has no fresh `seen_records` entry.
    ///
    /// Why it is needed: mdns-sd emits `ServiceResolved` only for a new or
    /// changed record, and `MdnsSdDiscovery` replays its per-browse `surfaced`
    /// cache only to a **newly attached** handle. While the resubscribe watch
    /// holds the subtype browse, a healthy node's record is drained once,
    /// then ages out of `seen_records` after [`SEEN_RECORD_TTL`]; unchanged
    /// refreshes emit nothing. A connect that merely reused the held handle
    /// would then park, wait out [`SUBTYPE_ONLY_WINDOW`], and open the base-type
    /// fallback — whose eventual stop wipes the daemon's SRV/TXT records for
    /// every instance. Before the watch existed every such connect opened a
    /// fresh browse and got the replay; this restores it.
    ///
    /// Attaching a second handle to the same subtype is cheap and safe: the
    /// adapter shares one daemon browse per service type and seeds the new
    /// handle from `surfaced`, and because the held handle stays attached,
    /// stopping this one releases only the handle — the daemon browse and its
    /// cache survive. The held handle, its cfid, and the advert quiet window
    /// are not touched.
    ///
    /// What is replayed is the adapter's mirror of the daemon's **live** cache:
    /// an instance whose PTR/SRV expired or that sent a goodbye has been
    /// dropped from it, so a replayed record is bounded by its own mDNS TTL —
    /// not by [`SEEN_RECORD_TTL`], which says nothing about a record that is
    /// stamped as it is cached. A replayed record whose instance already has a
    /// fresh `seen_records` entry ([`Self::has_fresh_record`]) is skipped, so
    /// the replay never overwrites a fresher entry or re-stamps a live one.
    /// The rest go through [`record_seen`](Self::record_seen) like any drain —
    /// address filtering applies and each is stamped now — and the caller's
    /// settle pass then matches the target against the cache. Found
    /// events are never replayed to a new handle, but this drain may fan new
    /// ones out; each also reached the held handle, which
    /// [`Self::poll_advert_found`] reads, so this handle's copy is discarded.
    ///
    /// A failed attach is logged at `debug` and otherwise ignored: the connect
    /// falls through to the parked resolve exactly as before. A handle equal
    /// to one already held is not an independent attach — there is no replay
    /// to take, and draining its found events or stopping it would eat the
    /// watch's adverts or tear the watch down — so it is left alone.
    fn replay_subtype_records(&mut self, compressed_fabric_id: [u8; 8], node_id: u64) {
        let handle = match self
            .discovery
            .query_operational_fabric(compressed_fabric_id)
        {
            Ok(h) => h,
            Err(e) => {
                tracing::debug!(
                    target: "matter_controller::actor",
                    node_id,
                    error = %e,
                    "connect: second subtype handle for the replay could not be \
                     attached; resolving on the held browse alone",
                );
                return;
            }
        };
        if self.resolve_query_fabric == Some(handle) || self.resolve_query == Some(handle) {
            return;
        }
        let replayed = self.discovery.poll_results(handle);
        let _ = self.discovery.poll_found(handle);
        self.discovery.stop_query(handle);
        let replayed_count = replayed.len();
        let services: Vec<matter_transport::MatterService> = replayed
            .into_iter()
            .filter(|svc| !self.has_fresh_record(&svc.instance_name))
            .collect();
        tracing::debug!(
            target: "matter_controller::actor",
            node_id,
            replayed = replayed_count,
            cached = services.len(),
            "connect: target not cached; replayed the held subtype browse \
             through a short-lived second handle",
        );
        self.record_seen(&services, Instant::now(), BROWSE_SUBTYPE);
    }

    /// `seen_records` key for an operational instance name. Matter instance
    /// names are hex, and DNS-SD comparison is case-insensitive, so lowercasing
    /// gives the same match the inline resolver's `eq_ignore_ascii_case` did.
    fn record_key(instance_name: &str) -> String {
        instance_name.to_ascii_lowercase()
    }

    /// Fold one browse drain into `seen_records`: age out stale entries, then
    /// store each record reduced to `(peer, peer_mrp)`.
    ///
    /// Address selection mirrors
    /// `matter_commissioning::driver::resolve_operational_with_mrp`'s per-poll
    /// body exactly (same
    /// [`preferred_address`](matter_commissioning::driver::preferred_address)
    /// routability pick, same `peer_mrp_config`) so the timer-driven path dials
    /// what the inline resolve would have dialled. A record with no usable
    /// address is dropped rather than cached as an un-dialable hit.
    ///
    /// `source` names the browse the records came from ([`BROWSE_SUBTYPE`] or
    /// [`BROWSE_BASE`]) and is carried into the cache purely so the resolve that
    /// a record settles can report which browse produced it.
    fn record_seen(
        &mut self,
        services: &[matter_transport::MatterService],
        now: Instant,
        source: &'static str,
    ) {
        self.seen_records
            .retain(|_, r| now.saturating_duration_since(r.seen) < SEEN_RECORD_TTL);
        if !services.is_empty() {
            // Field expressions are only evaluated when the callsite is
            // enabled, so the `collect` costs nothing without a subscriber.
            tracing::debug!(
                target: "matter_controller::actor",
                browse = source,
                count = services.len(),
                instances = ?services
                    .iter()
                    .map(|s| s.instance_name.as_str())
                    .collect::<Vec<_>>(),
                "operational browse drained",
            );
        }
        for svc in services {
            let Some(addr) = matter_commissioning::driver::preferred_address(&svc.addresses) else {
                tracing::debug!(
                    target: "matter_controller::actor",
                    browse = source,
                    instance = %svc.instance_name,
                    addresses = ?svc.addresses,
                    "operational record ignored: no routable address",
                );
                continue;
            };
            let key = Self::record_key(&svc.instance_name);
            // Make room for a genuinely new instance by dropping the oldest.
            if self.seen_records.len() >= SEEN_RECORD_CAP && !self.seen_records.contains_key(&key) {
                let oldest = self
                    .seen_records
                    .iter()
                    .min_by_key(|(_, r)| r.seen)
                    .map(|(k, _)| k.clone());
                if let Some(k) = oldest {
                    self.seen_records.remove(&k);
                }
            }
            // Keep the browse that FIRST surfaced this instance (while the entry
            // is alive): a record both browses carry would otherwise always be
            // credited to whichever was polled last, which is the opposite of
            // what the diagnostic is for.
            let source = self
                .seen_records
                .get(&key)
                .map_or(source, |existing| existing.source);
            self.seen_records.insert(
                key,
                SeenRecord {
                    peer: SocketAddr::new(addr, svc.port),
                    peer_mrp: svc.peer_mrp_config(),
                    seen: now,
                    source,
                },
            );
        }
    }

    /// Last act of [`Self::run`]: abandon any parked resolve and release the
    /// shared mDNS browses — the subtype one **unconditionally**.
    ///
    /// Dropping the actor is NOT enough. With a caller-supplied daemon
    /// (`MdnsSdDiscovery::with_daemon`, `owns_daemon == false`) nothing ever
    /// stops the browse, so a controller dropped mid-resolve would leave a
    /// `_matter._tcp` browse running on that shared daemon forever. The same
    /// holds for the resubscribe watch: subscriptions may still be waiting, but
    /// nothing will poll the browse again.
    fn shutdown_discovery(&mut self) {
        self.pending_resolves.clear();
        self.release_resolve_query_if_idle();
        self.close_subtype_browse();
    }

    /// Drop the shared operational browses once nothing needs them, so an idle
    /// controller holds no mDNS query open.
    ///
    /// The **base-type** browse goes as soon as no resolve is parked —
    /// unchanged, because a base browse left running beside the subtype one
    /// re-discovers every instance on the link and starves the resolver
    /// (#113, [`SUBTYPE_ONLY_WINDOW`]).
    ///
    /// The **fabric-subtype** browse goes only if, in addition, no subscription
    /// is waiting to be re-established ([`Self::resubscribe_watch_needed`]):
    /// while one is, the subtype browse is the resubscribe watch, which listens
    /// for the device to re-announce itself.
    fn release_resolve_query_if_idle(&mut self) {
        if !self.pending_resolves.is_empty() {
            return;
        }
        // Disarm the delayed fallback along with the browses. Nothing is
        // waiting on a record any more, so opening a base-type browse now
        // would serve no resolve — and the next connect to park arms a fresh
        // window, giving its subtype browse the same clear run at it.
        self.resolve_base_after = None;
        if let Some(base) = self.resolve_query.take() {
            // An injected `Discovery` that keeps the trait default for
            // `query_operational_fabric` hands back the same handle for both
            // browses. Stopping it here would also stop the subtype browse the
            // watch may still hold, so a shared handle is left to the subtype
            // release (below, or the watch's later one), which stops it once.
            if self.resolve_query_fabric != Some(base) {
                self.discovery.stop_query(base);
            }
        }
        if !self.resubscribe_watch_needed() {
            self.close_subtype_browse();
        }
    }

    /// The sole fabric's compressed fabric id: the value that names both its
    /// nodes' operational instance names and its DNS-SD subtype.
    ///
    /// # Errors
    ///
    /// [`Error::NotCommissioned`] unless exactly one fabric exists;
    /// [`Error::Operational`] if the derivation fails.
    fn sole_compressed_fabric_id(&self) -> Result<[u8; 8], Error> {
        let fabric = self.sole_fabric()?;
        matter_crypto::derive_compressed_fabric_id(
            fabric.rcac_cert.public_key().as_bytes(),
            fabric.fabric_id,
        )
        .map_err(|e| Error::Operational(e.to_string()))
    }

    /// Open the fabric-subtype browse and hold it as `resolve_query_fabric`.
    ///
    /// The ONE place a subtype browse is opened: by [`Self::spawn_connect`] for
    /// a parked resolve, and by the resubscribe watch. Going through one helper
    /// is what lets both openers record the same bookkeeping, so a browse
    /// opened for a connect is recognised by the watch instead of being closed
    /// and reopened by it.
    ///
    /// The caller holds no subtype handle (`resolve_query_fabric` is `None`).
    ///
    /// # Errors
    ///
    /// The discovery's error if the browse cannot be opened; nothing is
    /// recorded then.
    fn open_subtype_browse(
        &mut self,
        compressed_fabric_id: [u8; 8],
    ) -> matter_transport::Result<()> {
        let handle = self
            .discovery
            .query_operational_fabric(compressed_fabric_id)?;
        self.resolve_query_fabric = Some(handle);
        self.resolve_query_fabric_cfid = Some(compressed_fabric_id);
        // The daemon flushes its cached PTRs to a fresh browse as found
        // events; those are not adverts.
        self.advert_quiet_until = Some(Instant::now() + ADVERT_QUIET_WINDOW);
        Ok(())
    }

    /// Stop the fabric-subtype browse, if one is held, and forget it.
    ///
    /// Not stopped while the base-type handle is the very same handle (an
    /// injected `Discovery` that keeps the trait default for
    /// `query_operational_fabric` returns one handle for both): the base
    /// release stops it then, once.
    ///
    /// Also drops the watch's re-query schedule and any post-re-query fast
    /// drain window: every close path goes through here, so a reopened watch
    /// always starts at [`ADVERT_REQUERY_FIRST`] on the 1 s drain cadence.
    fn close_subtype_browse(&mut self) {
        self.resolve_query_fabric_cfid = None;
        self.advert_quiet_until = None;
        self.watch_requery_at = None;
        self.requery_fast_drain_until = None;
        if let Some(handle) = self.resolve_query_fabric.take() {
            if self.resolve_query != Some(handle) {
                self.discovery.stop_query(handle);
            }
        }
    }

    /// Every subscription currently in a resubscribe episode, wherever it sits,
    /// as `(sub id, node id, the consumer's sink)`:
    ///
    /// - **queued** in `resubscribes`, waiting for its attempt time;
    /// - **in flight** as a `PendingReply::Subscribe` with no reply channel (a
    ///   `SubscribeRequest` sent, its response not yet in);
    /// - **connecting** as a `ConnectWaiter::Resubscribe` behind a CASE connect.
    ///
    /// These three are the complete set, except for the one entry
    /// `attempt_resubscribe` is holding at that instant: `drive_resubscribes`
    /// takes due entries out of the queue one at a time, only as it attempts
    /// each, and `attempt_resubscribe` puts the entry into one of the other two
    /// (or back in the queue) before anything that consults this set can run.
    /// The only such path inside an attempt — `enqueue_connect_waiter` →
    /// `spawn_connect` → `drive_pending_resolves`, which can run the advert
    /// path — starts after the waiter is already on `pending_connects`. The
    /// actor is single-threaded, so nothing else runs in between.
    fn resubscribe_episode_entries(&self) -> impl Iterator<Item = (SubId, u64, &ReportSink)> + '_ {
        let queued = self
            .resubscribes
            .iter()
            .map(|pr| (pr.sub_id, pr.node_id, &pr.tx));
        let in_flight = self.pending.values().filter_map(|p| match &p.reply {
            PendingReply::Subscribe {
                sub_id,
                reply: None,
                node_id,
                report_tx,
                ..
            } => Some((*sub_id, *node_id, report_tx)),
            _ => None,
        });
        let connecting =
            self.pending_connects
                .values()
                .flatten()
                .filter_map(|waiter| match waiter {
                    ConnectWaiter::Resubscribe(pr) => Some((pr.sub_id, pr.node_id, &pr.tx)),
                    _ => None,
                });
        queued.chain(in_flight).chain(connecting)
    }

    /// The `KeepSubscriptions` flag for a `SubscribeRequest` to `node_id`:
    /// `true` iff this controller holds **another** subscription to the node —
    /// any but `excluding` — that is
    ///
    /// - established (`subscriptions`), its consumer still listening;
    /// - in a resubscribe episode ([`Self::resubscribe_episode_entries`]:
    ///   queued, in flight, or connecting), its consumer still listening;
    /// - an initial subscribe still pending (a `Subscribe` pending whose reply
    ///   channel is open — a caller that gave up does not count);
    /// - an initial subscribe parked for re-send after MRP exhaustion
    ///   (`ConnectWaiter::ResendPending`), its reply channel still open:
    ///   exhaustion does not prove the device never received it.
    ///
    /// A parked `Command::Subscribe` does not count: it has not been sent, and
    /// computes its own flag when it is.
    ///
    /// Matter 1.4 §8.5: with `KeepSubscriptions = false` the publisher
    /// terminates every other subscription of this subscriber. So a lone
    /// subscription (the first after a restart) still clears what an earlier
    /// process left on the device, while siblings never terminate each other.
    /// The device scopes that to (fabric, subscriber node id); with one sole
    /// fabric the node id alone identifies it — hence the documented
    /// assumption of one controller process per operational identity.
    ///
    /// Two known gaps, both benign and documented rather than solved:
    /// `handle_connect_done` takes a node's whole waiter list before resuming
    /// it, so siblings resumed in that one pass do not see each other — they
    /// are sent in order, so an earlier `false` reaches the device before the
    /// later sibling exists there. And if a first `false` transmission is lost
    /// and a sibling's `true` arrives first, the first one's MRP retransmission
    /// terminates the sibling, which recovers through its own liveness timeout.
    fn keep_subscriptions_for(&self, node_id: u64, excluding: Option<SubId>) -> bool {
        let other = |sub_id: SubId| excluding != Some(sub_id);
        let established = self
            .subscriptions
            .iter()
            .any(|(id, e)| e.node_id == node_id && other(*id) && !e.tx.consumer_gone());
        let in_episode = self
            .resubscribe_episode_entries()
            .any(|(id, n, tx)| n == node_id && other(id) && !tx.consumer_gone());
        let initial_pending = self.pending.values().any(|p| {
            matches!(
                &p.reply,
                PendingReply::Subscribe { sub_id, reply: Some(reply), node_id: n, .. }
                    if *n == node_id && other(*sub_id) && !reply.is_closed()
            )
        });
        let initial_parked = self.pending_connects.get(&node_id).is_some_and(|waiters| {
            waiters.iter().any(|w| {
                matches!(
                    w,
                    ConnectWaiter::ResendPending(Pending {
                        reply: PendingReply::Subscribe { sub_id, reply: Some(reply), .. },
                        ..
                    }) if other(*sub_id) && !reply.is_closed()
                )
            })
        });
        established || in_episode || initial_pending || initial_parked
    }

    /// Drop every in-flight trace of `sub_id`'s resubscribe:
    ///
    /// - an attempt on the wire (a `Subscribe` pending with no reply) is
    ///   removed and its MRP exchange — the purged pending's own key — aborted
    ///   ([`Self::abort_exchange`]), which sends the ack it still owes and
    ///   drops its pending retransmits: the
    ///   `SubscribeRequest` stops retransmitting and cannot be late-delivered
    ///   to create a subscription nobody reads (or, with
    ///   `KeepSubscriptions = false`, to terminate a sibling);
    /// - an attempt waiting on a connect loses its waiter. The connect itself
    ///   keeps running for whatever else waits on it; an emptied waiter list is
    ///   tolerated by `handle_connect_done` and `fail_connect_waiters`.
    ///
    /// Matter has no unsubscribe message; this is what chip's `ReadClient`
    /// destructor does (it releases its exchange, aborting MRP retries).
    async fn purge_inflight_resubscribe(&mut self, sub_id: SubId) {
        let keys: Vec<(SessionId, u16)> = self
            .pending
            .iter()
            .filter(|(_, p)| {
                matches!(
                    &p.reply,
                    PendingReply::Subscribe { sub_id: s, reply: None, .. } if *s == sub_id
                )
            })
            .map(|(key, _)| *key)
            .collect();
        for (sid, exchange) in keys {
            if let Some(p) = self.pending.remove(&(sid, exchange)) {
                // chip's abort still flushes the ACK before it drops the
                // exchange's retransmits (`Abort()` → `DoClose(true)`).
                self.abort_exchange(sid, exchange, p.peer).await;
            }
        }
        for waiters in self.pending_connects.values_mut() {
            waiters.retain(|w| !matches!(w, ConnectWaiter::Resubscribe(pr) if pr.sub_id == sub_id));
        }
    }

    /// Whether the resubscribe watch must hold the fabric-subtype browse open:
    /// true while some subscription whose consumer is still listening is in a
    /// resubscribe episode ([`Self::resubscribe_episode_entries`]). An entry
    /// whose consumer dropped both receivers does not count; it only waits to
    /// be reaped and must not keep a browse open until then.
    fn resubscribe_watch_needed(&self) -> bool {
        self.resubscribe_episode_entries()
            .any(|(_, _, tx)| !tx.consumer_gone())
    }

    /// Pull `node_id`'s resubscribes forward because the node is likely
    /// reachable again; returns how many subscriptions were affected.
    ///
    /// For every subscription of `node_id` in a resubscribe episode whose
    /// consumer is still listening (and, for [`TriggerSource::Advert`], not
    /// pulled within [`ADVERT_PULL_COOLDOWN`]):
    ///
    /// - **queued** with its attempt in the future: backoff reset to the start
    ///   (`retry_count = 0`) and `attempt_at = now`, so the existing
    ///   `drive_resubscribes` fires it on the next pass. Counted.
    /// - **queued and already due**: backoff reset (`retry_count = 0`) but its
    ///   `attempt_at` is left alone — it fires this pass anyway. Not counted,
    ///   so it gets no cooldown stamp and causes no route eviction. The reset
    ///   still matters: if that attempt fails it is rescheduled on the first
    ///   step, not on the step it had reached.
    /// - **in flight** (a `Subscribe` pending, or a connect waiter): backoff
    ///   reset, and no second attempt is started. If that attempt then fails it
    ///   is rescheduled on the first step (3–10 s), not a multi-minute one.
    ///   Without this an advert that lands mid-attempt is consumed and lost.
    ///   Counted.
    ///
    /// Every counted subscription's cooldown stamp is set, whatever the source.
    /// If at least one queued entry moved, the node's idle cached route is
    /// dropped ([`Self::evict_route_for_pull`]) so the attempt makes a fresh
    /// CASE handshake instead of first timing out on a session a rebooted
    /// device no longer has.
    ///
    /// This is chip's `ResetResubscriptionBackoff()` followed by
    /// `ReadClient::TriggerResubscribeIfScheduled`, which is what Apple's
    /// `Matter.framework` calls when it sees an operational advert. Apple
    /// resets the backoff unconditionally, whatever state the attempt is in,
    /// which is why the already-due case resets too. A forgotten node has no
    /// entries, so nothing is resurrected. Never fails.
    fn trigger_resubscribe(&mut self, node_id: u64, source: TriggerSource, now: Instant) -> usize {
        let honour_cooldown = source == TriggerSource::Advert;
        let pulled_at = &self.resubscribe_pulled_at;
        let cooling = |sub_id: SubId| {
            honour_cooldown
                && pulled_at
                    .get(&sub_id)
                    .is_some_and(|at| now.saturating_duration_since(*at) < ADVERT_PULL_COOLDOWN)
        };
        let mut counted: Vec<SubId> = Vec::new();
        let mut moved_queued = false;

        for pr in &mut self.resubscribes {
            if pr.node_id != node_id || pr.tx.consumer_gone() || cooling(pr.sub_id) {
                continue;
            }
            pr.retry_count = 0;
            if pr.attempt_at <= now {
                // Due already: it fires this pass; only the backoff is reset.
                continue;
            }
            pr.attempt_at = now;
            moved_queued = true;
            counted.push(pr.sub_id);
        }
        for pending in self.pending.values_mut() {
            let PendingReply::Subscribe {
                sub_id,
                reply: None,
                node_id: entry_node,
                report_tx,
                retry_count,
                ..
            } = &mut pending.reply
            else {
                continue;
            };
            if *entry_node != node_id || report_tx.consumer_gone() || cooling(*sub_id) {
                continue;
            }
            *retry_count = 0;
            counted.push(*sub_id);
        }
        if let Some(waiters) = self.pending_connects.get_mut(&node_id) {
            for waiter in waiters {
                let ConnectWaiter::Resubscribe(pr) = waiter else {
                    continue;
                };
                if pr.tx.consumer_gone() || cooling(pr.sub_id) {
                    continue;
                }
                pr.retry_count = 0;
                counted.push(pr.sub_id);
            }
        }

        for sub_id in &counted {
            self.resubscribe_pulled_at.insert(*sub_id, now);
        }
        let evicted_route = moved_queued && self.evict_route_for_pull(node_id);
        let pulled = counted.len();
        match source {
            TriggerSource::Advert if pulled > 0 => tracing::info!(
                target: "matter_controller::actor",
                node = format_args!("{node_id:016X}"),
                pulled,
                evicted_route,
                "operational advert seen; resubscribe pulled forward",
            ),
            TriggerSource::Advert => tracing::debug!(
                target: "matter_controller::actor",
                node = format_args!("{node_id:016X}"),
                "operational advert seen; nothing to pull (already due, or pulled within the cooldown)",
            ),
            TriggerSource::Api => tracing::debug!(
                target: "matter_controller::actor",
                node = format_args!("{node_id:016X}"),
                pulled,
                evicted_route,
                "resubscribe_now called; resubscribe pulled forward",
            ),
        }
        pulled
    }

    /// Distinct node ids with a subscription in a resubscribe episode whose
    /// consumer is still listening: the nodes an advert can matter for.
    fn resubscribe_episode_nodes(&self) -> Vec<u64> {
        let mut nodes: Vec<u64> = self
            .resubscribe_episode_entries()
            .filter(|(_, _, tx)| !tx.consumer_gone())
            .map(|(_, node_id, _)| node_id)
            .collect();
        nodes.sort_unstable();
        nodes.dedup();
        nodes
    }

    /// Drain the subtype browse's found events (new PTR records,
    /// [`Discovery::poll_found`]) and pull forward the resubscribes of every
    /// waiting node that re-announced. Runs in the same pass as the
    /// `poll_results` drains in [`Self::drive_pending_resolves`], whenever the
    /// subtype handle is held (parked resolve, watch, or both).
    ///
    /// - Only the **subtype** handle is asked, and not when it is the same
    ///   handle as the base one: a fresh base browse flushes the daemon's whole
    ///   `_matter._tcp` cache to it as found events.
    /// - Events drained inside [`ADVERT_QUIET_WINDOW`] after the subtype open
    ///   are discarded (consumed, not deferred).
    /// - Events count only for the fabric the browse was opened for, and only
    ///   while it is still the sole fabric. Each waiting node's instance name
    ///   (`<cfid>-<node>`) is compared case-insensitively, as `record_key` does;
    ///   the name embeds the compressed fabric id, so the same node id on
    ///   another fabric cannot match.
    ///
    /// A found event is not a resolution: the pulled attempt's connect may park
    /// until the matching record lands, which chip sends in the same
    /// announcement, so usually in the same pass.
    fn poll_advert_found(&mut self, now: Instant) {
        let Some(handle) = self.resolve_query_fabric else {
            return;
        };
        if self.resolve_query == Some(handle) {
            return;
        }
        let found = self.discovery.poll_found(handle);
        if found.is_empty() {
            return;
        }
        if self.advert_quiet_until.is_some_and(|until| now < until) {
            tracing::debug!(
                target: "matter_controller::actor",
                discarded = found.len(),
                "subtype browse found events inside the quiet window after its open; \
                 discarded as the daemon's cache flush",
            );
            return;
        }
        let Some(cfid) = self.resolve_query_fabric_cfid else {
            return;
        };
        if self.sole_compressed_fabric_id().ok() != Some(cfid) {
            return;
        }
        for node_id in self.resubscribe_episode_nodes() {
            let instance = matter_commissioning::driver::operational_instance_name(cfid, node_id);
            if found
                .iter()
                .any(|name| name.eq_ignore_ascii_case(&instance))
            {
                self.trigger_resubscribe(node_id, TriggerSource::Advert, now);
            }
        }
    }

    /// Remove the cached route `(fabric_id, node_id)` if — and only if — it
    /// still points at `sid`, leaving the session itself registered. Returns
    /// whether it removed anything.
    ///
    /// Removing only the route sends the node's next operation through a fresh
    /// connect while anything still in flight on `sid` finishes or times out on
    /// its own terms. The "still points at `sid`" check stops a late caller from
    /// evicting a healthy session a sibling already put in its place. The
    /// session is never removed here (`handle_connect_done` finds no route for
    /// it, so it does not remove it either): [`Self::check_liveness`] and both
    /// branches of [`Self::on_pending_timeout`] follow up with
    /// [`Self::remove_session_if_orphaned`]; a pull
    /// ([`Self::evict_route_for_pull`]) leaves it to the session table.
    fn evict_cached_route_if(&mut self, fabric_id: u64, node_id: u64, sid: SessionId) -> bool {
        let key = (fabric_id, node_id);
        if self.cache.get(&key).is_some_and(|c| c.session_id == sid) {
            self.cache.remove(&key);
            true
        } else {
            false
        }
    }

    /// The route eviction a pull performs: drop `node_id`'s cached route unless
    /// a live subscription rides its session (then the node is demonstrably
    /// talking to us on it). No sole fabric: nothing to do.
    fn evict_route_for_pull(&mut self, node_id: u64) -> bool {
        let Ok(fabric_id) = self.sole_fabric().map(|f| f.fabric_id) else {
            return false;
        };
        let Some(sid) = self.cache.get(&(fabric_id, node_id)).map(|c| c.session_id) else {
            return false;
        };
        if self
            .subscriptions
            .values()
            .any(|entry| entry.session_id == sid)
        {
            return false;
        }
        self.evict_cached_route_if(fabric_id, node_id, sid)
    }

    /// Remove session `sid` if nothing references it any more: no cached route
    /// points at it, no subscription rides it, and no pending operation is
    /// keyed on it. Returns whether it was removed.
    ///
    /// Run after every route-only eviction — [`Self::check_liveness`], both
    /// branches of [`Self::on_pending_timeout`] — and after
    /// [`Self::find_report_subscription`] re-keys a subscription away from a
    /// session. Left alone, such orphans would linger until the session table's
    /// cap, whose oldest-idle-first eviction takes long-lived subscription
    /// sessions (idle between reports) before the newer orphans. What this
    /// cannot see is MRP-only traffic on the session (acks to reports, answers
    /// to stray reports); dropping that with no subscription left is harmless —
    /// a device still reporting there gets no ack and closes its subscription
    /// itself. A later MRP retransmit for a removed session finds no peer and
    /// is skipped; a later expiry finds no pending and returns.
    ///
    /// The session's owed ACKs are sent first ([`Self::release_session`]).
    fn remove_session_if_orphaned(&mut self, sid: SessionId) -> bool {
        let referenced = self.cache.values().any(|c| c.session_id == sid)
            || self.subscriptions.values().any(|e| e.session_id == sid)
            || self.pending.keys().any(|(s, _)| *s == sid);
        !referenced && self.release_session(sid)
    }

    /// Every subscription id currently in a resubscribe episode, live consumer
    /// or not. The set `resubscribe_pulled_at` must stay within.
    fn resubscribe_episode_sub_ids(&self) -> std::collections::HashSet<SubId> {
        self.resubscribe_episode_entries()
            .map(|(sub_id, _, _)| sub_id)
            .collect()
    }

    /// Test audit: every cooldown stamp belongs to a subscription that is still
    /// in a resubscribe episode, i.e. the map has not leaked.
    #[cfg(test)]
    fn assert_pulled_at_within_episodes(&self) {
        let live = self.resubscribe_episode_sub_ids();
        for sub_id in self.resubscribe_pulled_at.keys() {
            assert!(
                live.contains(sub_id),
                "resubscribe_pulled_at leaked {sub_id:?}: not in any resubscribe episode"
            );
        }
    }

    /// One reconcile step for the resubscribe watch, run once per timer drive
    /// pass at both drive sites in [`Self::run`]: after `check_liveness` and
    /// `drive_resubscribes`, so an episode that began this pass is seen, and
    /// before `drive_pending_resolves`, so a browse opened here is drained in
    /// the same pass. It never runs per inbound packet.
    ///
    /// - **Fabric changed** (no sole fabric, or not the one the held browse was
    ///   opened for): stop counting its found events; close it if no resolve is
    ///   parked, and let the next pass reopen it for the current fabric.
    /// - **Close** the held browse when no episode needs it and no resolve is
    ///   parked.
    /// - **Open** one when an episode needs it, none is held, no base-type
    ///   browse is live (a subtype browse beside a live base one recreates the
    ///   #113 starvation), there is a sole fabric, and no failed open is waiting
    ///   out [`WATCH_OPEN_RETRY`].
    /// - **Re-query** the held browse on its cadence while an episode needs it
    ///   ([`Self::drive_watch_requery`]), after the fabric check above. Its
    ///   schedule is dropped whenever no episode needs the watch, even while a
    ///   parked resolve keeps the browse, and a browse opened here gets one at
    ///   once.
    ///
    /// Opens go through [`Self::open_subtype_browse`], the same helper
    /// `spawn_connect` uses, so a browse a connect opened is recognised here
    /// rather than churned.
    fn reconcile_resubscribe_watch(&mut self, now: Instant) {
        let needed = self.resubscribe_watch_needed();
        let parked = !self.pending_resolves.is_empty();
        if self.resolve_query_fabric.is_some() {
            let current = self.sole_compressed_fabric_id().ok();
            if current.is_none() || current != self.resolve_query_fabric_cfid {
                self.resolve_query_fabric_cfid = None;
                if !parked {
                    tracing::debug!(
                        target: "matter_controller::actor",
                        "resubscribe watch: the fabric changed; closing the subtype browse",
                    );
                    self.close_subtype_browse();
                }
                // A stale `watch_requery_at` left here is harmless: no
                // re-query runs on this path, and `close_subtype_browse`
                // clears it before any reopen.
                return;
            }
            if !needed {
                // The episode is over. A parked resolve may still hold the
                // browse, but the watch's schedule goes now, so the next
                // episode starts at the first step.
                self.watch_requery_at = None;
                if !parked {
                    tracing::debug!(
                        target: "matter_controller::actor",
                        "resubscribe watch: no subscription is waiting; closing the subtype browse",
                    );
                    self.close_subtype_browse();
                }
                return;
            }
            self.drive_watch_requery(now);
            return;
        }
        if !needed
            || self.resolve_query.is_some()
            || self.watch_open_retry_at.is_some_and(|at| now < at)
        {
            return;
        }
        let Ok(cfid) = self.sole_compressed_fabric_id() else {
            return;
        };
        match self.open_subtype_browse(cfid) {
            Ok(()) => {
                self.watch_open_retry_at = None;
                // The drain tick counts toward the deadline from now on; make
                // the anchor fresh here (the invariant `park_resolve` keeps), so
                // a stale one cannot make the overdue guard run a wasted pass.
                if !parked {
                    self.next_resolve_poll = now + ADVERT_WATCH_POLL_INTERVAL;
                }
                tracing::debug!(
                    target: "matter_controller::actor",
                    subtype = %matter_transport::operational_fabric_subtype(cfid),
                    "resubscribe watch: subtype browse opened",
                );
                // Adopts the new handle: the first re-query is one step out.
                self.drive_watch_requery(now);
            }
            Err(e) => {
                self.watch_open_retry_at = Some(now + WATCH_OPEN_RETRY);
                tracing::debug!(
                    target: "matter_controller::actor",
                    error = %e,
                    retry_in_secs = WATCH_OPEN_RETRY.as_secs(),
                    "resubscribe watch: subtype browse could not be opened; will retry",
                );
            }
        }
    }

    /// The resubscribe watch's re-query cadence, run by
    /// [`Self::reconcile_resubscribe_watch`] while an episode needs the watch
    /// and the subtype browse is held for the sole fabric.
    ///
    /// - **Adopt:** a held handle with no schedule (just opened by the watch,
    ///   or opened by `spawn_connect`) gets its first re-query
    ///   [`ADVERT_REQUERY_FIRST`] from now.
    /// - **Reset:** a node that was not in an episode on the previous pass
    ///   (`watch_episode_nodes`, refreshed on every pass) has just been lost,
    ///   so the cadence restarts at its first step — never later than a
    ///   re-query already scheduled. Every newly lost node gets the 30 s →
    ///   5 min sequence whatever other nodes already wait; this is bounded
    ///   because episodes begin only at liveness timeouts. If a re-query is
    ///   already due on the pass a node joins, it goes out on that pass and
    ///   the next one follows 60 s later (the second step), never after the
    ///   longer interval the interrupted cadence may have reached.
    /// - **Re-query** once due, unless the base-type fallback browse is live:
    ///   a resolve is already driving queries then, and acting on the subtype
    ///   beside a live base browse is what #113 forbids. (That also covers a
    ///   `Discovery` handing out one handle for both browses: equal handles
    ///   mean the base one is live.) A skipped re-query stays due and goes out
    ///   on the first pass after the base browse closes. The interval then
    ///   doubles up to [`ADVERT_REQUERY_MAX`], and `requery_fast_drain_until`
    ///   holds the drain tick at [`RESOLVE_POLL_INTERVAL`] for the next
    ///   [`REQUERY_FAST_DRAIN`].
    ///
    /// No quiet window follows a re-query: the adapter's `poll_found` does not
    /// re-report an instance it already reported, so the daemon's replay is
    /// not mistaken for adverts. No timer source is added either: while the
    /// handle is held, the drain tick (at most 1 s) is in
    /// [`Self::next_timer_deadline`] and reconcile runs on every timer pass, so
    /// a re-query goes out at most about a second late.
    fn drive_watch_requery(&mut self, now: Instant) {
        let Some(handle) = self.resolve_query_fabric else {
            return;
        };
        let nodes = self.resubscribe_episode_nodes();
        let joined = nodes
            .iter()
            .any(|node| self.watch_episode_nodes.binary_search(node).is_err());
        self.watch_episode_nodes = nodes;
        let Some(scheduled) = self.watch_requery_at else {
            self.watch_requery_interval = ADVERT_REQUERY_FIRST;
            self.watch_requery_at = Some(now + ADVERT_REQUERY_FIRST);
            return;
        };
        let due = if joined {
            let reset = scheduled.min(now + ADVERT_REQUERY_FIRST);
            self.watch_requery_interval = ADVERT_REQUERY_FIRST;
            self.watch_requery_at = Some(reset);
            tracing::debug!(
                target: "matter_controller::actor",
                waiting_nodes = self.watch_episode_nodes.len(),
                "resubscribe watch: a node joined; re-query cadence restarted",
            );
            reset
        } else {
            scheduled
        };
        if self.resolve_query.is_some() || now < due {
            return;
        }
        self.discovery.requery(handle);
        self.watch_requery_interval = self
            .watch_requery_interval
            .saturating_mul(2)
            .min(ADVERT_REQUERY_MAX);
        self.watch_requery_at = Some(now + self.watch_requery_interval);
        self.requery_fast_drain_until = Some(now + REQUERY_FAST_DRAIN);
        tracing::debug!(
            target: "matter_controller::actor",
            waiting_nodes = self.watch_episode_nodes.len(),
            next_in = ?self.watch_requery_interval,
            "resubscribe watch: re-queried the subtype browse",
        );
    }

    /// Drop any parked resolve for `node_id` (it has been resolved, failed, or
    /// the node was forgotten) and release the shared browse if it was the last.
    fn cancel_pending_resolve(&mut self, node_id: u64) {
        self.pending_resolves.retain(|pr| pr.node_id != node_id);
        self.release_resolve_query_if_idle();
    }

    /// Open the base-type `_matter._tcp` fallback browse if its deadline has
    /// come and it is not open already — the delayed half of the #113 fix.
    ///
    /// Driven from [`Self::drive_pending_resolves`], which the loop already runs
    /// every [`RESOLVE_POLL_INTERVAL`] while resolves are parked, so the open
    /// lands within one tick of becoming due without a timer or task of its own.
    /// Called only with entries actually parked: a resolve that settled off the
    /// subtype browse inside the window releases `resolve_base_after` (via
    /// [`Self::release_resolve_query_if_idle`]) and the fallback never opens at
    /// all, which is the property that keeps the narrowing intact.
    ///
    /// Attempted exactly once per armed deadline (`resolve_base_after` is
    /// cleared regardless of outcome): a daemon that refuses the browse must not
    /// be re-asked on every subsequent tick. Failure is not fatal — the subtype
    /// browse is still running, and it is the one expected to answer.
    fn open_base_fallback_if_due(&mut self) {
        let Some(due) = self.resolve_base_after else {
            return;
        };
        if Instant::now() < due || self.resolve_query.is_some() {
            return;
        }
        self.resolve_base_after = None;
        match self.discovery.query(ServiceKind::Operational) {
            Ok(h) => {
                self.resolve_query = Some(h);
                tracing::debug!(
                    target: "matter_controller::actor",
                    after = ?SUBTYPE_ONLY_WINDOW,
                    parked = self.pending_resolves.len(),
                    "no subtype match after {}s; opening the base-type \
                     _matter._tcp browse as a fallback",
                    SUBTYPE_ONLY_WINDOW.as_secs_f32(),
                );
            }
            Err(e) => {
                tracing::debug!(
                    target: "matter_controller::actor",
                    error = %e,
                    "base-type fallback browse could not be opened; \
                     continuing on the subtype browse alone",
                );
            }
        }
    }

    /// Settle the parked resolves: drain the shared browse ONCE into
    /// `seen_records`, then match every parked entry against that cache — hits
    /// spawn their handshake, entries past [`RESOLVE_DEADLINE`] fail their node's
    /// waiters, the rest stay parked.
    ///
    /// The single drain is required for correctness, not just economy:
    /// [`Discovery::poll_results`] consumes what it returns, so a second drain
    /// elsewhere would steal records from entries this pass has not examined —
    /// and matching against the *cache* rather than this pass's snapshot is what
    /// stops a record that arrived before its resolve did from being lost (see
    /// [`SEEN_RECORD_TTL`]).
    ///
    /// Called from the timer arm, so [`RESOLVE_POLL_INTERVAL`] is the resolve's
    /// polling interval (the inline resolve it replaces polled every 100 ms), and once
    /// from [`Self::spawn_connect`] so an already-known record connects at once.
    /// Returns immediately when nothing is parked and the resubscribe watch
    /// holds no browse — an idle controller pays nothing. With only the watch
    /// held it drains the subtype browse every [`ADVERT_WATCH_POLL_INTERVAL`],
    /// except for [`REQUERY_FAST_DRAIN`] after a watch re-query
    /// (`requery_fast_drain_until`), when it drains every
    /// [`RESOLVE_POLL_INTERVAL`].
    fn drive_pending_resolves(&mut self) {
        // Re-arm the polling tick FIRST, before any early return: the loop only
        // consults it while entries are parked or the resubscribe watch holds
        // the subtype browse, and arming it unconditionally means no path can
        // leave a due-in-the-past anchor behind that would spin the fairness
        // guard. A parked resolve is polled briskly; the watch alone, which only
        // waits for a device to re-announce, at the slower cadence — except
        // while a watch re-query's fast-drain window is open: the daemon is
        // replaying its cache into a small channel, and its thread waits for
        // each drain while that is full.
        let now = Instant::now();
        let fast_drain = self
            .requery_fast_drain_until
            .is_some_and(|until| now < until);
        let interval = if self.pending_resolves.is_empty() && !fast_drain {
            ADVERT_WATCH_POLL_INTERVAL
        } else {
            RESOLVE_POLL_INTERVAL
        };
        self.next_resolve_poll = now + interval;
        if self.pending_resolves.is_empty() && self.resolve_query_fabric.is_none() {
            return;
        }
        self.open_base_fallback_if_due();
        // Poll BOTH browses (fabric subtype first — it is the one expected to
        // answer), deduplicating equal handles for a `Discovery` that does not
        // override `query_operational_fabric`. The base one is present only once
        // the delayed fallback above has opened it.
        let mut browses: Vec<(&'static str, QueryHandle)> = Vec::new();
        if let Some(h) = self.resolve_query_fabric {
            browses.push((BROWSE_SUBTYPE, h));
        }
        if let Some(h) = self.resolve_query {
            if !browses.iter().any(|(_, existing)| *existing == h) {
                browses.push((BROWSE_BASE, h));
            }
        }
        if browses.is_empty() {
            return;
        }
        if !self.pending_resolves.is_empty() {
            tracing::debug!(
                target: "matter_controller::actor",
                parked = ?self
                    .pending_resolves
                    .iter()
                    .map(|pr| pr.target.as_str())
                    .collect::<Vec<_>>(),
                cached = self.seen_records.len(),
                "settling parked operational resolves",
            );
        }
        let now = Instant::now();
        for (source, handle) in &browses {
            let services = self.discovery.poll_results(*handle);
            self.record_seen(&services, now, source);
        }
        // Adverts ride the same pass as the record drains.
        self.poll_advert_found(now);

        // Classify first, act after: the effects below need `&mut self`, which
        // the parked list cannot be borrowed across.
        let mut resolved: Vec<(
            u64,
            u64,
            SocketAddr,
            matter_transport::MrpConfig,
            &'static str,
        )> = Vec::new();
        let mut expired: Vec<(u64, String)> = Vec::new();
        let mut still_parked = Vec::with_capacity(self.pending_resolves.len());
        for pr in std::mem::take(&mut self.pending_resolves) {
            if let Some(rec) = self.seen_records.get(&Self::record_key(&pr.target)) {
                resolved.push((pr.fabric_id, pr.node_id, rec.peer, rec.peer_mrp, rec.source));
            } else if now >= pr.deadline {
                expired.push((pr.node_id, pr.target));
            } else {
                still_parked.push(pr);
            }
        }
        self.pending_resolves = still_parked;
        self.release_resolve_query_if_idle();

        for (node_id, target) in expired {
            // Same error the inline resolve produced on budget exhaustion (the
            // `not found via mDNS` substring is unchanged, so callers matching
            // on the message text are unaffected), plus a summary of what the
            // browse DID surface — the difference between "nothing reached this
            // host" and "records reached us, none of them this node" is the
            // whole diagnosis, and it must be visible without `RUST_LOG`.
            let message = self.resolve_failure_message(&target);
            tracing::debug!(
                target: "matter_controller::actor",
                node_id,
                instance = %target,
                "resolve expired at its deadline",
            );
            let err = Error::from(matter_commissioning::driver::DriverError::Discovery(
                message,
            ));
            self.fail_connect_waiters(node_id, &err);
        }
        for (fabric_id, node_id, peer, peer_mrp, browse) in resolved {
            tracing::debug!(
                target: "matter_controller::actor",
                node_id,
                peer = %peer,
                // Which browse produced the record that settled this resolve —
                // the field a #113 field report is read for.
                browse,
                "resolve matched a cached operational record",
            );
            self.finish_spawn_connect(fabric_id, node_id, peer, peer_mrp);
        }
    }

    /// The error text for a resolve that reached its deadline, enriched with
    /// the operational records the shared browse has actually cached.
    ///
    /// `seen_records` is keyed by the LOWERCASED instance name (DNS-SD
    /// comparison is case-insensitive), so the sampled names read lowercase
    /// while `target` carries the spec's uppercase hex — read them
    /// case-insensitively. The cache is bounded by [`SEEN_RECORD_CAP`] and aged
    /// by [`SEEN_RECORD_TTL`], so the reported count is "recently seen", not a
    /// lifetime total.
    ///
    /// It also holds only records that made it through
    /// [`record_seen`](Self::record_seen) — i.e. that the adapter recognised
    /// *and* that carried a routable address. A reported count of zero
    /// therefore does not prove nothing arrived, which is why the message says
    /// so rather than blaming the network.
    fn resolve_failure_message(&self, target: &str) -> String {
        let mut names: Vec<&str> = self.seen_records.keys().map(String::as_str).collect();
        // Sorted so repeated failures read identically instead of shuffling
        // with HashMap iteration order.
        names.sort_unstable();
        discovery_failure_message(target, &names)
    }

    /// Spawn the CASE handshake to an already-resolved `peer` — the tail of a
    /// connect, shared by [`spawn_connect`](Self::spawn_connect)'s fast path and
    /// the timer arm.
    ///
    /// The credentials and the certificate-validation clock are (re)built here
    /// rather than carried from `spawn_connect`: a parked connect may start its
    /// handshake many seconds later, and the device's operational chain must be
    /// checked against the time the handshake actually runs at.
    fn finish_spawn_connect(
        &mut self,
        fabric_id: u64,
        node_id: u64,
        peer: SocketAddr,
        peer_mrp: matter_transport::MrpConfig,
    ) {
        let creds = match self.sole_fabric() {
            Ok(fabric) => crate::credentials::operational_credentials(fabric),
            Err(e) => Err(e),
        };
        let (credentials, roots, _compressed) = match creds {
            Ok(c) => c,
            Err(e) => {
                self.fail_connect_waiters(node_id, &e);
                return;
            }
        };
        let now = match current_matter_time() {
            Ok(n) => n,
            Err(e) => {
                self.fail_connect_waiters(node_id, &e);
                return;
            }
        };
        // The peer's advertised MRP config now sizes the HANDSHAKE's retransmits
        // as well as the resulting session's. It is still stashed for
        // the failure paths that clear it, but the value the handshake and the
        // session use travels with the task.
        self.connect_mrp.insert(node_id, peer_mrp);
        // Reserve the local session id the handshake advertises in Sigma1; the
        // actor registers the finished session under it on completion.
        let local_session_id = self.sessions.allocate_session_id().0;
        // Load the stored resumption record, if this node has one. Attempting
        // whenever a record exists is what both references do — no capability
        // probe, no age check. A record the device no longer holds costs one
        // declined Sigma1 and the full handshake proceeds on the same exchange.
        let resumption_record = self.resumption_record_for_connect(fabric_id, node_id);
        let (inbound_tx, inbound_rx) = mpsc::channel(16);
        self.connect_inbound.insert(node_id, inbound_tx);
        let outbound_tx = self.connect_outbound_tx.clone();
        let done_tx = self.connect_done_tx.clone();
        tokio::spawn(run_connect_task(
            node_id,
            fabric_id,
            local_session_id,
            credentials,
            roots,
            now,
            peer,
            peer_mrp,
            matter_transport::MrpProvenance::PeerAdvertised,
            resumption_record,
            inbound_rx,
            outbound_tx,
            done_tx,
        ));
    }

    /// Put a spawned connect's outbound datagram on the actor's own socket.
    /// Installs the `peer` → node-id route first — before the send, so
    /// it is guaranteed present before the device's reply can arrive — then
    /// sends. The route is only installed while the connect is still live
    /// (`connect_inbound` holds its queue); a late outbound after completion is
    /// dropped without re-installing a stale route.
    async fn handle_connect_outbound(&mut self, out: crate::handshake_socket::HandshakeOutbound) {
        let crate::handshake_socket::HandshakeOutbound {
            node_id,
            bytes,
            peer,
        } = out;
        if self.connect_inbound.contains_key(&node_id) {
            self.connect_routes.insert(route_key(peer), node_id);
        }
        let _ = self.transport.send_to(&bytes, peer).await;
    }

    /// Handle a finished spawned connect: tear down its routing, then
    /// on success register the established session + re-dispatch the parked
    /// verbs (their `session_for` now cache-hits), or on failure resolve each
    /// parked verb's caller with the error.
    async fn handle_connect_done(&mut self, done: ConnectCompletion) {
        let ConnectCompletion {
            node_id,
            result,
            peer_mrp,
            provenance,
            attempted_resumption,
            peer_session_params,
        } = done;
        // The handshake is over: stop routing the peer's datagrams to the task.
        self.connect_inbound.remove(&node_id);
        self.connect_routes.retain(|_, n| *n != node_id);

        let (output, peer) = match result {
            Ok(ok) => ok,
            Err(e) => {
                if attempted_resumption && is_resumption_mac_mismatch(&e) {
                    self.recover_from_unusable_resumption_record(node_id);
                    return;
                }
                self.fail_connect_waiters(node_id, &e);
                return;
            }
        };
        let fabric_id = match self.sole_fabric() {
            Ok(fabric) => fabric.fabric_id,
            Err(e) => {
                self.fail_connect_waiters(node_id, &e);
                return;
            }
        };

        // Mirror the inline `connect` bookkeeping: evict any prior session for
        // this node, register the fresh one, refresh the address hint + cache,
        // and rescue any subscription stranded on the replaced session.
        let old_session = self.cache.get(&(fabric_id, node_id)).map(|c| c.session_id);
        if let Some(old) = old_session {
            self.release_session(old);
        }
        // Persist the fresh CASE resumption record alongside the address hint.
        // The device stores the same (id, secret) pair from this handshake, so
        // when it later initiates CASE to our provider server it will present
        // exactly this record's id. Serialization failure only costs the
        // fast-path (a later Sigma1-resume falls back to a full handshake).
        // Stamp the commissioner identity in force right now. A record without
        // it is unusable on the way back in, so a failure here costs the fast
        // path and nothing else.
        let fingerprint = self.commissioner_identity_fingerprint(fabric_id);
        let record_bytes = output
            .resumption_record
            .as_ref()
            .and_then(|r| crate::resumption::serialize_record(r, fingerprint.as_ref()).ok());
        // The config the handshake was actually sized to travels back on the
        // completion, so this no longer re-reads `connect_mrp` and cannot
        // silently substitute a default when a resolve expiry or a forget
        // cleared the entry mid-flight. Drop the stashed copy.
        self.connect_mrp.remove(&node_id);
        // The device's own `SessionParameters`, if it sent any, override the
        // mDNS-derived values field by field: an advertisement can be stale,
        // cached, or absent, whereas this is what the device said during this
        // handshake. Fields it omitted keep the mDNS value (chip's merge, not
        // matter.js's wholesale replace).
        let (peer_mrp, provenance) = match peer_session_params {
            Some(p) => (
                peer_mrp.merge_session_params(&p),
                matter_transport::MrpProvenance::PeerAdvertised,
            ),
            None => (peer_mrp, provenance),
        };
        let sid = self.sessions.register_case_with_mrp(
            &output,
            SessionRole::Initiator,
            peer_mrp,
            provenance,
        );
        if let Some(s) = self.sessions.get_mut(sid) {
            s.peer_addr = Some(peer);
        }
        self.upsert_device(fabric_id, node_id, peer, record_bytes);
        self.cache.insert(
            (fabric_id, node_id),
            CachedSession {
                session_id: sid,
                peer,
            },
        );
        if let Some(old) = old_session {
            self.resubscribe_stranded(old);
        }

        // Resume every unit of work parked on this connect on the fresh
        // `(session, peer)`; each proceeds without blocking the loop.
        if let Some(waiters) = self.pending_connects.remove(&node_id) {
            for waiter in waiters {
                match waiter {
                    // A verb: re-dispatch — its `session_for` now cache-hits.
                    ConnectWaiter::Command(cmd) => self.dispatch_ready(cmd).await,
                    // A timed-out op: re-send on the fresh session.
                    ConnectWaiter::ResendPending(p) => {
                        self.resume_resend_pending(p, sid, peer).await;
                    }
                    // A stranded subscription: re-establish on the fresh session.
                    ConnectWaiter::Resubscribe(pr) => {
                        self.resume_resubscribe(pr, sid, peer).await;
                    }
                }
            }
        }
    }

    /// Resolve every unit of work parked on a failed connect to `node_id` and
    /// drop the connect's routing. A parked verb fails its caller, a timed-out op
    /// fails its caller, and a stranded subscription reschedules onto its backoff
    /// (chip retries a subscription forever). `Error` is not `Clone`, so each
    /// caller-facing failure gets a fresh `Error::Operational` with the text.
    fn fail_connect_waiters(&mut self, node_id: u64, err: &Error) {
        self.connect_inbound.remove(&node_id);
        self.connect_routes.retain(|_, n| *n != node_id);
        // Drop any captured peer MRP config for this aborted/forgotten connect.
        self.connect_mrp.remove(&node_id);
        // …and any resolve still parked for it, so a forgotten node stops being
        // looked up and the shared browse closes with the last entry.
        self.cancel_pending_resolve(node_id);
        if let Some(waiters) = self.pending_connects.remove(&node_id) {
            let msg = err.to_string();
            let fail_err =
                || Error::Operational(format!("connect to node {node_id} failed: {msg}"));
            for waiter in waiters {
                match waiter {
                    ConnectWaiter::Command(cmd) => fail_command(cmd, fail_err()),
                    ConnectWaiter::ResendPending(p) => Self::fail_pending(p, fail_err()),
                    ConnectWaiter::Resubscribe(pr) => self.reschedule_resubscribe(pr, err),
                }
            }
        }
    }

    /// Re-send a timed-out pending op `p` on the freshly-established
    /// `(session, peer)` (pending-retry recovery, resumed by
    /// [`Self::handle_connect_done`]). Marks it `retried` and discards any
    /// partial read/subscribe accumulation from the first attempt; a send
    /// failure fails the op's caller.
    ///
    /// A subscribe is re-encoded, not replayed: its `KeepSubscriptions` is
    /// recomputed now — the one baked in at the first send may have been
    /// `false` with a sibling established since, and replaying it would
    /// terminate that sibling — and its event filters are bumped to the
    /// delivery watermark, since priming events from the failed first attempt
    /// are already in the caller's channel. The new bytes are stored back as
    /// the request.
    async fn resume_resend_pending(&mut self, mut p: Pending, sid: SessionId, peer: SocketAddr) {
        if p.reply.action_stopped() {
            Self::fail_pending(
                p,
                Error::Operational("action deadline elapsed or caller dropped".into()),
            );
            return;
        }
        if let PendingReply::Subscribe {
            sub_id,
            report_tx,
            paths,
            event_paths,
            event_filters,
            min_interval,
            max_interval,
            ..
        } = &mut p.reply
        {
            let keep_subscriptions = self.keep_subscriptions_for(p.node_id, Some(*sub_id));
            *event_filters =
                bump_event_filters(std::mem::take(event_filters), report_tx.max_event_delivered);
            p.request.payload = matter_interaction::build_subscribe_request(
                &matter_interaction::SubscribeRequest {
                    keep_subscriptions,
                    min_interval_floor: *min_interval,
                    max_interval_ceiling: *max_interval,
                    paths: paths.clone(),
                    event_paths: event_paths.clone(),
                    event_filters: event_filters.clone(),
                },
            );
        }
        let sent = self
            .send_request_guarded(
                sid,
                peer,
                p.request.opcode,
                p.request.protocol_id,
                &p.request.payload,
                p.reply.action_reply_mut(),
            )
            .await;
        match sent {
            Ok((exchange, counter)) => {
                let mut np = p;
                np.peer = peer;
                np.retried = true;
                // The retry re-sends the original request, so any partial
                // accumulation from the first attempt must be discarded.
                match &mut np.reply {
                    PendingReply::Read {
                        chunks,
                        total_bytes,
                        ..
                    } => {
                        chunks.clear();
                        *total_bytes = 0;
                    }
                    PendingReply::Subscribe { priming, .. } => {
                        **priming = ReportReassembler::default();
                    }
                    PendingReply::RoundTrip(_)
                    | PendingReply::TimedAction { .. }
                    | PendingReply::Action { .. }
                    | PendingReply::ChunkedWrite { .. } => {}
                }
                np.last_reliable_send = Some(counter);
                self.pending.insert((sid, exchange), np);
            }
            Err(e) => Self::fail_pending(p, e),
        }
    }

    /// Re-establish a stranded subscription `pr` on the freshly-established
    /// `(session, peer)` (resubscribe recovery, resumed by
    /// [`Self::handle_connect_done`]). A send failure reschedules it on its
    /// backoff rather than dropping it.
    async fn resume_resubscribe(
        &mut self,
        pr: PendingResubscribe,
        sid: SessionId,
        peer: SocketAddr,
    ) {
        // A consumer that dropped both receivers can never observe this
        // subscription again, so send nothing (a backstop: the `Drop`
        // cancel is a lossy `try_send` and may not have arrived).
        if pr.tx.consumer_gone() {
            self.resubscribe_pulled_at.remove(&pr.sub_id);
            return;
        }
        let req =
            matter_interaction::build_subscribe_request(&matter_interaction::SubscribeRequest {
                keep_subscriptions: self.keep_subscriptions_for(pr.node_id, Some(pr.sub_id)),
                min_interval_floor: pr.min_interval,
                max_interval_ceiling: pr.max_interval,
                paths: pr.paths.clone(),
                event_paths: pr.event_paths.clone(),
                event_filters: pr.event_filters.clone(),
            });
        match self
            .send_request(
                sid,
                peer,
                OP_SUBSCRIBE_REQUEST,
                ProtocolId::INTERACTION_MODEL,
                &req,
            )
            .await
        {
            Ok((exchange, counter)) => {
                self.pending.insert(
                    (sid, exchange),
                    Pending {
                        response_deadline: Instant::now() + self.response_deadline,
                        node_id: pr.node_id,
                        peer,
                        request: PendingRequest {
                            opcode: OP_SUBSCRIBE_REQUEST,
                            protocol_id: ProtocolId::INTERACTION_MODEL,
                            payload: req,
                        },
                        // Skip SH.1's reconnect-once — a timeout reschedules on
                        // the backoff (see `on_pending_timeout`).
                        retried: true,
                        last_reliable_send: Some(counter),
                        reply: PendingReply::Subscribe {
                            sub_id: pr.sub_id,
                            reply: None,
                            report_tx: pr.tx,
                            report_rx: None,
                            priming: Box::new(ReportReassembler::default()),
                            node_id: pr.node_id,
                            paths: pr.paths,
                            event_paths: pr.event_paths,
                            event_filters: pr.event_filters,
                            min_interval: pr.min_interval,
                            max_interval: pr.max_interval,
                            retry_count: pr.retry_count,
                        },
                    },
                );
            }
            Err(e) => self.reschedule_resubscribe(pr, &e),
        }
    }

    /// Establish a fresh CASE session to `node_id`, cache it, and record an
    /// address hint in persisted state.
    ///
    /// **This path never resumes**, and that is now a property of this
    /// fallback alone rather than of the controller: the spawned path
    /// ([`Self::finish_spawn_connect`]) offers the stored resumption record and
    /// takes the `Sigma2_Resume` fast path when the device accepts it. This one
    /// calls `run_case`, which has no resumption entry point, so it always
    /// pays a full SIGMA-I. It also cannot persist a record (`run_case`
    /// registers the session internally and never surfaces the handshake
    /// output), which is why it is a defensive fallback and not a route any
    /// real caller takes.
    ///
    /// This INLINE handshake is now a defensive fallback only. Every
    /// real caller connects OFF the actor loop instead — verbs park behind
    /// [`Self::spawn_connect`] via [`Self::dispatch`], and the two timer-arm
    /// recovery reconnects (pending-retry in [`Self::on_pending_timeout`],
    /// resubscribe in [`Self::attempt_resubscribe`]) enqueue a
    /// [`ConnectWaiter`]. It survives only as the cache-miss branch of
    /// [`Self::session_for`], which those callers no longer reach with a missing
    /// session; if it ever runs it briefly blocks the loop, so it must stay
    /// unreached in normal operation.
    async fn connect(&mut self, node_id: u64) -> Result<(SessionId, std::net::SocketAddr), Error> {
        let fabric_id = self.sole_fabric()?.fabric_id;
        let (credentials, roots, compressed) =
            crate::credentials::operational_credentials(self.sole_fabric()?)?;

        let peer = matter_commissioning::driver::resolve_operational(
            &mut self.discovery,
            compressed,
            node_id,
        )
        .await?;

        // Validate the device's operational cert chain against the real
        // wall-clock — the crypto layer never reads the system clock itself.
        let now = current_matter_time()?;
        let sid = matter_commissioning::driver::run_case(
            &self.transport,
            &mut self.sessions,
            peer,
            credentials,
            roots,
            node_id,
            fabric_id,
            now,
        )
        .await?;
        if let Some(s) = self.sessions.get_mut(sid) {
            s.peer_addr = Some(peer);
        }

        // Evict any prior session for this node from the SessionManager so its
        // dead MRP retransmits stop; we keep only the freshly-established one.
        let old_session = self.cache.get(&(fabric_id, node_id)).map(|c| c.session_id);
        // Defensive: `session_for` calls `connect` only on a cache miss, so this never fires today.
        if let Some(old) = old_session {
            self.release_session(old);
        }
        // `run_case` registers the session internally and does not expose the
        // `CaseSessionOutput`, so this fallback path cannot persist a
        // resumption record (`None` leaves any stored record untouched).
        self.upsert_device(fabric_id, node_id, peer, None);
        self.cache.insert(
            (fabric_id, node_id),
            CachedSession {
                session_id: sid,
                peer,
            },
        );
        // Any subscription still on the now-replaced session is stranded (its
        // reports arrive on a session we just evicted). Proactively resubscribe
        // it onto the fresh session instead of waiting for its liveness deadline,
        // so a round-trip reconnect transparently re-establishes the subscription
        // too.
        if let Some(old) = old_session {
            self.resubscribe_stranded(old);
        }
        Ok((sid, peer))
    }

    /// Resubscribe every subscription still bound to `old_session` — its reports
    /// would otherwise be lost (that session was just evicted) until its own
    /// liveness deadline fires. A subscription mid-resubscribe is not in
    /// `subscriptions`, so it is not re-triggered here.
    fn resubscribe_stranded(&mut self, old_session: SessionId) {
        let stranded: Vec<SubId> = self
            .subscriptions
            .iter()
            .filter(|(_, e)| e.session_id == old_session)
            .map(|(id, _)| *id)
            .collect();
        for id in stranded {
            self.begin_resubscribe(id, Error::Operational("session replaced".into()));
        }
    }

    /// Record/refresh the device's last-known address and (when the fresh
    /// handshake produced one) its CASE resumption record in persisted state.
    /// The NOC public key stays unknown until it is captured separately during
    /// commissioning; this entry is an address/resumption cache only.
    ///
    /// `resumption_record` is the serialized [`matter_crypto::ResumptionRecord`]
    /// from the just-completed CASE connect (see [`crate::resumption`]). It is
    /// persisted so a peer that later initiates CASE *to us* — the OTA
    /// requestor querying our provider server — can be matched by resumption
    /// id and accepted via `CaseResponder::accept_resumption`. `None` leaves
    /// any stored record untouched (the inline fallback `connect` path, whose
    /// driver does not expose the handshake output).
    fn upsert_device(
        &mut self,
        fabric_id: u64,
        node_id: u64,
        peer: std::net::SocketAddr,
        resumption_record: Option<Vec<u8>>,
    ) {
        let addr = peer.to_string();
        // Track whether this connect actually changed persisted state. A
        // reconnect to the *same* address (the common hot-path case) leaves the
        // address hint unchanged; the resumption record, however, rotates on
        // every fresh handshake, so a connect that carries one always persists.
        let mut changed = false;
        if let Some(fabric) = self
            .state
            .fabrics
            .iter_mut()
            .find(|f| f.fabric_id == fabric_id)
        {
            if let Some(dev) = fabric.devices.iter_mut().find(|d| d.node_id == node_id) {
                if dev.last_known_addr.as_deref() != Some(addr.as_str()) {
                    dev.last_known_addr = Some(addr);
                    changed = true;
                }
                if let Some(rr) = resumption_record {
                    dev.resumption_record = Some(rr);
                    changed = true;
                }
            }
            // UPDATE-ONLY: a `DeviceEntry` is born at commission time
            // ([`Self::handle_commission_completion`]), never on a connect. If
            // the node is not a known device — because it was `forget_node`ed
            // while this handshake was in flight, or was never commissioned —
            // this connect must NOT fabricate an entry. Doing so previously
            // pushed a placeholder with a ZEROED `peer_noc_public_key`, which
            // (a) resurrected a device the caller asked to forget and (b)
            // persisted a corrupt NOC key. A late connect to a forgotten node
            // now leaves persisted state untouched; its transient session is
            // never used (its waiters were failed by `forget_node`).
        }
        // Persistence here is best-effort and offloaded off the actor loop; a
        // write failure must not abort an otherwise-successful connection (the
        // address hint is rebuildable via mDNS, and a lost resumption record
        // only costs a full handshake later). Skip the fsync when nothing
        // changed (an unchanged reconnect on the inline fallback path).
        if changed {
            self.persist_best_effort();
        }
    }

    /// A resumption attempt failed its `Sigma2_Resume` MIC: drop the stored
    /// record and immediately re-run the connect as a full handshake.
    ///
    /// The waiters are deliberately NOT failed — from the caller's point of
    /// view this is one connect that took a little longer, not a failure. The
    /// retry cannot recur: the record is gone, so the next Sigma1 carries no
    /// resumption fields and cannot draw a `Sigma2_Resume` at all.
    ///
    /// # Why invalidate, when neither reference does
    ///
    /// chip fails the session establishment and keeps the record
    /// (`CASESession::HandleSigma2Resume`); matter.js throws and keeps it
    /// (`CaseClient`). Neither cites spec text, and the usual argument for
    /// keeping it is that deleting opens a denial-of-service vector — an
    /// attacker spoofing a bad-MIC `Sigma2_Resume` to wipe our state.
    ///
    /// That argument does not survive the threat model. Forging a
    /// `Sigma2_Resume` requires the 64-bit ephemeral initiator node id and the
    /// 16-bit exchange id of a handshake in flight; anyone who can supply
    /// those can equally forge a garbage `Sigma2` and break ANY handshake,
    /// resumption or not. Deleting opens no new surface. And the direction is
    /// backwards: keeping the record lets the attacker replay the same forgery
    /// on every retry, forever, whereas dropping it means the next Sigma1 is
    /// plain and a forged `Sigma2_Resume` is then an unsolicited opcode the
    /// exchange filters out. Invalidation terminates the wedge; retention
    /// sustains it.
    ///
    /// The benign case — a peer holding our resumption id against a different
    /// secret — is unreachable honestly (the responder validates the Sigma1
    /// resume MIC first and declines to a full handshake) but wedges forever
    /// if it ever occurs, and this is the only escape.
    ///
    /// This does not contradict the standing decision in `provider_server`
    /// that "records are not invalidated on CASE failure". That covers the
    /// RESPONDER declining an unknown id, which genuinely self-heals in one
    /// round trip. An initiator holding a record the responder has already
    /// rotated away is pure loss on every retry.
    fn recover_from_unusable_resumption_record(&mut self, node_id: u64) {
        tracing::warn!(
            target: "matter_controller::actor",
            node_id,
            "Sigma2_Resume failed its MIC; dropping the stored resumption record \
             and reconnecting with a full handshake"
        );
        let fabric_id = match self.sole_fabric() {
            Ok(f) => f.fabric_id,
            Err(e) => {
                self.fail_connect_waiters(node_id, &e);
                return;
            }
        };
        if let Some(fabric) = self
            .state
            .fabrics
            .iter_mut()
            .find(|f| f.fabric_id == fabric_id)
        {
            if let Some(dev) = fabric.devices.iter_mut().find(|d| d.node_id == node_id) {
                dev.resumption_record = None;
            }
        }
        self.persist_best_effort();
        self.spawn_connect(fabric_id, node_id);
    }

    /// SHA-256 of the commissioner NOC currently in force on `fabric_id`, or
    /// `None` if the fabric is unknown or its NOC will not re-serialize.
    ///
    /// `None` is always safe: on the write path the record is stored without a
    /// fingerprint (and so is never reused), and on the read path the record is
    /// rejected. Both outcomes cost only the resumption fast path.
    fn commissioner_identity_fingerprint(&self, fabric_id: u64) -> Option<[u8; 32]> {
        let fabric = self
            .state
            .fabrics
            .iter()
            .find(|f| f.fabric_id == fabric_id)?;
        crate::resumption::identity_fingerprint(&fabric.commissioner.noc).ok()
    }

    /// Load the stored CASE resumption record for `node_id` on `fabric_id`,
    /// ready to be offered in Sigma1.
    ///
    /// Returns `None` when the device has no record, when the stored bytes fail
    /// to deserialize, or when the record has an expiry that has passed.
    ///
    /// **A load failure is never fatal.** Every outcome here costs at most the
    /// fast path: the connect proceeds as a full handshake, which is what it did
    /// before resumption was wired up at all. A corrupt record is therefore
    /// logged and dropped rather than surfaced, so a bad byte in persisted state
    /// cannot make a device unreachable.
    fn resumption_record_for_connect(
        &self,
        fabric_id: u64,
        node_id: u64,
    ) -> Option<matter_crypto::ResumptionRecord> {
        self.usable_resumption_record(fabric_id, node_id)
    }

    /// The stored record for `node_id` on `fabric_id`, if it exists, parses,
    /// has not expired, and was minted under the commissioner identity
    /// currently in force. Used by both roles — offering one in Sigma1 and
    /// seeding the provider server that accepts one.
    fn usable_resumption_record(
        &self,
        fabric_id: u64,
        node_id: u64,
    ) -> Option<matter_crypto::ResumptionRecord> {
        let bytes = self
            .state
            .fabrics
            .iter()
            .find(|f| f.fabric_id == fabric_id)?
            .devices
            .iter()
            .find(|d| d.node_id == node_id)?
            .resumption_record
            .as_ref()?;
        let stored = match crate::resumption::deserialize_record(bytes) {
            Ok(r) => r,
            Err(e) => {
                tracing::debug!(
                    target: "matter_controller::actor",
                    node_id,
                    error = %e,
                    "stored CASE resumption record is unreadable; connecting with a full handshake"
                );
                return None;
            }
        };
        // Refuse a record minted under a commissioner identity that no longer
        // holds. Resumption replays a cached authorization snapshot without
        // re-verifying a certificate, and the ECDH secret it authenticates with
        // survives a NOC change unchanged — so nothing in the handshake itself
        // can notice that the identity moved. See `crate::resumption`.
        let current = self.commissioner_identity_fingerprint(fabric_id)?;
        if !stored.is_usable_under(&current) {
            tracing::debug!(
                target: "matter_controller::actor",
                node_id,
                "stored CASE resumption record was minted under a different commissioner \
                 identity; connecting with a full handshake"
            );
            return None;
        }
        let record = stored.record;
        // Nothing sets `expires_at` today, but honour it if it ever appears
        // rather than offering a record we already consider dead.
        if let Some(expiry) = record.expires_at {
            if let Ok(now) = current_matter_time() {
                if now > expiry {
                    tracing::debug!(
                        target: "matter_controller::actor",
                        node_id,
                        "stored CASE resumption record has expired; connecting with a full handshake"
                    );
                    return None;
                }
            }
        }
        Some(record)
    }

    /// Drop every cached CASE resumption record on `fabric_id`, then save
    /// **durably** — unlike the best-effort persist used for record rotation.
    ///
    /// The asymmetry is deliberate. Losing a rotation costs a fast path;
    /// losing an invalidation leaves stale authorization snapshots on disk
    /// after the caller was told they were gone, which is the whole failure
    /// this method exists to prevent.
    async fn handle_invalidate_resumption_records(
        &mut self,
        fabric_id: u64,
    ) -> Result<usize, Error> {
        let Some(fabric) = self
            .state
            .fabrics
            .iter_mut()
            .find(|f| f.fabric_id == fabric_id)
        else {
            return Err(Error::Operational(format!(
                "no fabric {fabric_id:#x} to invalidate resumption records on"
            )));
        };
        let cleared = fabric.invalidate_resumption_records();
        if cleared > 0 {
            tracing::info!(
                target: "matter_controller::actor",
                fabric_id,
                cleared,
                "invalidated cached CASE resumption records"
            );
        }
        let job = self.durable_save_inputs()?;
        save_offloaded(job).await?;
        Ok(cleared)
    }

    /// Replace the stored CASE resumption record for `node_id` on the sole
    /// fabric (best-effort persist). See [`Command::StoreResumptionRecord`].
    #[cfg(feature = "ota")]
    fn handle_store_resumption_record(
        &mut self,
        node_id: u64,
        record: &matter_crypto::ResumptionRecord,
    ) -> Result<(), Error> {
        let fabric = self.sole_fabric()?;
        let fabric_id = fabric.fabric_id;
        let fingerprint = self.commissioner_identity_fingerprint(fabric_id);
        let record_bytes = crate::resumption::serialize_record(record, fingerprint.as_ref())?;
        let Some(dev) = self
            .state
            .fabrics
            .iter_mut()
            .find(|f| f.fabric_id == fabric_id)
            .and_then(|f| f.devices.iter_mut().find(|d| d.node_id == node_id))
        else {
            return Err(Error::Operational(format!(
                "no device entry for node {node_id:#x} to store a resumption record on"
            )));
        };
        dev.resumption_record = Some(record_bytes);
        self.persist_best_effort();
        Ok(())
    }

    /// Return a live `(session, peer)` for `node_id`: the cached session if any,
    /// else connect fresh (this blocks the loop briefly — accepted residual).
    async fn session_for(&mut self, node_id: u64) -> Result<(SessionId, SocketAddr), Error> {
        let fabric_id = self.sole_fabric()?.fabric_id;
        if let Some((sid, peer)) = self
            .cache
            .get(&(fabric_id, node_id))
            .map(|c| (c.session_id, c.peer))
        {
            return Ok((sid, peer));
        }
        self.connect(node_id).await
    }

    /// Encode+send a reliable secured request; returns the allocated exchange
    /// id and the request's message counter (for
    /// [`Pending::last_reliable_send`]).
    async fn send_request(
        &mut self,
        sid: SessionId,
        peer: SocketAddr,
        opcode: u8,
        protocol_id: ProtocolId,
        payload: &[u8],
    ) -> Result<(u16, MessageCounter), Error> {
        self.send_request_guarded(sid, peer, opcode, protocol_id, payload, None)
            .await
    }

    #[allow(clippy::too_many_arguments)] // optional action lifetime at the send boundary
    async fn send_request_guarded(
        &mut self,
        sid: SessionId,
        peer: SocketAddr,
        opcode: u8,
        protocol_id: ProtocolId,
        payload: &[u8],
        reply: Option<&mut ActionReply>,
    ) -> Result<(u16, MessageCounter), Error> {
        let out = self.sessions.encode_outbound(
            sid,
            None,
            opcode,
            protocol_id,
            payload,
            MrpFlags { reliable: true },
            Instant::now(),
        )?;
        let exchange = out.exchange_id;
        let send = async {
            self.transport
                .send_to(&out.wire_bytes, peer)
                .await
                .map_err(|e| Error::Operational(format!("request send: {e}")))
        };
        let result = match reply {
            Some(reply) => reply.until_stopped(send).await,
            None => send.await,
        };
        if let Err(error) = result {
            self.abort_exchange(sid, exchange, peer).await;
            return Err(error);
        }
        Ok((exchange, out.message_counter))
    }

    /// Send a secured IM round-trip and register a pending op; the central
    /// [`Self::handle_inbound`] resolves `reply` when the response (or timeout)
    /// arrives.
    #[cfg(test)]
    async fn start_round_trip(
        &mut self,
        node_id: u64,
        opcode: u8,
        protocol_id: ProtocolId,
        payload: Vec<u8>,
        reply: ActionReply,
    ) {
        if reply.stopped() {
            let _ = reply.send(Err(Error::Operational(
                "action deadline elapsed or caller dropped".into(),
            )));
            return;
        }

        let (sid, peer) = match self.session_for(node_id).await {
            Ok(v) => v,
            Err(e) => {
                let _ = reply.send(Err(e));
                return;
            }
        };
        match self
            .send_request(sid, peer, opcode, protocol_id, &payload)
            .await
        {
            Ok((exchange, counter)) => {
                self.pending.insert(
                    (sid, exchange),
                    Pending {
                        response_deadline: Instant::now() + self.response_deadline,
                        node_id,
                        peer,
                        request: PendingRequest {
                            opcode,
                            protocol_id,
                            payload,
                        },
                        retried: false,
                        last_reliable_send: Some(counter),
                        reply: PendingReply::RoundTrip(reply),
                    },
                );
            }
            Err(e) => {
                let _ = reply.send(Err(e));
            }
        }
    }

    /// Send a `TimedRequest` and register a [`PendingReply::TimedAction`] that, on
    /// the device's `StatusResponse(SUCCESS)`, sends `action_payload` on the same
    /// exchange (see [`Self::resolve_timed`]). Shared by
    /// [`Self::start_timed_round_trip`] and the timed-escalation path of a
    /// write/invoke `Action`.
    #[allow(clippy::too_many_arguments)] // the timed handshake inputs; bundling only renames them.
    async fn begin_timed(
        &mut self,
        sid: SessionId,
        peer: SocketAddr,
        node_id: u64,
        timeout_ms: u16,
        action_opcode: u8,
        action_payload: Vec<u8>,
        mut reply: ActionReply,
    ) {
        if reply.stopped() {
            let _ = reply.send(Err(Error::Operational(
                "action deadline elapsed or caller dropped".into(),
            )));
            return;
        }

        let req = matter_interaction::build_timed_request(timeout_ms);
        match self
            .send_request_guarded(
                sid,
                peer,
                OP_TIMED_REQUEST,
                ProtocolId::INTERACTION_MODEL,
                &req,
                Some(&mut reply),
            )
            .await
        {
            Ok((exchange, counter)) => {
                self.pending.insert(
                    (sid, exchange),
                    Pending {
                        response_deadline: Instant::now() + self.response_deadline,
                        node_id,
                        peer,
                        request: PendingRequest {
                            opcode: OP_TIMED_REQUEST,
                            protocol_id: ProtocolId::INTERACTION_MODEL,
                            payload: req,
                        },
                        retried: false,
                        last_reliable_send: Some(counter),
                        reply: PendingReply::TimedAction {
                            action_opcode,
                            action_payload,
                            reply,
                        },
                    },
                );
            }
            Err(e) => {
                let _ = reply.send(Err(e));
            }
        }
    }

    /// Timed round-trip: resolve the session, then run the `TimedRequest` →
    /// action handshake (see [`Self::begin_timed`] / [`Self::resolve_timed`]).
    async fn start_timed_round_trip(
        &mut self,
        node_id: u64,
        timeout_ms: u16,
        action_opcode: u8,
        action_payload: Vec<u8>,
        reply: ActionReply,
    ) {
        if reply.stopped() {
            let _ = reply.send(Err(Error::Operational(
                "action deadline elapsed or caller dropped".into(),
            )));
            return;
        }

        let (sid, peer) = match self.session_for(node_id).await {
            Ok(v) => v,
            Err(e) => {
                let _ = reply.send(Err(e));
                return;
            }
        };
        self.begin_timed(
            sid,
            peer,
            node_id,
            timeout_ms,
            action_opcode,
            action_payload,
            reply,
        )
        .await;
    }

    /// Handle a write/invoke `Action`: consult the learned timed-cache and either
    /// go straight to a timed interaction (cache hit) or send the plain action and
    /// let [`Self::resolve_action`] retry-on-`0xc6`.
    #[allow(clippy::too_many_arguments)] // mirrors the Command::Action fields.
    async fn handle_action(
        &mut self,
        node_id: u64,
        opcode: u8,
        plain_payload: Vec<u8>,
        timed_payload: TimedPayload,
        keys: Vec<(u32, u32)>,
        timeout_ms: u16,
        mut reply: ActionReply,
    ) {
        if reply.stopped() {
            let _ = reply.send(Err(Error::Operational(
                "action deadline elapsed or caller dropped".into(),
            )));
            return;
        }

        let (sid, peer) = match self.session_for(node_id).await {
            Ok(v) => v,
            Err(e) => {
                let _ = reply.send(Err(e));
                return;
            }
        };
        if reply.stopped() {
            let _ = reply.send(Err(Error::Operational(
                "action deadline elapsed or caller dropped".into(),
            )));
            return;
        }
        // Fast-path: a known-timed path skips the wasted plain attempt. This is
        // one of the two places the timed payload is actually encoded.
        if keys.iter().any(|k| self.timed_paths.contains(k)) {
            self.begin_timed(
                sid,
                peer,
                node_id,
                timeout_ms,
                opcode,
                timed_payload(),
                reply,
            )
            .await;
            return;
        }
        match self
            .send_request_guarded(
                sid,
                peer,
                opcode,
                ProtocolId::INTERACTION_MODEL,
                &plain_payload,
                Some(&mut reply),
            )
            .await
        {
            Ok((exchange, counter)) => {
                self.pending.insert(
                    (sid, exchange),
                    Pending {
                        response_deadline: Instant::now() + self.response_deadline,
                        node_id,
                        peer,
                        request: PendingRequest {
                            opcode,
                            protocol_id: ProtocolId::INTERACTION_MODEL,
                            payload: plain_payload,
                        },
                        retried: false,
                        last_reliable_send: Some(counter),
                        reply: PendingReply::Action {
                            opcode,
                            timed_payload,
                            keys,
                            timeout_ms,
                            node_id,
                            reply,
                        },
                    },
                );
            }
            Err(e) => {
                let _ = reply.send(Err(e));
            }
        }
    }

    /// Resolve a plain write/invoke response. If the device rejected it with
    /// `NEEDS_TIMED_INTERACTION (0xc6)`, record the `keys` in the learned
    /// timed-cache and transparently retry the action as a timed interaction;
    /// otherwise resolve the caller with the response bytes.
    async fn resolve_action(&mut self, sid: SessionId, exchange: u16, payload: Vec<u8>) {
        let Some(p) = self.pending.remove(&(sid, exchange)) else {
            return;
        };
        if p.reply.action_stopped() {
            self.abort_exchange(sid, exchange, p.peer).await;
            Self::fail_pending(
                p,
                Error::Operational("action deadline elapsed or caller dropped".into()),
            );
            return;
        }
        let PendingReply::Action {
            opcode,
            timed_payload,
            keys,
            timeout_ms,
            node_id,
            reply,
        } = p.reply
        else {
            return;
        };
        if !response_needs_timed(opcode, &payload) {
            self.abort_exchange(sid, exchange, p.peer).await;
            let _ = reply.send(Ok(payload));
            return;
        }
        // Learn these paths so future ops skip the wasted plain attempt, then
        // retry the action as a timed interaction feeding the same reply. This
        // is the second (and only other) place the timed payload is encoded —
        // the same `build_*_timed` bytes as before, just built now instead of
        // up-front.
        for k in keys {
            self.timed_paths.insert(k);
        }
        // The plain attempt's exchange is over; the timed retry opens a new one.
        self.abort_exchange(sid, exchange, p.peer).await;
        self.begin_timed(
            sid,
            p.peer,
            node_id,
            timeout_ms,
            opcode,
            timed_payload(),
            reply,
        )
        .await;
    }

    /// Send a `ReadRequest` and register a pending read; chunks accumulate in
    /// the pending entry and resolve on the final chunk.
    async fn start_read(
        &mut self,
        node_id: u64,
        payload: Vec<u8>,
        reply: oneshot::Sender<Result<Vec<matter_interaction::ReportData>, Error>>,
    ) {
        let (sid, peer) = match self.session_for(node_id).await {
            Ok(v) => v,
            Err(e) => {
                let _ = reply.send(Err(e));
                return;
            }
        };
        let opcode = crate::node::OP_READ_REQUEST;
        match self
            .send_request(sid, peer, opcode, ProtocolId::INTERACTION_MODEL, &payload)
            .await
        {
            Ok((exchange, counter)) => {
                self.pending.insert(
                    (sid, exchange),
                    Pending {
                        response_deadline: Instant::now() + self.response_deadline,
                        node_id,
                        peer,
                        request: PendingRequest {
                            opcode,
                            protocol_id: ProtocolId::INTERACTION_MODEL,
                            payload,
                        },
                        retried: false,
                        last_reliable_send: Some(counter),
                        reply: PendingReply::Read {
                            reply,
                            chunks: Vec::new(),
                            total_bytes: 0,
                        },
                    },
                );
            }
            Err(e) => {
                let _ = reply.send(Err(e));
            }
        }
    }

    /// Send a chunked write: `chunks` go on ONE exchange, ONE chunk in flight
    /// at a time (mirrors chip's `WriteClient`: exactly one outstanding
    /// reliable `WriteRequest` per exchange — Matter §8.7.4 / §10.6). The
    /// first chunk allocates the exchange (`encode_outbound(.., None, ..)`)
    /// via `send_request`; every later chunk reuses it (`Some(exchange)`),
    /// sent one at a time by [`Self::resolve_chunked_write`] as each
    /// preceding chunk's `WriteResponse` arrives. All but the last chunk
    /// carry `MoreChunkedMessages=true` (the caller built them via
    /// `build_list_write_chunks`). The device replies with a `WriteResponse`
    /// to EVERY chunk (chip's `WriteHandler` sends one per received
    /// `WriteRequest`); every chunk's statuses are accumulated and pumping
    /// continues UNCONDITIONALLY regardless of individual element statuses
    /// (chip's `WriteClient` does not abort on a non-Success status — see
    /// [`PendingReply::ChunkedWrite`]'s doc for the full terminal-failure list).
    ///
    /// Only ONE [`Pending`] is registered for this exchange at any time,
    /// keyed by `(session, exchange)`: registered here after the first
    /// chunk, then re-registered by [`Self::resolve_chunked_write`] after
    /// each subsequent chunk until the final chunk's `WriteResponse`
    /// resolves `reply` with the accumulated per-path status list.
    async fn handle_chunked_write(
        &mut self,
        node_id: u64,
        chunks: Vec<Vec<u8>>,
        reply: oneshot::Sender<
            Result<
                Vec<(
                    matter_interaction::AttributePath,
                    matter_interaction::ImStatus,
                )>,
                Error,
            >,
        >,
    ) {
        if chunks.is_empty() {
            let _ = reply.send(Err(Error::Operational(
                "chunked_write requires at least one chunk".into(),
            )));
            return;
        }
        let (sid, peer) = match self.session_for(node_id).await {
            Ok(v) => v,
            Err(e) => {
                let _ = reply.send(Err(e));
                return;
            }
        };

        // First chunk allocates the exchange; capture it so later chunks
        // (sent one at a time, gated on each WriteResponse — see
        // resolve_chunked_write) reuse it.
        let (exchange, counter) = match self
            .send_request(
                sid,
                peer,
                OP_WRITE_REQUEST,
                ProtocolId::INTERACTION_MODEL,
                &chunks[0],
            )
            .await
        {
            Ok(sent) => sent,
            Err(e) => {
                let _ = reply.send(Err(e));
                return;
            }
        };

        // The remaining chunks are NOT sent here — chip's WriteClient gates
        // each chunk on the previous chunk's WriteResponse, so they wait in
        // `remaining` until resolve_chunked_write drains them one at a time.
        let mut remaining: VecDeque<Vec<u8>> = chunks.into();
        // The first chunk (just sent above) is also the request bytes this
        // pending retains — `remaining.pop_front()` re-yields it since
        // nothing has been popped yet.
        let first = remaining.pop_front().unwrap_or_default();

        self.pending.insert(
            (sid, exchange),
            Pending {
                response_deadline: Instant::now() + self.response_deadline,
                node_id,
                peer,
                request: PendingRequest {
                    opcode: OP_WRITE_REQUEST,
                    protocol_id: ProtocolId::INTERACTION_MODEL,
                    // The chunk actually in flight right now (chunks[0]), not
                    // the final chunk — this is what a reconnect-resend would
                    // conceptually retry. `retried: true` below means a
                    // timeout never actually replays it (see that field's
                    // comment).
                    payload: first,
                },
                // A chunked write spans multiple reliable messages on one
                // exchange; a transparent reconnect-and-resend mid-transaction
                // would corrupt the device's accumulation (a partially-sent
                // chunked write on a dead session cannot be resumed — the
                // device discards an incomplete chunked transaction, and only
                // the caller re-issuing the whole write is correct). Mark it
                // already retried so a timeout fails the op cleanly instead
                // of attempting a reconnect-resend.
                retried: true,
                last_reliable_send: Some(counter),
                reply: PendingReply::ChunkedWrite {
                    reply,
                    remaining,
                    statuses: Vec::new(),
                },
            },
        );
    }

    /// Route one inbound datagram: resolve a pending round-trip/read by
    /// `(session, exchange)`; deliver a steady-state `ReportData` to its
    /// subscription by `(session, subscriptionId)`; otherwise let MRP absorb it.
    async fn handle_inbound(&mut self, packet: &[u8], from: SocketAddr) {
        // Unsecured datagrams (session id 0). During an off-loop CASE connect
        // (M9-G-d) the device's handshake replies (Sigma2 / StatusReport /
        // standalone acks) arrive here from the connect's peer — forward them to
        // that spawned task via its inbound queue. Anything else is a straggler
        // we drop.
        if packet.len() >= 3 && packet[1] == 0 && packet[2] == 0 {
            if let Some(&node_id) = self.connect_routes.get(&route_key(from)) {
                if let Some(tx) = self.connect_inbound.get(&node_id) {
                    let _ = tx.send((packet.to_vec(), from)).await;
                }
            }
            return;
        }
        let decoded = match self.sessions.decode_inbound(packet, Instant::now()) {
            Ok(decoded) => decoded,
            Err(e) => {
                // Never swallow this silently: a dropped `ExchangeTableFull` hid
                // an MRP exchange leak for weeks while every subscription on the
                // session went deaf after its priming report. It means the
                // session is refusing every new device-initiated exchange
                // (reports, events), and the device gets no ack — so warn. It is
                // not rate-limited: with completed exchanges reclaimed, reaching
                // the cap takes 256 genuinely live exchanges from one peer.
                // Everything else (a stale session id, a replayed or late
                // duplicate counter, a failed tag) is routine datagram noise.
                if matches!(e, matter_transport::Error::ExchangeTableFull) {
                    tracing::warn!(
                        target: "matter_controller::actor",
                        peer = %from,
                        error = %e,
                        "dropping inbound message: the session's exchange table is full, \
                         so new device-initiated exchanges (reports, events) are being lost"
                    );
                } else {
                    tracing::debug!(
                        target: "matter_controller::actor",
                        peer = %from,
                        error = %e,
                        "dropping inbound message that failed to decode"
                    );
                }
                return;
            }
        };
        match decoded {
            DecodeInboundOutput::AppMessage {
                session_id,
                exchange_id,
                is_initiator,
                protocol_id,
                opcode,
                payload,
                ..
            } => {
                // A CloseSession (Matter 1.4 Core §4.11.1.4) is a Secure
                // Channel status report the device sends as an exchange
                // initiator, encrypted on the session it closes;
                // `decode_inbound` has just authenticated it with that
                // session's keys. One on an exchange we started (I flag clear)
                // is not a CloseSession. chip is slightly stricter: it hands a
                // message to its unsolicited handler
                // (`UnsolicitedStatusHandler.cpp:28-56`) only when no open
                // exchange matched it (`ExchangeMgr.cpp:279`, `:319-322` at
                // master 5cd2917a; `:267`, `:307-309` at v1.4.2.0), so it
                // ignores one sent on an exchange the device opened earlier.
                // We honour that one too: only the authenticated peer can send
                // it, and it can close only its own session.
                if is_initiator
                    && matter_transport::secure_channel::is_close_session(
                        protocol_id,
                        opcode,
                        &payload,
                    )
                {
                    self.on_peer_close_session(session_id).await;
                    return;
                }
                // Pending ops are exchanges we started, so only a message with
                // `I` clear can answer one. A device that starts its own
                // exchange with the same id (legal: each side allocates its own
                // ids, Matter 1.4 Core §4.10.2) sends `I=1`, and that is a
                // different exchange (§4.10.5.1; chip
                // `ExchangeContext::MatchExchange`).
                if !is_initiator && self.pending.contains_key(&(session_id, exchange_id)) {
                    self.resolve_pending(session_id, exchange_id, protocol_id, opcode, payload)
                        .await;
                    // chip's `ExchangeContext::MessageHandled`: once the
                    // handler is done and nothing more is expected, the
                    // exchange closes, and the close flushes its ACK. Every
                    // terminal branch above already flushed before answering
                    // its caller; this catches any that did not. Skipped while
                    // the exchange is still pending (a timed action, a chunked
                    // read or write, a subscribe being primed): flushing there
                    // would reclaim an exchange we are about to send on.
                    if !self.pending.contains_key(&(session_id, exchange_id)) {
                        self.finish_exchange(session_id, exchange_id, from).await;
                    }
                } else if opcode == OP_REPORT_DATA && protocol_id == ProtocolId::INTERACTION_MODEL {
                    self.deliver_report(session_id, exchange_id, !is_initiator, from, &payload)
                        .await;
                } else {
                    // A message no handler wants. chip, with no delegate for
                    // an exchange, flushes its ACK at once
                    // (`ExchangeContext.cpp:556-562` at master 5cd2917a,
                    // `:549-554` at v1.4.2.0); so do we, rather than leave it
                    // to the 200 ms timer. On the exchange it arrived on: the
                    // device's if it set `I`, ours otherwise.
                    self.finish_exchange_as(session_id, exchange_id, !is_initiator, from)
                        .await;
                }
            }
            DecodeInboundOutput::DuplicateReliableAckResent { ack_packet, .. } => {
                let _ = self.transport.send_to(&ack_packet, from).await;
            }
            // AckOnly (no app payload), and — `DecodeInboundOutput` being
            // `#[non_exhaustive]` — any future outcome: nothing to route here.
            _ => {}
        }
    }

    /// Resolve a pending op identified by `(session, exchange)`. For a
    /// round-trip, reply with the payload. For a read, accumulate the chunk and,
    /// if more chunks follow, ack to solicit the next; otherwise reply with all
    /// chunks. For a subscribe handshake, buffer/ack priming reports and finish
    /// on the `SubscribeResponse`.
    ///
    /// `protocol_id` reaches only the subscribe handshake, the one consumer
    /// that checks it.
    async fn resolve_pending(
        &mut self,
        session_id: SessionId,
        exchange_id: u16,
        protocol_id: ProtocolId,
        opcode: u8,
        payload: Vec<u8>,
    ) {
        // Classify by variant, dropping the borrow before we remove/await.
        enum Kind {
            RoundTrip,
            ChunkedWrite,
            Read,
            Subscribe,
            Timed,
            Action,
        }
        let key = (session_id, exchange_id);
        let kind = match self.pending.get(&key) {
            Some(p) => match &p.reply {
                PendingReply::RoundTrip(_) => Kind::RoundTrip,
                PendingReply::ChunkedWrite { .. } => Kind::ChunkedWrite,
                PendingReply::Read { .. } => Kind::Read,
                PendingReply::Subscribe { .. } => Kind::Subscribe,
                PendingReply::TimedAction { .. } => Kind::Timed,
                PendingReply::Action { .. } => Kind::Action,
            },
            None => return,
        };
        match kind {
            Kind::RoundTrip => {
                if let Some(p) = self.pending.remove(&key) {
                    self.abort_exchange(session_id, exchange_id, p.peer).await;
                    if let PendingReply::RoundTrip(reply) = p.reply {
                        let _ = reply.send(Ok(payload));
                    }
                }
            }
            Kind::ChunkedWrite => {
                self.resolve_chunked_write(session_id, exchange_id, opcode, payload)
                    .await;
            }
            Kind::Read => {
                let peer = self.pending.get(&key).map(|p| p.peer);
                // Parse the chunk exactly once here; `Node::read` consumes the
                // parsed structs directly (no second TLV walk). `total_bytes` is
                // accounted from the wire length before parsing.
                let chunk_len = payload.len();
                let rd = match matter_interaction::parse_report_data(&payload) {
                    Ok(rd) => rd,
                    Err(e) => {
                        // A malformed chunk fails the read, matching the old
                        // `Node::read` behaviour where re-parsing surfaced the
                        // error to the caller via `?`.
                        if let Some(p) = self.pending.remove(&key) {
                            self.finish_exchange(session_id, exchange_id, p.peer).await;
                            if let PendingReply::Read { reply, .. } = p.reply {
                                let _ = reply.send(Err(Error::InteractionModel(e)));
                            }
                        }
                        return;
                    }
                };
                let more = rd.more_chunked_messages;
                let over = match self.pending.get_mut(&key).map(|p| &mut p.reply) {
                    Some(PendingReply::Read {
                        chunks,
                        total_bytes,
                        ..
                    }) => {
                        *total_bytes = total_bytes.saturating_add(chunk_len);
                        chunks.push(rd);
                        chunks.len() > MAX_READ_CHUNKS || *total_bytes > MAX_READ_BYTES
                    }
                    _ => return,
                };
                if over {
                    if let Some(p) = self.pending.remove(&key) {
                        self.finish_exchange(session_id, exchange_id, p.peer).await;
                        if let PendingReply::Read { reply, .. } = p.reply {
                            let _ = reply.send(Err(Error::Operational("read too large".into())));
                        }
                    }
                } else if more {
                    // Ack this chunk on the same exchange to solicit the next.
                    if let Some(peer) = peer {
                        if let Ok(counter) =
                            self.send_chunk_ack(session_id, exchange_id, peer).await
                        {
                            self.note_reliable_send(key, counter);
                        }
                    }
                } else if let Some(p) = self.pending.remove(&key) {
                    self.finish_exchange(session_id, exchange_id, p.peer).await;
                    if let PendingReply::Read { reply, chunks, .. } = p.reply {
                        let _ = reply.send(Ok(chunks));
                    }
                }
            }
            Kind::Subscribe => {
                self.resolve_subscribe(session_id, exchange_id, protocol_id, opcode, payload)
                    .await;
            }
            Kind::Timed => {
                self.resolve_timed(session_id, exchange_id, payload).await;
            }
            Kind::Action => {
                self.resolve_action(session_id, exchange_id, payload).await;
            }
        }
    }

    /// Drive a timed handshake on the device's `StatusResponse` to our
    /// `TimedRequest`. On SUCCESS, send the action on the SAME exchange and
    /// convert the pending into a [`PendingReply::RoundTrip`] awaiting the action
    /// response. On a non-success/unparseable status, resolve the caller with the
    /// raw bytes so it can surface the status.
    async fn resolve_timed(&mut self, sid: SessionId, exchange: u16, payload: Vec<u8>) {
        let success = matches!(
            matter_interaction::parse_status_response(&payload),
            Ok(Some(0))
        );
        let Some(p) = self.pending.remove(&(sid, exchange)) else {
            return;
        };
        if p.reply.action_stopped() {
            self.abort_exchange(sid, exchange, p.peer).await;
            Self::fail_pending(
                p,
                Error::Operational("action deadline elapsed or caller dropped".into()),
            );
            return;
        }
        let PendingReply::TimedAction {
            action_opcode,
            action_payload,
            mut reply,
        } = p.reply
        else {
            return;
        };
        if !success {
            // The device rejected the TimedRequest (e.g. TIMED_REQUEST_MISMATCH)
            // or sent an unexpected message — hand the bytes back to the caller.
            self.abort_exchange(sid, exchange, p.peer).await;
            let _ = reply.send(Ok(payload));
            return;
        }
        let counter = match reply
            .until_stopped(self.send_on_exchange(
                sid,
                exchange,
                p.peer,
                action_opcode,
                &action_payload,
            ))
            .await
        {
            Ok(counter) => counter,
            Err(e) => {
                self.abort_exchange(sid, exchange, p.peer).await;
                let _ = reply.send(Err(e));
                return;
            }
        };
        // Await the action's response on the same exchange as a normal round-trip.
        self.pending.insert(
            (sid, exchange),
            Pending {
                response_deadline: Instant::now() + self.response_deadline,
                node_id: p.node_id,
                peer: p.peer,
                request: PendingRequest {
                    opcode: action_opcode,
                    protocol_id: ProtocolId::INTERACTION_MODEL,
                    payload: action_payload,
                },
                retried: true, // mid-handshake; do not trigger the reconnect-once dance
                last_reliable_send: Some(counter),
                reply: PendingReply::RoundTrip(reply),
            },
        );
    }

    /// Drive a chunked write's next chunk on the response to the chunk that
    /// just came back — chip's `WriteClient` allows exactly one outstanding
    /// `WriteRequest` per exchange (Matter §8.7.4 / §10.6). Mirrors
    /// [`Self::resolve_timed`]'s re-register-on-the-same-exchange shape, but
    /// unlike `resolve_timed` this checks `opcode` explicitly: a device that
    /// rejects a chunk outright (e.g. Busy) replies with a message-level
    /// `StatusResponse` (chip's `WriteHandler`: `StatusResponse::Send` then
    /// `Close`), not a `WriteResponse` — parsing that as a `WriteResponse`
    /// would misread it as `Ok(vec![])` (a vacuous "all Success") and pump
    /// the next chunk into a transaction the device has already closed.
    ///
    /// - If `opcode` is not [`OP_WRITE_RESPONSE`]: TERMINAL. If it's
    ///   [`OP_STATUS_RESPONSE`], parse the status and resolve `reply` with an
    ///   `Err` naming it; for any other opcode, resolve `reply` with an `Err`
    ///   naming the unexpected opcode. Either way, `remaining` is dropped —
    ///   no further chunks are sent.
    /// - Otherwise parse `payload` as a `WriteResponse`
    ///   ([`matter_interaction::parse_write_response`]). A parse failure is
    ///   also TERMINAL (`Err` to `reply`, `remaining` dropped) — chip only
    ///   aborts on a malformed response, not a bad element status.
    /// - On a successful parse, append its statuses to the accumulated
    ///   `statuses`. If `remaining` is empty, this was the final chunk:
    ///   resolve `reply` with `Ok(statuses)` (the full accumulated list).
    ///   Otherwise send the next chunk on the SAME exchange UNCONDITIONALLY
    ///   (chip's `WriteClient` pumps every chunk regardless of individual
    ///   element statuses — `WriteClient.cpp:583-593`) and re-register the
    ///   pending with what remains. A send failure resolves `reply` with the
    ///   error.
    async fn resolve_chunked_write(
        &mut self,
        sid: SessionId,
        exchange: u16,
        opcode: u8,
        payload: Vec<u8>,
    ) {
        let Some(p) = self.pending.remove(&(sid, exchange)) else {
            return;
        };
        let PendingReply::ChunkedWrite {
            reply,
            mut remaining,
            mut statuses,
        } = p.reply
        else {
            return;
        };

        if opcode != OP_WRITE_RESPONSE {
            let err = if opcode == OP_STATUS_RESPONSE {
                match matter_interaction::parse_status_response(&payload) {
                    Ok(Some(status)) => Error::Operational(format!(
                        "chunked write rejected by device: IM status 0x{status:02x}"
                    )),
                    _ => Error::Operational(
                        "chunked write rejected by device: malformed StatusResponse".into(),
                    ),
                }
            } else {
                Error::Operational(format!(
                    "chunked write: unexpected response opcode 0x{opcode:02x} (expected WriteResponse)"
                ))
            };
            self.finish_exchange(sid, exchange, p.peer).await;
            let _ = reply.send(Err(err));
            return;
        }

        let chunk_statuses = match matter_interaction::parse_write_response(&payload) {
            Ok(s) => s,
            Err(e) => {
                self.finish_exchange(sid, exchange, p.peer).await;
                let _ = reply.send(Err(Error::InteractionModel(e)));
                return;
            }
        };
        statuses.extend(chunk_statuses);

        let Some(next) = remaining.pop_front() else {
            // Final chunk: resolve with every chunk's accumulated statuses.
            self.finish_exchange(sid, exchange, p.peer).await;
            let _ = reply.send(Ok(statuses));
            return;
        };
        let counter = match self
            .send_on_exchange(sid, exchange, p.peer, OP_WRITE_REQUEST, &next)
            .await
        {
            Ok(counter) => counter,
            Err(e) => {
                self.finish_exchange(sid, exchange, p.peer).await;
                let _ = reply.send(Err(e));
                return;
            }
        };
        self.pending.insert(
            (sid, exchange),
            Pending {
                response_deadline: Instant::now() + self.response_deadline,
                node_id: p.node_id,
                peer: p.peer,
                request: PendingRequest {
                    opcode: OP_WRITE_REQUEST,
                    protocol_id: ProtocolId::INTERACTION_MODEL,
                    payload: next,
                },
                retried: true, // see the ChunkedWrite insert in handle_chunked_write
                last_reliable_send: Some(counter),
                reply: PendingReply::ChunkedWrite {
                    reply,
                    remaining,
                    statuses,
                },
            },
        );
    }

    /// Send `payload` (opcode `opcode`) on an EXISTING exchange — reuses the wire
    /// exchange id via `encode_outbound(.., Some(exchange), ..)`, exactly like
    /// [`Self::send_chunk_ack`]. Reliable. Sends the Write/Invoke half of a timed
    /// interaction on the same exchange as the preceding `TimedRequest`.
    /// Returns the message's counter, for [`Pending::last_reliable_send`].
    async fn send_on_exchange(
        &mut self,
        sid: SessionId,
        exchange: u16,
        peer: SocketAddr,
        opcode: u8,
        payload: &[u8],
    ) -> Result<MessageCounter, Error> {
        // A pending exchange, so one we started (`I=1`).
        let out = self.sessions.encode_outbound_with_role(
            sid,
            exchange,
            true,
            opcode,
            ProtocolId::INTERACTION_MODEL,
            payload,
            MrpFlags { reliable: true },
            Instant::now(),
        )?;
        self.transport
            .send_to(&out.wire_bytes, peer)
            .await
            .map_err(|e| Error::Operational(format!("timed action send: {e}")))?;
        Ok(out.message_counter)
    }

    /// Reliable `StatusResponse(SUCCESS)` on a read exchange to solicit the next
    /// chunk (mirrors `secured_read`'s per-chunk ack). Returns the message's
    /// counter, for [`Pending::last_reliable_send`].
    async fn send_chunk_ack(
        &mut self,
        sid: SessionId,
        exchange: u16,
        peer: SocketAddr,
    ) -> Result<MessageCounter, Error> {
        let status = matter_interaction::build_status_response(0);
        // The read is a pending exchange, so one we started (`I=1`).
        let out = self.sessions.encode_outbound_with_role(
            sid,
            exchange,
            true,
            OP_STATUS_RESPONSE,
            ProtocolId::INTERACTION_MODEL,
            &status,
            MrpFlags { reliable: true },
            Instant::now(),
        )?;
        self.transport
            .send_to(&out.wire_bytes, peer)
            .await
            .map_err(|e| Error::Operational(format!("chunk ack send: {e}")))?;
        Ok(out.message_counter)
    }

    /// Deliver a steady-state `ReportData` to its subscription
    /// ([`Self::match_report`]), reassembling chunks and resetting the liveness
    /// deadline, then ack on the report's own exchange.
    ///
    /// A report that cannot be delivered is answered on its exchange rather
    /// than dropped, as chip's `InteractionModelEngine::OnUnsolicitedReportData`
    /// answers it:
    ///
    /// - no subscription of ours matches it, or the one that does has a
    ///   consumer that is gone (it is reaped — up front, or here when a send
    ///   finds the report receiver closed): `StatusResponse(InvalidSubscription)`,
    ///   so the device drops that subscription at once (Matter 1.4 §8.5)
    ///   instead of pushing reports nobody reads;
    /// - it does not parse, or carries no `SubscriptionId`:
    ///   `StatusResponse(InvalidAction)`.
    ///
    /// No amplification: only a message that decrypts on a known session gets
    /// here, the reply is one-for-one, and MRP bounds it. Consequence, as in
    /// chip: a report that overtakes a lost `SubscribeResponse`'s
    /// retransmission matches nothing yet, draws `InvalidSubscription`, and so
    /// tears that fresh subscription down; it comes back through liveness and
    /// resubscribe.
    ///
    /// `is_local_initiator` is the role of the exchange the report arrived on
    /// (false for the usual device-initiated report), so every answer goes
    /// back on that exchange and no other with the same id.
    async fn deliver_report(
        &mut self,
        session_id: SessionId,
        exchange_id: u16,
        is_local_initiator: bool,
        from: SocketAddr,
        payload: &[u8],
    ) {
        let (mut rd, wire_sub_id, sub_id) = match self.match_report(session_id, from, payload) {
            Ok(matched) => matched,
            Err(stray) => {
                self.answer_stray_report(session_id, exchange_id, is_local_initiator, from, stray)
                    .await;
                return;
            }
        };
        let now = Instant::now();
        let Some(entry) = self.subscriptions.get_mut(&sub_id) else {
            debug_assert!(false, "match_report returned a missing subscription");
            return;
        };
        entry.liveness_deadline =
            now + std::time::Duration::from_secs(u64::from(entry.max_interval)) + LIVENESS_GRACE;
        let peer = entry.peer;
        // Events have no merge semantics — forward them immediately, bypassing the
        // attribute reassembler. Take them out before `push_parsed` consumes `rd`.
        // Both the event loop and `push_parsed` borrow `entry` mutably, so the
        // event forwarding completes before the reassembler call.
        let mut consumer_gone = false;
        for ev in std::mem::take(&mut rd.events) {
            // try_send_event: never blocks the actor loop; a full buffer drops +
            // counts (coalesced `Lagged`), a closed receiver reaps the sub.
            if !entry.tx.try_send_event(ev) {
                consumer_gone = true;
                break;
            }
        }
        // `rd` was parsed once (to read its `subscription_id`); hand the
        // parsed struct straight to the reassembler rather than re-parsing the
        // same bytes inside `push`.
        if !consumer_gone {
            if let Some(attrs) = entry.reassembler.push_parsed(rd) {
                for (path, value) in attrs {
                    // try_send: never blocks the actor loop. A full buffer drops the
                    // report and counts it (surfaced later as a coalesced `Lagged`);
                    // a closed receiver means the consumer is gone — reap the sub.
                    if !entry.tx.try_send_report(AttributeReport { path, value }) {
                        consumer_gone = true;
                        break;
                    }
                }
            }
        }
        if consumer_gone {
            // Reaped: we no longer hold it, so tell the device.
            self.remove_subscription(sub_id);
            self.answer_stray_report(
                session_id,
                exchange_id,
                is_local_initiator,
                from,
                StrayReport {
                    subscription_id: Some(wire_sub_id),
                    reason: "consumer gone",
                    status: IM_STATUS_INVALID_SUBSCRIPTION,
                },
            )
            .await;
            return;
        }
        let _ = self
            .send_status_ack(session_id, exchange_id, is_local_initiator, peer)
            .await;
    }

    /// Parse a steady-state report and find the subscription it belongs to
    /// ([`Self::find_report_subscription`]): `(the parsed report, its
    /// subscription id, our subscription)`, or why it cannot be delivered. A
    /// matched subscription whose consumer is gone is reaped here and reported
    /// as stray (only after the lookup).
    fn match_report(
        &mut self,
        session_id: SessionId,
        from: SocketAddr,
        payload: &[u8],
    ) -> Result<(matter_interaction::ReportData, u32, SubId), StrayReport> {
        let Ok(rd) = matter_interaction::parse_report_data(payload) else {
            return Err(StrayReport {
                subscription_id: None,
                reason: "malformed",
                status: IM_STATUS_INVALID_ACTION,
            });
        };
        let Some(wire_sub_id) = rd.subscription_id else {
            return Err(StrayReport {
                subscription_id: None,
                reason: "no subscription id",
                status: IM_STATUS_INVALID_ACTION,
            });
        };
        let invalid_subscription = move |reason: &'static str| StrayReport {
            subscription_id: Some(wire_sub_id),
            reason,
            status: IM_STATUS_INVALID_SUBSCRIPTION,
        };
        let Some(sub_id) = self.find_report_subscription(session_id, wire_sub_id, from) else {
            return Err(invalid_subscription("unknown subscription"));
        };
        if self
            .subscriptions
            .get(&sub_id)
            .is_some_and(|entry| entry.tx.consumer_gone())
        {
            self.remove_subscription(sub_id);
            return Err(invalid_subscription("consumer gone"));
        }
        Ok((rd, wire_sub_id, sub_id))
    }

    /// The subscription a steady-state report belongs to, re-keyed to
    /// `session_id` when it was established on another session.
    ///
    /// 1. An exact `(session, subscription id)` hit in `sub_index`.
    /// 2. Otherwise (fabric, node, subscription id), as chip finds a report's
    ///    subscription: the arriving session's fabric and peer node (a CASE
    ///    session carries both in its [`matter_transport::PeerHint`]) and the
    ///    report's subscription id. A publisher may report on any session it
    ///    holds with us, and since a liveness timeout opens a new session while
    ///    siblings stay on the old one, the two can differ. The session's
    ///    fabric must be the sole fabric, the only one a subscription is made
    ///    on ([`Self::session_for`]); a session with no fabric or node id
    ///    (PASE), on another fabric, or with no sole fabric to compare
    ///    against, matches nothing. Exactly one match is delivered and moved
    ///    to this session through [`Self::insert_subscription`], so the
    ///    keep-first-owner rule holds (chip moves its session holder the same
    ///    way). None or several matches — several only from a device reusing
    ///    a subscription id, which is not compliant — count as unknown.
    ///
    /// A re-keyed subscription also takes the arriving session's peer address
    /// (else `from`, where the report came from): a cross-session hit is
    /// exactly when the device may have moved — a fresh CASE session after a
    /// reboot or a DHCP renewal — and acks sent to the stale address would make
    /// the device tear the subscription down.
    fn find_report_subscription(
        &mut self,
        session_id: SessionId,
        wire_sub_id: u32,
        from: SocketAddr,
    ) -> Option<SubId> {
        if let Some(&sub_id) = self.sub_index.get(&(session_id, wire_sub_id)) {
            return Some(sub_id);
        }
        let peer = &self.sessions.get(session_id)?.peer;
        let node_id = peer.node_id?.0;
        if peer.fabric_id? != self.sole_fabric().ok()?.fabric_id {
            return None;
        }
        let mut matching = self
            .subscriptions
            .iter()
            .filter(|(_, e)| e.node_id == node_id && e.wire_sub_id == wire_sub_id)
            .map(|(id, _)| *id);
        let sub_id = matching.next()?;
        if matching.next().is_some() {
            return None;
        }
        let mut entry = self.remove_subscription(sub_id)?;
        let old_session = entry.session_id;
        entry.session_id = session_id;
        entry.peer = self
            .sessions
            .get(session_id)
            .and_then(|s| s.peer_addr)
            .unwrap_or(from);
        self.insert_subscription(sub_id, entry);
        // Moved away, the old session may now be referenced by nothing.
        self.remove_session_if_orphaned(old_session);
        Some(sub_id)
    }

    /// Answer a steady-state report that cannot be delivered with
    /// `StatusResponse(stray.status)` on its own exchange (`exchange_id` with
    /// role `is_local_initiator`), and log why.
    async fn answer_stray_report(
        &mut self,
        session_id: SessionId,
        exchange_id: u16,
        is_local_initiator: bool,
        peer: SocketAddr,
        stray: StrayReport,
    ) {
        let node = self
            .sessions
            .get(session_id)
            .and_then(|s| s.peer.node_id)
            .map_or_else(|| "unknown".to_string(), |n| format!("{:016X}", n.0));
        let StrayReport {
            subscription_id,
            reason,
            status,
        } = stray;
        tracing::debug!(
            target: "matter_controller::actor",
            node = %node,
            subscription_id = ?subscription_id,
            reason,
            status = format_args!("0x{status:02x}"),
            "answering a report that cannot be delivered",
        );
        let _ = self
            .send_status(session_id, exchange_id, is_local_initiator, peer, status)
            .await;
    }

    /// Send a `SubscribeRequest` and register a pending subscribe handshake. The
    /// report receiver is handed back via `reply` once the `SubscribeResponse`
    /// arrives (see [`Self::resolve_subscribe`]); priming reports that precede it
    /// flow through the same channel.
    ///
    /// The request's `KeepSubscriptions` comes from
    /// [`Self::keep_subscriptions_for`]; `excluding` is `None` because this
    /// subscription's `SubId` is allocated only once the request is sent.
    // Mirrors the `Command::Subscribe` variant's fields one-for-one; bundling them
    // into a params struct would only move the same set behind one name.
    #[allow(clippy::too_many_arguments)]
    async fn start_subscribe(
        &mut self,
        node_id: u64,
        paths: Vec<matter_interaction::ReadPath>,
        event_paths: Vec<matter_interaction::EventPath>,
        event_filters: Vec<matter_interaction::EventFilter>,
        min_interval: u16,
        max_interval: u16,
        reply: oneshot::Sender<Result<SubEstablished, Error>>,
    ) {
        let (sid, peer) = match self.session_for(node_id).await {
            Ok(v) => v,
            Err(e) => {
                let _ = reply.send(Err(e));
                return;
            }
        };
        let req =
            matter_interaction::build_subscribe_request(&matter_interaction::SubscribeRequest {
                keep_subscriptions: self.keep_subscriptions_for(node_id, None),
                min_interval_floor: min_interval,
                max_interval_ceiling: max_interval,
                paths: paths.clone(),
                event_paths: event_paths.clone(),
                event_filters: event_filters.clone(),
            });
        match self
            .send_request(
                sid,
                peer,
                OP_SUBSCRIBE_REQUEST,
                ProtocolId::INTERACTION_MODEL,
                &req,
            )
            .await
        {
            Ok((exchange, counter)) => {
                let sub_id = SubId(self.next_sub_id);
                self.next_sub_id += 1;
                // Bounded report channel + reliable control channel. The bounded
                // cap is the memory-DoS guard; control events bypass it.
                let (report_tx, report_rx) =
                    mpsc::channel::<SubscriptionEvent>(SUBSCRIPTION_CHANNEL_CAP);
                let (ctrl_tx, ctrl_rx) = mpsc::unbounded_channel::<SubscriptionEvent>();
                let report_tx = ReportSink {
                    report_tx,
                    ctrl_tx,
                    dropped: 0,
                    max_event_delivered: None,
                };
                let report_rx = SubReceivers { report_rx, ctrl_rx };
                self.pending.insert(
                    (sid, exchange),
                    Pending {
                        response_deadline: Instant::now() + self.response_deadline,
                        node_id,
                        peer,
                        request: PendingRequest {
                            opcode: OP_SUBSCRIBE_REQUEST,
                            protocol_id: ProtocolId::INTERACTION_MODEL,
                            payload: req,
                        },
                        retried: false,
                        last_reliable_send: Some(counter),
                        reply: PendingReply::Subscribe {
                            sub_id,
                            reply: Some(reply),
                            report_tx,
                            report_rx: Some(report_rx),
                            priming: Box::new(ReportReassembler::default()),
                            node_id,
                            paths,
                            event_paths,
                            event_filters,
                            min_interval,
                            max_interval,
                            retry_count: 0,
                        },
                    },
                );
            }
            Err(e) => {
                let _ = reply.send(Err(e));
            }
        }
    }

    /// Drive the subscribe handshake on its exchange.
    ///
    /// - `ReportData`: a priming chunk ([`Self::resolve_priming_report`]).
    /// - `SubscribeResponse`: the end of the handshake
    ///   ([`Self::resolve_subscribe_response`]).
    /// - Anything else that is an Interaction Model message ends the attempt
    ///   through [`Self::fail_subscribe_attempt`]: a `StatusResponse` with a
    ///   non-success status is a rejection, a Success one or one that does not
    ///   parse as a bare status is a protocol error, and any other opcode is an
    ///   unexpected message.
    ///
    /// A message that is not an Interaction Model one is ignored, whatever its
    /// opcode: the protocol is checked before anything else, so a Secure
    /// Channel opcode 0x01 is never read as a `StatusResponse`, and a non-IM
    /// 0x04 / 0x05 is no longer taken for a `SubscribeResponse` / priming
    /// report either (uniform with the steady-state report path).
    async fn resolve_subscribe(
        &mut self,
        session_id: SessionId,
        exchange_id: u16,
        protocol_id: ProtocolId,
        opcode: u8,
        payload: Vec<u8>,
    ) {
        // Not an Interaction Model message: not ours to judge.
        if protocol_id != ProtocolId::INTERACTION_MODEL {
            return;
        }
        let key = (session_id, exchange_id);
        match opcode {
            OP_REPORT_DATA => self.resolve_priming_report(key, &payload).await,
            OP_SUBSCRIBE_RESPONSE => self.resolve_subscribe_response(key, &payload).await,
            OP_STATUS_RESPONSE => {
                let Some(p) = self.pending.remove(&key) else {
                    return;
                };
                let cause = match matter_interaction::parse_status_response(&payload) {
                    Ok(Some(0)) => SubscribeFailure::UnexpectedMessage(OP_STATUS_RESPONSE),
                    Ok(Some(status)) => SubscribeFailure::Rejected(status),
                    Ok(None) => SubscribeFailure::Malformed(
                        matter_interaction::ImError::UnexpectedValue("not a bare StatusResponse"),
                    ),
                    Err(e) => SubscribeFailure::Malformed(e),
                };
                self.fail_subscribe_attempt(key, p, cause).await;
            }
            _ => {
                let Some(p) = self.pending.remove(&key) else {
                    return;
                };
                self.fail_subscribe_attempt(key, p, SubscribeFailure::UnexpectedMessage(opcode))
                    .await;
            }
        }
    }

    /// A priming `ReportData` on a subscribe exchange: parse it, then ack it
    /// (which solicits the next chunk), then forward its events and merge its
    /// attributes into the priming reassembler.
    ///
    /// The ack follows the parse, as chip's `ReadClient::ProcessReportData`
    /// sends its Success only after a good parse. A chunk that does not parse
    /// fails the attempt ([`SubscribeFailure::Malformed`], answered
    /// `InvalidAction`) instead of being Success-acked and skipped, which
    /// established the subscription on a silently incomplete priming dump. The
    /// parse is synchronous in this handler, so the reply still piggybacks the
    /// MRP ack.
    async fn resolve_priming_report(&mut self, key: (SessionId, u16), payload: &[u8]) {
        let mut rd = match matter_interaction::parse_report_data(payload) {
            Ok(rd) => rd,
            Err(e) => {
                if let Some(p) = self.pending.remove(&key) {
                    self.fail_subscribe_attempt(key, p, SubscribeFailure::Malformed(e))
                        .await;
                }
                return;
            }
        };
        if let Some(peer) = self.pending.get(&key).map(|p| p.peer) {
            // A priming report arrives on our subscribe exchange.
            if let Ok(counter) = self.send_status_ack(key.0, key.1, true, peer).await {
                self.note_reliable_send(key, counter);
            }
        }
        if let Some(Pending {
            reply: PendingReply::Subscribe {
                report_tx, priming, ..
            },
            ..
        }) = self.pending.get_mut(&key)
        {
            // Priming events bypass the reassembler too — forward immediately.
            for ev in std::mem::take(&mut rd.events) {
                if !report_tx.try_send_event(ev) {
                    break;
                }
            }
            if let Some(attrs) = priming.push_parsed(rd) {
                for (path, value) in attrs {
                    // Priming reports are bounded the same way as steady-state
                    // ones: try_send, drop+count on a full buffer.
                    if !report_tx.try_send_report(AttributeReport { path, value }) {
                        break;
                    }
                }
            }
        }
    }

    /// The `SubscribeResponse` that ends a subscribe handshake: register the
    /// subscription under `(session, subscriptionId)` and hand the report
    /// receiver back to an initial subscribe's caller.
    ///
    /// One that does not parse fails the attempt
    /// ([`SubscribeFailure::Malformed`], answered `InvalidAction`): an initial
    /// subscribe's caller gets the parse error, as before, and a resubscribe is
    /// rescheduled on its backoff — it used to be dropped, ending the
    /// consumer's stream with no cause.
    async fn resolve_subscribe_response(&mut self, key: (SessionId, u16), payload: &[u8]) {
        let Some(p) = self.pending.remove(&key) else {
            return;
        };
        let resp = match matter_interaction::parse_subscribe_response(payload) {
            Ok(resp) => resp,
            Err(e) => {
                self.fail_subscribe_attempt(key, p, SubscribeFailure::Malformed(e))
                    .await;
                return;
            }
        };
        // The SubscribeResponse ends the subscribe exchange; reports arrive
        // on exchanges the device opens.
        self.finish_exchange(key.0, key.1, p.peer).await;
        let PendingReply::Subscribe {
            sub_id,
            reply,
            report_tx,
            report_rx,
            node_id,
            paths,
            event_paths,
            event_filters,
            min_interval,
            // What we asked for: the caller's ceiling, carried unchanged
            // through every resubscribe.
            max_interval: max_interval_ceiling,
            ..
        } = p.reply
        else {
            return;
        };
        // The episode (if this was one) ends here, established — and only
        // here. A failed attempt stays in its episode, so its advert cooldown
        // stamp must survive the failure; removing it before the parse let a
        // device that keeps answering with a malformed response be
        // advert-pulled on every advert.
        self.resubscribe_pulled_at.remove(&sub_id);
        // Liveness uses the *negotiated* max interval (the device's agreed
        // reporting cadence); a resubscribe re-requests the caller's
        // `max_interval_ceiling` (see `SubEntry`).
        let deadline = Instant::now()
            + std::time::Duration::from_secs(u64::from(resp.max_interval))
            + LIVENESS_GRACE;
        // Signal (re-)establishment to the consumer on the reliable control
        // channel BEFORE inserting, so we can reap on a dead receiver. Control
        // events are never dropped by report backpressure (chip's
        // OnSubscriptionEstablished). Any priming Reports already flowed — they
        // precede the SubscribeResponse on the wire. If the consumer's receiver
        // is already gone (a resubscribe raced a cancel/Drop), do not insert a
        // zombie SubEntry that resubscribes forever.
        if !report_tx.send_control(SubscriptionEvent::Established {
            subscription_id: resp.subscription_id,
            max_interval: resp.max_interval,
        }) {
            return;
        }
        self.insert_subscription(
            sub_id,
            SubEntry {
                tx: report_tx,
                peer: p.peer,
                reassembler: ReportReassembler::default(),
                session_id: key.0,
                wire_sub_id: resp.subscription_id,
                node_id,
                paths,
                event_paths,
                event_filters,
                min_interval,
                max_interval: resp.max_interval,
                max_interval_ceiling,
                liveness_deadline: deadline,
            },
        );
        // Initial subscribe hands the receivers back; a resubscribe
        // (reply/report_rx None) reuses the consumer's existing ones.
        if let (Some(reply), Some(rx)) = (reply, report_rx) {
            let _ = reply.send(Ok((rx, sub_id)));
        }
    }

    /// Send an application `StatusResponse` carrying `status` on an existing
    /// exchange, `exchange` with role `is_local_initiator` (false for a
    /// device-initiated report, true for a priming report on our subscribe
    /// exchange); it also piggybacks the MRP ack for what arrived there. Sent
    /// reliably, for the reason given on [`Self::send_status_ack`]. Returns
    /// the message's counter, for [`Pending::last_reliable_send`].
    async fn send_status(
        &mut self,
        sid: SessionId,
        exchange: u16,
        is_local_initiator: bool,
        peer: SocketAddr,
        status: u8,
    ) -> Result<MessageCounter, Error> {
        let payload = matter_interaction::build_status_response(status);
        let out = self.sessions.encode_outbound_with_role(
            sid,
            exchange,
            is_local_initiator,
            OP_STATUS_RESPONSE,
            ProtocolId::INTERACTION_MODEL,
            &payload,
            MrpFlags { reliable: true },
            Instant::now(),
        )?;
        self.transport
            .send_to(&out.wire_bytes, peer)
            .await
            .map_err(|e| Error::Operational(format!("status response send: {e}")))?;
        Ok(out.message_counter)
    }

    /// Send an application `StatusResponse(Success)` on a subscription exchange
    /// (also piggybacks the MRP ack for the received report).
    ///
    /// Sent RELIABLY, as chip does (`StatusResponse::Send` →
    /// `ExchangeContext::SendMessage` requests an ack whenever the session
    /// allows MRP). If an unreliable answer is lost — common on Thread — the
    /// device retransmits its `ReportData`, the duplicate earns only a
    /// standalone MRP ack (the dedup path never re-delivers), no
    /// `StatusResponse` ever arrives, and the device tears the subscription
    /// down. Reliable, MRP retransmits the answer (piggyback ack included)
    /// until the device acks it. A retransmit that expires on a steady-state
    /// report matches no pending op and is dropped; during the subscribe
    /// handshake it goes through [`Self::on_pending_timeout`] like any other
    /// MRP expiry of the pending subscribe.
    async fn send_status_ack(
        &mut self,
        sid: SessionId,
        exchange: u16,
        is_local_initiator: bool,
        peer: SocketAddr,
    ) -> Result<MessageCounter, Error> {
        self.send_status(sid, exchange, is_local_initiator, peer, 0)
            .await
    }

    /// Record `counter` as the last reliable message sent on the pending op
    /// `key` ([`Pending::last_reliable_send`]). No-op if `key` is not pending.
    fn note_reliable_send(&mut self, key: (SessionId, u16), counter: MessageCounter) {
        if let Some(p) = self.pending.get_mut(&key) {
            p.last_reliable_send = Some(counter);
        }
    }

    /// Close `exchange` on `sid` the way chip's `ExchangeContext::DoClose`
    /// does (`ExchangeContext.cpp:239` at master 5cd2917a, `:237` at
    /// v1.4.2.0): send the exchange's buffered standalone ACK now instead of
    /// leaving it to the 200 ms timer, and reclaim the exchange. Our own
    /// retransmits keep running (chip's `Close()`).
    ///
    /// Every terminal branch calls this BEFORE it answers its caller, so the
    /// ACK is on the wire by the time the caller's `.await` returns, even if
    /// the caller then drops the controller and the runtime with it. Never
    /// call it mid-exchange (a `TimedRequest`'s `StatusResponse`, a chunked
    /// write's chunk response, a read chunk with `MoreChunkedMessages`, a
    /// priming report): that would reclaim an exchange we are about to send
    /// on, and the send would go out with `I=0`. A second call finds nothing
    /// to send.
    ///
    /// `peer` is the pending's `peer` (where the request went, and where every
    /// follow-up on the exchange goes) in the terminal branches, and the
    /// inbound's source in the catch-all. The two are equal unless the
    /// device's address changes mid-exchange, in which case the ACK follows
    /// the exchange's other follow-ups to the pending's `peer`. chip ACKs to
    /// the session's latest peer address, which it updates from every inbound
    /// message on the session, before decrypting it (`SessionManager.cpp`
    /// `:902-905` at master 5cd2917a, `:911-914` at v1.4.2.0).
    ///
    /// `exchange` is one we started: every caller but the catch-all in
    /// [`Self::handle_inbound`] closes a pending op, and pending ops are
    /// always ours. A device exchange that reuses the id keeps its own ACK.
    async fn finish_exchange(&mut self, sid: SessionId, exchange: u16, peer: SocketAddr) {
        self.finish_exchange_as(sid, exchange, true, peer).await;
    }

    /// [`Self::finish_exchange`] for an exchange of either role:
    /// `is_local_initiator` is true for one we started, false for one the
    /// device started.
    async fn finish_exchange_as(
        &mut self,
        sid: SessionId,
        exchange: u16,
        is_local_initiator: bool,
        peer: SocketAddr,
    ) {
        for event in self
            .sessions
            .finish_exchange_with_role(sid, exchange, is_local_initiator)
        {
            self.send_ack_event(event, Some(peer)).await;
        }
    }

    /// [`Self::finish_exchange`] with abort semantics (chip's `Abort()` →
    /// `DoClose(true)`): send the exchange's owed ACK, then drop our own
    /// retransmits on it. For an exchange we are abandoning, which is always
    /// one we started (a pending op), so the device's exchange with the same
    /// id, if any, keeps its retransmits.
    ///
    /// Invariant: application bytes must not outlive their reply guard. Every
    /// terminal removal of an Action/TimedAction/RoundTrip pending aborts,
    /// including success and timed fallback; a retry transfers the guard to a
    /// new exchange only after aborting the old one.
    async fn abort_exchange(&mut self, sid: SessionId, exchange: u16, peer: SocketAddr) {
        for event in self.sessions.abort_exchange_with_role(sid, exchange, true) {
            self.send_ack_event(event, Some(peer)).await;
        }
    }

    /// Remove session `sid` on purpose, first taking the standalone ACKs it
    /// still owes (`SessionManager::flush_session_acks`) and queueing them for
    /// [`Self::send_queued_acks`]. Returns whether a session was removed.
    ///
    /// matter.js sends these when it closes a session (`Session.ts:279-284`).
    /// chip, in effect, does not: its release path reaches `FlushAcks` only
    /// after the session holder is released (`Session.h:178-184`), so the send
    /// fails with `CHIP_ERROR_CONNECTION_ABORTED` (`ExchangeContext.cpp:101` at
    /// master 5cd2917a, `:99` at v1.4.2.0). Best effort, like every flush.
    ///
    /// Synchronous because `remove_session_if_orphaned` is, and its callers
    /// (`check_liveness`, `find_report_subscription`) too: the packets are
    /// built and addressed while the session still exists (its stamped
    /// `peer_addr`, set at CASE registration), and sent on the next loop turn.
    fn release_session(&mut self, sid: SessionId) -> bool {
        for event in self.sessions.flush_session_acks(sid) {
            match event {
                MrpEvent::SendStandaloneAck { packet, .. } => {
                    if let Some(to) = self.peer_for_session(sid) {
                        self.queued_acks.push((to, packet));
                    }
                }
                // As in `send_ack_event`: an exhausted session sends nothing.
                MrpEvent::SessionCounterExhausted {
                    session_id,
                    exchange_id,
                    ..
                } => {
                    tracing::debug!(
                        target: "matter_controller::actor",
                        session_id = session_id.0,
                        exchange_id,
                        "standalone ACK not sent: the session's message counter is exhausted"
                    );
                }
                // `MrpEvent` is `#[non_exhaustive]`; a session flush yields
                // only the two above.
                _ => {}
            }
        }
        self.sessions.remove(sid).is_some()
    }

    /// The device closed session `sid` with a `CloseSession` (Matter 1.4 Core
    /// §4.11.1.4). Remove it and everything that leads to it, as the spec
    /// requires of a node that receives one. chip marks the session for
    /// eviction (`UnsolicitedStatusHandler.cpp:55`); matter.js force-closes it
    /// (`SecureChannelProtocol.ts:86-88`).
    ///
    /// - **Routes** on `sid` are evicted, so the next request to the node
    ///   opens a fresh CASE session. Its resumption record is kept: the spec
    ///   lets the device keep resumption state too.
    /// - **Subscriptions** on `sid` go straight into the resubscribe queue, as
    ///   a liveness timeout would put them, without waiting for one: their
    ///   reports can no longer be decrypted.
    /// - **In-flight requests** on `sid` can no longer be answered. A
    ///   resubscribe attempt, and a read or initial subscribe not yet
    ///   retried, take [`Self::on_pending_timeout`]: reconnect and re-send
    ///   once, or reschedule. They are idempotent (#126). Every other request
    ///   (an invoke, a timed action, a write, a raw round trip, or a read or
    ///   subscribe already retried) fails at once: the device may have
    ///   executed it, so it is not re-sent (#119). chip fails every exchange
    ///   on a released session with a timeout
    ///   (`ExchangeContext::OnSessionReleased`).
    /// - **The session** goes last, through [`Self::release_session`], which
    ///   first queues any ACK it still owes (none for a conformant
    ///   `CloseSession`, which asks for no ACK).
    ///
    /// Nothing is sent in reply: a `CloseSession` is not answered.
    async fn on_peer_close_session(&mut self, sid: SessionId) {
        tracing::debug!(
            target: "matter_controller::actor",
            session_id = sid.0,
            "the device closed the session (CloseSession); evicting it"
        );
        let routes: Vec<(u64, u64)> = self
            .cache
            .iter()
            .filter(|(_, c)| c.session_id == sid)
            .map(|(key, _)| *key)
            .collect();
        for (fabric_id, node_id) in routes {
            self.evict_cached_route_if(fabric_id, node_id, sid);
        }
        let subs: Vec<SubId> = self
            .subscriptions
            .iter()
            .filter(|(_, e)| e.session_id == sid)
            .map(|(id, _)| *id)
            .collect();
        for sub_id in subs {
            self.begin_resubscribe(
                sub_id,
                Error::Operational(SubscribeFailure::SessionClosed.to_string()),
            );
        }
        let keys: Vec<(SessionId, u16)> = self
            .pending
            .keys()
            .filter(|(s, _)| *s == sid)
            .copied()
            .collect();
        for key in keys {
            let retry = match self.pending.get(&key) {
                Some(p) => {
                    matches!(&p.reply, PendingReply::Subscribe { reply: None, .. })
                        || (!p.retried
                            && matches!(
                                &p.reply,
                                PendingReply::Read { .. } | PendingReply::Subscribe { .. }
                            ))
                }
                None => continue,
            };
            if retry {
                self.on_pending_timeout(key.0, key.1, SubscribeFailure::SessionClosed)
                    .await;
            } else if let Some(p) = self.pending.remove(&key) {
                let node_id = p.node_id;
                Self::fail_pending(
                    p,
                    Error::Operational(format!(
                        "node {node_id:016X}: the device closed the session (CloseSession) \
                         before answering"
                    )),
                );
            }
        }
        self.release_session(sid);
    }

    /// Send the ACKs [`Self::release_session`] queued. Best effort.
    async fn send_queued_acks(&mut self) {
        for (to, packet) in std::mem::take(&mut self.queued_acks) {
            let _ = self.transport.send_to(&packet, to).await;
        }
    }

    /// Put one flushed or timer-fired standalone ACK on the wire, best effort:
    /// chip ignores a failed `FlushAcks` too, because a lost ACK only makes
    /// the device retransmit, and the duplicate path ACKs that.
    ///
    /// `peer` overrides the session's address when the caller knows where the
    /// exchange's messages came from. A counter-exhausted session sends
    /// nothing (logged at debug): it cannot send anything more until it is
    /// replaced.
    async fn send_ack_event(&mut self, event: MrpEvent, peer: Option<SocketAddr>) {
        let (packet, to) = match event {
            MrpEvent::SendStandaloneAck {
                session_id, packet, ..
            } => (packet, peer.or_else(|| self.peer_for_session(session_id))),
            MrpEvent::SessionCounterExhausted {
                session_id,
                exchange_id,
                ..
            } => {
                tracing::debug!(
                    target: "matter_controller::actor",
                    session_id = session_id.0,
                    exchange_id,
                    "standalone ACK not sent: the session's message counter is exhausted"
                );
                return;
            }
            // `MrpEvent` is `#[non_exhaustive]`; retransmits and expiries are
            // not ACKs.
            _ => return,
        };
        if let Some(to) = to {
            let _ = self.transport.send_to(&packet, to).await;
        }
    }

    /// Drive MRP for all sessions: send retransmits/standalone-acks, and on
    /// `Expired` resolve the matching pending op — retrying once on a fresh
    /// session if the cached one was stale (preserves the original
    /// reconnect-once policy).
    async fn abort_stopped_action(&mut self, sid: SessionId, exchange: u16) -> bool {
        if !self
            .pending
            .get(&(sid, exchange))
            .is_some_and(|p| p.reply.action_stopped())
        {
            return false;
        }
        if let Some(p) = self.pending.remove(&(sid, exchange)) {
            self.abort_exchange(sid, exchange, p.peer).await;
            Self::fail_pending(
                p,
                Error::Operational("action deadline elapsed or caller dropped".into()),
            );
        }
        true
    }

    async fn drive_mrp(&mut self) {
        let mut stopped: std::collections::HashSet<_> = self
            .pending
            .iter()
            .filter_map(|(key, p)| p.reply.action_stopped().then_some(*key))
            .collect();
        for (sid, exchange) in stopped.iter().copied() {
            self.abort_stopped_action(sid, exchange).await;
        }
        // Address each standalone ACK now, while its session still exists. A
        // session's `Expired` comes before its ACKs in the batch, and its
        // `on_pending_timeout` can orphan and release the session
        // (`remove_session_if_orphaned`). The ACK has already left the
        // session's MRP state, so the release's flush cannot see it, and a
        // lookup after the release would find no address.
        let events: Vec<(MrpEvent, Option<SocketAddr>)> = self
            .sessions
            .handle_timeout(Instant::now())
            .into_iter()
            .map(|event| {
                let ack_peer = match &event {
                    MrpEvent::SendStandaloneAck { session_id, .. } => {
                        self.peer_for_session(*session_id)
                    }
                    _ => None,
                };
                (event, ack_peer)
            })
            .collect();
        for (event, ack_peer) in events {
            match event {
                MrpEvent::Retransmit {
                    session_id,
                    exchange_id,
                    packet,
                    ..
                } => {
                    if stopped.contains(&(session_id, exchange_id))
                        || self.abort_stopped_action(session_id, exchange_id).await
                    {
                        stopped.insert((session_id, exchange_id));
                        continue;
                    }
                    if let Some(peer) = self.peer_for_session(session_id) {
                        let send = async {
                            self.transport
                                .send_to(&packet, peer)
                                .await
                                .map_err(|e| Error::Operational(format!("request send: {e}")))
                        };
                        if let Some(reply) = self
                            .pending
                            .get_mut(&(session_id, exchange_id))
                            .and_then(|p| p.reply.action_reply_mut())
                        {
                            let _ = reply.until_stopped(send).await;
                        } else {
                            let _ = send.await;
                        }
                    }
                }
                MrpEvent::Expired {
                    session_id,
                    exchange_id,
                    counter,
                } => {
                    // The event names the exchange by id alone. It is the
                    // pending op's own expiry only if it is the op's last
                    // reliable message; otherwise it is one of our reliable
                    // answers on a device exchange with the same id, which MRP
                    // has already given up on (`Pending::last_reliable_send`).
                    let ours = self
                        .pending
                        .get(&(session_id, exchange_id))
                        .is_some_and(|p| p.last_reliable_send == Some(counter));
                    if ours {
                        self.on_pending_timeout(
                            session_id,
                            exchange_id,
                            SubscribeFailure::MrpExpired,
                        )
                        .await;
                    } else {
                        tracing::debug!(
                            target: "matter_controller::actor",
                            session_id = session_id.0,
                            exchange_id,
                            counter = counter.0,
                            "MRP gave up on a message that is no pending op's own"
                        );
                    }
                }
                // Standalone ACKs and an exhausted counter take the same path
                // as a close's flush. `MrpEvent` is `#[non_exhaustive]`;
                // `send_ack_event` ignores what it does not know.
                other => self.send_ack_event(other, ack_peer).await,
            }
        }
    }

    /// Fail every pending op whose response deadline has elapsed.
    ///
    /// This is the counterpart to [`Self::drive_mrp`], and it exists because
    /// MRP cannot cover this case: MRP bounds *delivery*, and the moment a peer
    /// ACKs a request its retransmit entry is dropped. A device that accepts a
    /// request and then never sends the Interaction Model response therefore
    /// leaves nothing at the exchange layer to expire, and the caller's oneshot
    /// waits forever (#119, reproduced on a Tapo H100 bridge that silently
    /// drops the 9th consecutive read on a session).
    ///
    /// Unlike [`Self::on_pending_timeout`], a fired deadline here does **not**
    /// reconnect and re-send. That path exists for MRP expiry, where the
    /// absence of an ACK means the request most likely never arrived, so
    /// re-sending is safe. Here delivery may have been confirmed (a short
    /// response deadline can also beat MRP expiry), so the device may have
    /// executed a non-idempotent command already. The op is failed
    /// with [`Error::ResponseTimeout`] and whether to retry is the caller's
    /// decision.
    ///
    /// A resubscribe attempt (a `Subscribe` pending with no reply channel) is
    /// the one exception: it is routed through [`Self::on_pending_timeout`] so
    /// it keeps its existing reschedule-on-backoff behaviour rather than being
    /// silently dropped.
    async fn drive_response_deadlines(&mut self) {
        let now = Instant::now();
        let expired: Vec<(SessionId, u16)> = self
            .pending
            .iter()
            .filter(|(_, p)| p.response_deadline <= now)
            .map(|(k, _)| *k)
            .collect();
        for key in expired {
            // Re-check: an earlier iteration may have resolved or replaced this
            // entry (a resubscribe reschedule re-inserts under the same key).
            let Some(p) = self.pending.get(&key) else {
                continue;
            };
            if p.response_deadline > now {
                continue;
            }
            if matches!(&p.reply, PendingReply::Subscribe { reply: None, .. }) {
                self.on_pending_timeout(key.0, key.1, SubscribeFailure::ResponseDeadline)
                    .await;
                continue;
            }
            // A READ is idempotent, so a fired response deadline on one takes
            // the same reconnect-and-resend-once path MRP expiry uses
            // ([`Self::on_pending_timeout`]) instead of failing outright.
            //
            // #119 established that a fired response deadline must not trigger
            // a re-send, because delivery was ACKed and a re-send could execute
            // a non-idempotent command twice. That reasoning is right, but it
            // was applied to every pending kind and only holds for some: a read
            // cannot change device state, so re-sending one is free of that
            // hazard. `Action`, `TimedAction`, `ChunkedWrite` and the raw
            // `RoundTrip` (opaque payload — may well be an invoke) keep failing
            // immediately, unchanged.
            //
            // Mechanism-agnostic on purpose (#126): a bridge that drops the
            // Nth consecutive read may be rate-limiting or may have wedged the
            // session, and we cannot tell which from here. The reconnect covers
            // the wedged case and the deadline itself supplies the spacing for
            // the rate-limited one. Healthy devices never reach the deadline,
            // so this costs them nothing.
            //
            // `!p.retried` matters for more than avoiding a loop: it means a
            // read that times out AGAIN after its retry falls through to the
            // arm below and still fails with `Error::ResponseTimeout`, rather
            // than the generic round-trip error `on_pending_timeout` uses when
            // it gives up.
            if !p.retried && matches!(&p.reply, PendingReply::Read { .. }) {
                tracing::debug!(
                    node_id = format_args!("{:016X}", p.node_id),
                    exchange_id = key.1,
                    "operational response deadline elapsed on a read; \
                     reconnecting and re-sending once (reads are idempotent)"
                );
                self.on_pending_timeout(key.0, key.1, SubscribeFailure::ResponseDeadline)
                    .await;
                continue;
            }
            // `get` above only borrowed; remove for real now.
            let Some(p) = self.pending.remove(&key) else {
                continue;
            };
            self.abort_exchange(key.0, key.1, p.peer).await;
            let node_id = p.node_id;
            let after = self.response_deadline;
            tracing::debug!(
                node_id = format_args!("{node_id:016X}"),
                exchange_id = key.1,
                after_secs = after.as_secs(),
                "operational response deadline elapsed; failing the request \
                 (non-idempotent requests are not retried)"
            );
            Self::fail_pending(p, Error::ResponseTimeout { node_id, after });
        }
    }

    /// A pending op timed out. If it ran on a stale cached session and has not
    /// yet been retried, evict the session, reconnect, and re-send once on the
    /// new session; otherwise resolve it with a timeout error.
    ///
    /// `cause` says which timeout fired; it reaches the resubscribe failure log.
    async fn on_pending_timeout(
        &mut self,
        session_id: SessionId,
        exchange_id: u16,
        cause: SubscribeFailure,
    ) {
        let Some(p) = self.pending.remove(&(session_id, exchange_id)) else {
            return;
        };
        // A retry uses a new exchange. Abort the old one even if MRP has
        // not expired yet (the response deadline can fire first).
        self.abort_exchange(session_id, exchange_id, p.peer).await;
        // A resubscribe attempt (no oneshot reply) reschedules on the backoff
        // rather than failing — chip retries forever. An INITIAL subscribe
        // (reply `Some`) does not come here: it falls through to the
        // reconnect-and-re-send-once path below, as in 0.16.
        if matches!(&p.reply, PendingReply::Subscribe { reply: None, .. }) {
            // A consumer that dropped both receivers evicts nothing: its attempt
            // is dropped below, and the route may still serve a sibling
            // (a backstop: the `Drop` cancel is a lossy `try_send`).
            let consumer_gone = matches!(
                &p.reply,
                PendingReply::Subscribe { report_tx, .. } if report_tx.consumer_gone()
            );
            // The attempt timed out — the cached session is likely dead (most
            // commonly a device reboot, which invalidates CASE). Drop the
            // ROUTE so the next attempt runs a fresh handshake, as the
            // round-trip branch below does; leave the session registered —
            // other subscriptions and in-flight invokes may still be using it,
            // and if it is dead they exhaust on their own and reconnect through
            // that branch. Only if the cache still holds the expired session: a
            // sibling may already have replaced it with a healthy one. With the
            // route kept, `handle_connect_done` strands nothing (it strands
            // only when the cache still holds the old route).
            if !consumer_gone {
                if let Ok(fabric_id) = self.sole_fabric().map(|f| f.fabric_id) {
                    self.evict_cached_route_if(fabric_id, p.node_id, session_id);
                }
            }
            self.fail_subscribe_attempt((session_id, exchange_id), p, cause)
                .await;
            // With this attempt's pending gone, nothing may reference the
            // session any more.
            self.remove_session_if_orphaned(session_id);
            return;
        }
        // ChunkedWrite pendings are always inserted with `retried: true` —
        // both the initial insert in `handle_chunked_write` and every
        // re-insert in `resolve_chunked_write` set it — so a timeout on one
        // always skips the `!p.retried` branch below and falls straight
        // through to `fail_pending`, never attempting a reconnect-resend
        // mid-transaction (see the rationale at those insert sites).
        if !p.retried {
            let Ok(fabric_id) = self.sole_fabric().map(|f| f.fabric_id) else {
                Self::fail_pending(p, Error::Operational("round-trip timed out".into()));
                return;
            };
            // Only evict if the cache still holds the *expired* session. A
            // sibling op may have already timed out, evicted it, reconnected, and
            // cached a fresh healthy session under this node — dropping that here
            // would force a redundant CASE handshake and churn every subscription
            // just bound to the new session.
            self.evict_cached_route_if(fabric_id, p.node_id, session_id);
            // `p` is already out of `pending` and its re-send targets the new
            // session, so the old one may now be referenced by nothing; if so,
            // it is removed. The reconnect and re-send below serve every op
            // alike.
            self.remove_session_if_orphaned(session_id);
            // M9-G-d: re-send on a cached fresh session if a sibling already
            // reconnected, else reconnect OFF the actor loop (the handshake no
            // longer blocks other sessions) and re-send on completion.
            if let Some((sid, peer)) = self
                .cache
                .get(&(fabric_id, p.node_id))
                .map(|c| (c.session_id, c.peer))
            {
                self.resume_resend_pending(p, sid, peer).await;
            } else {
                self.enqueue_connect_waiter(fabric_id, p.node_id, ConnectWaiter::ResendPending(p));
            }
            return;
        }
        Self::fail_pending(p, Error::Operational("round-trip timed out".into()));
    }

    /// Resolve a pending op's reply channel with an error.
    fn fail_pending(p: Pending, err: Error) {
        match p.reply {
            PendingReply::RoundTrip(reply)
            | PendingReply::TimedAction { reply, .. }
            | PendingReply::Action { reply, .. } => {
                let _ = reply.send(Err(err));
            }
            // Distinct arm: `ChunkedWrite`'s reply carries parsed per-path
            // statuses, not raw bytes, so it cannot merge into the arm above.
            PendingReply::ChunkedWrite { reply, .. } => {
                let _ = reply.send(Err(err));
            }
            PendingReply::Read { reply, .. } => {
                let _ = reply.send(Err(err));
            }
            PendingReply::Subscribe { reply, .. } => {
                if let Some(reply) = reply {
                    let _ = reply.send(Err(err));
                }
            }
        }
    }

    /// One subscribe attempt failed: the single path every failure cause takes,
    /// so they all behave alike.
    ///
    /// - **Answer** (`key` is the attempt's exchange): a failure caused by a
    ///   message on the exchange ([`SubscribeFailure::arrived_on_the_wire`]) is
    ///   answered `StatusResponse(InvalidAction)`, as chip's
    ///   `ReadClient::OnMessageReceived` answers on every error exit. A timeout
    ///   sends nothing.
    /// - **Initial subscribe** (`reply: Some`): the caller gets
    ///   [`SubscribeFailure::into_initial_error`]; nothing is rescheduled (the
    ///   caller retries, as before).
    /// - **Resubscribe** (`reply: None`): rebuilt into a [`PendingResubscribe`]
    ///   and rescheduled on its backoff, its event filters re-bumped to the
    ///   delivery watermark exactly as [`Self::begin_resubscribe`] does — an
    ///   attempt can fail mid-priming, after some priming events already
    ///   reached the consumer, and the next attempt's priming dump must not
    ///   replay them. The episode continues, so the advert cooldown stamp stays.
    ///   Retrying a rejection forever, including effectively permanent
    ///   statuses, is deliberate chip parity; the backoff spaces the retries
    ///   out to at most one per ~92 min.
    /// - **Consumer gone** (a resubscribe whose consumer dropped both
    ///   receivers): dropped with its cooldown stamp; nothing is rescheduled
    ///   (a backstop: the `Drop` cancel is a lossy `try_send`).
    ///
    /// Nothing is evicted here; the timeout caller decides that.
    async fn fail_subscribe_attempt(
        &mut self,
        key: (SessionId, u16),
        pending: Pending,
        cause: SubscribeFailure,
    ) {
        if cause.arrived_on_the_wire() {
            // Best effort: the attempt is over whether or not the device hears it.
            let _ = self
                .send_status(key.0, key.1, true, pending.peer, IM_STATUS_INVALID_ACTION)
                .await;
        }
        // Only subscribe pendings are ever handed here.
        let PendingReply::Subscribe {
            sub_id,
            reply,
            report_tx,
            node_id,
            paths,
            event_paths,
            event_filters,
            min_interval,
            max_interval,
            retry_count,
            ..
        } = pending.reply
        else {
            return;
        };
        if let Some(reply) = reply {
            let _ = reply.send(Err(cause.into_initial_error()));
            return;
        }
        if report_tx.consumer_gone() {
            self.resubscribe_pulled_at.remove(&sub_id);
            return;
        }
        // Read the watermark before `report_tx` moves into the record.
        let watermark = report_tx.max_event_delivered;
        self.reschedule_resubscribe(
            PendingResubscribe {
                sub_id,
                attempt_at: Instant::now(),
                node_id,
                paths,
                event_paths,
                event_filters: bump_event_filters(event_filters, watermark),
                min_interval,
                max_interval,
                retry_count,
                tx: report_tx,
            },
            &cause,
        );
    }

    /// Insert/replace a subscription, keeping `sub_index` in lock-step.
    /// A resubscribe re-inserts the same `SubId` with a NEW
    /// `(session_id, wire_sub_id)` — the old index key is removed first
    /// (guarded: only if it still points at this `SubId`, see below).
    ///
    /// `wire_sub_id` comes from the device's `SubscribeResponse` — it is
    /// remote-influenced input, not our own bookkeeping. A non-compliant or
    /// hostile device can reuse a subscription id it already owns on a
    /// session for a second, distinct subscription, so two live `SubEntry`s
    /// CAN legitimately contend for one `(session_id, wire_sub_id)` key.
    /// This is handled as **keep-first-owner**: the key is claimed only when
    /// vacant or already owned by this `sub_id`; if a different `SubId`
    /// already holds it, that owner's index entry is left untouched and the
    /// new entry is simply left unindexed. An unindexed entry is not found by
    /// [`Self::find_report_subscription`]'s exact `(session, subscription id)`
    /// lookup, but once the index owner is gone (cancelled, or removed to
    /// resubscribe) the cross-session lookup finds it as the only match for
    /// its node and subscription id and re-keys it to the session the report
    /// arrived on, which indexes it. Failing that, its own liveness deadline
    /// drives a resubscribe, which asks the device for a fresh id. This is no
    /// worse than the old linear scan's arbitrary pick between two colliding
    /// entries, and unlike a blind overwrite it can never orphan the surviving
    /// owner's routing.
    fn insert_subscription(&mut self, sub_id: SubId, entry: SubEntry) {
        let new_key = (entry.session_id, entry.wire_sub_id);
        if let Some(old) = self.subscriptions.insert(sub_id, entry) {
            let old_key = (old.session_id, old.wire_sub_id);
            // Only clear the old key if it still maps to us — a collision
            // on that key (this `sub_id` never won it, see below) means
            // there is nothing of ours to remove there.
            if self.sub_index.get(&old_key) == Some(&sub_id) {
                self.sub_index.remove(&old_key);
            }
        }
        match self.sub_index.get(&new_key) {
            None => {
                self.sub_index.insert(new_key, sub_id);
            }
            Some(&existing) if existing == sub_id => {
                // Already ours (re-insert under an unchanged key) — no-op.
            }
            Some(_) => {
                // Deliberate keep-first-owner: a different live subscription
                // already holds this device-issued key. Leave it alone.
            }
        }
    }

    /// Remove a subscription and its index entry (the only removal path —
    /// a bare `subscriptions.remove` would silently corrupt `sub_index`).
    /// The index key is cleared only if it still maps to this `sub_id`: a
    /// subscription that lost a `(session, wire_sub_id)` collision in
    /// [`Self::insert_subscription`] was never indexed, so there is nothing
    /// to clear for it (and clearing unconditionally would delete the
    /// colliding survivor's live entry).
    fn remove_subscription(&mut self, sub_id: SubId) -> Option<SubEntry> {
        let entry = self.subscriptions.remove(&sub_id)?;
        let key = (entry.session_id, entry.wire_sub_id);
        if self.sub_index.get(&key) == Some(&sub_id) {
            self.sub_index.remove(&key);
        }
        Some(entry)
    }

    /// Remove every subscription bound to `node_id` (`forget_node`). Replaces
    /// the former bulk `retain`, which bypassed index maintenance.
    fn remove_subscriptions_for_node(&mut self, node_id: u64) {
        let ids: Vec<SubId> = self
            .subscriptions
            .iter()
            .filter(|(_, s)| s.node_id == node_id)
            .map(|(id, _)| *id)
            .collect();
        for id in ids {
            self.remove_subscription(id);
        }
    }

    /// Re-subscribe any subscription whose liveness deadline has passed.
    ///
    /// Before each one enters its resubscribe episode, its own cached route is
    /// dropped — if, and only if, it still points at that subscription's
    /// session — so the immediate retry misses the cache and runs a fresh CASE
    /// handshake (cheap with resumption) instead of first spending MRP's
    /// retransmissions, or the response deadline, on a session that has most
    /// likely died. This is chip's `TriggerResubscriptionForLivenessTimeout`,
    /// which marks the timed-out subscription's own session defunct and
    /// resubscribes with `reestablishCASE`. Like chip there is no sibling
    /// guard; a route a newer session already replaced is spared, as chip
    /// spares sessions with newer peer activity. The session stays registered
    /// for siblings and in-flight work — chip's "defunct" is soft too — and is
    /// removed once nothing references it
    /// ([`Self::remove_session_if_orphaned`]). That test runs after
    /// `begin_resubscribe` has removed this subscription, one subscription at a
    /// time, so the last of several stale siblings on a session removes it.
    ///
    /// A subscription whose consumer is gone keeps the route: `begin_resubscribe`
    /// reaps it (its control receiver is closed), so no retry follows and there
    /// is nothing to clear the route for — evicting it would only cost the
    /// node's other users a fresh CASE handshake. Its session still gets the
    /// orphan test.
    ///
    /// The eviction is here, not in `begin_resubscribe`, which
    /// [`Self::resubscribe_stranded`] also calls for a session already replaced.
    fn check_liveness(&mut self) {
        let now = Instant::now();
        let stale: Vec<SubId> = self
            .subscriptions
            .iter()
            .filter(|(_, e)| e.liveness_deadline <= now)
            .map(|(id, _)| *id)
            .collect();
        let fabric_id = self.sole_fabric().map(|f| f.fabric_id).ok();
        for id in stale {
            let Some((node_id, sid, consumer_gone)) = self
                .subscriptions
                .get(&id)
                .map(|e| (e.node_id, e.session_id, e.tx.consumer_gone()))
            else {
                continue;
            };
            let evicted_route = !consumer_gone
                && fabric_id.is_some_and(|f| self.evict_cached_route_if(f, node_id, sid));
            self.begin_resubscribe(
                id,
                Error::Operational("subscription liveness timeout".into()),
            );
            let removed_orphan_session = self.remove_session_if_orphaned(sid);
            if consumer_gone {
                tracing::debug!(
                    target: "matter_controller::actor",
                    node = format_args!("{node_id:016X}"),
                    sub_id = id.0,
                    removed_orphan_session,
                    "subscription liveness timed out; its consumer is gone, so it is reaped",
                );
            } else {
                tracing::debug!(
                    target: "matter_controller::actor",
                    node = format_args!("{node_id:016X}"),
                    sub_id = id.0,
                    evicted_route,
                    removed_orphan_session,
                    "subscription liveness timed out; its retry runs on a fresh CASE session",
                );
            }
        }
    }

    /// Move a stale subscription into the resubscribe queue: emit `Resubscribing`,
    /// drop the dead `SubEntry`, and schedule the first attempt (retry 0 ≈ immediate).
    fn begin_resubscribe(&mut self, sub_id: SubId, cause: Error) {
        let Some(entry) = self.remove_subscription(sub_id) else {
            return;
        };
        // If the consumer dropped its receiver, reap the subscription instead of
        // resubscribing forever (closes the zombie-SubEntry window when a cancel
        // races an in-flight resubscribe, or the Drop cancel was lost). Sent on
        // the reliable control channel so it is never dropped by report backpressure.
        if !entry
            .tx
            .send_control(SubscriptionEvent::Resubscribing { cause })
        {
            self.resubscribe_pulled_at.remove(&sub_id);
            return;
        }
        let wait = resubscribe_backoff(self.rng.as_ref(), 0);
        // Read the watermark before `entry.tx` is moved into the pending record
        // below — see `bump_event_filters`: a device-buffered event must not be
        // replayed late by the fresh subscription's priming dump.
        let watermark = entry.tx.max_event_delivered;
        self.resubscribes.push(PendingResubscribe {
            sub_id,
            attempt_at: Instant::now() + wait,
            node_id: entry.node_id,
            paths: entry.paths,
            event_paths: entry.event_paths,
            event_filters: bump_event_filters(entry.event_filters, watermark),
            min_interval: entry.min_interval,
            max_interval: entry.max_interval_ceiling,
            retry_count: 0,
            tx: entry.tx,
        });
    }

    /// Fire any due resubscribe attempts, one at a time.
    ///
    /// A due entry is taken out of `resubscribes` only at the moment it is
    /// attempted, never batched into a local list first. An attempt can reach
    /// the advert path (`attempt_resubscribe` → `enqueue_connect_waiter` →
    /// `spawn_connect` → `drive_pending_resolves`), and everything that path
    /// consults — [`Self::resubscribe_episode_entries`], `trigger_resubscribe`,
    /// the resubscribe watch — must still see the entries not yet attempted.
    ///
    /// The loop ends: every iteration removes one entry, and an entry put back
    /// during the pass is either rescheduled into the future (the backoff at
    /// retry 1 or more is at least 3 s) or pulled to the trigger's own `now`,
    /// which is never earlier than this pass's; a pulled entry is due, and a due
    /// entry is never pulled again, so that can happen at most once per entry.
    async fn drive_resubscribes(&mut self) {
        let now = Instant::now();
        while let Some(i) = self.resubscribes.iter().position(|pr| pr.attempt_at <= now) {
            let pr = self.resubscribes.swap_remove(i);
            self.attempt_resubscribe(pr).await;
        }
    }

    /// One resubscribe attempt: send a fresh `SubscribeRequest` on the node's
    /// cached session and register a pending Subscribe (no oneshot reply) so the
    /// central demux drives the handshake. If the node is not connected, reconnect
    /// OFF the actor loop (the CASE handshake no longer blocks other
    /// sessions) and resume on completion; a missing fabric reschedules on backoff.
    async fn attempt_resubscribe(&mut self, pr: PendingResubscribe) {
        #[cfg(test)]
        self.episode_sizes_at_attempt
            .push(self.resubscribe_episode_entries().count());
        // A consumer that dropped both receivers can never observe this
        // subscription again — reap instead of retrying forever (the drop-side
        // cancel is lossy `try_send`, so this is the reliable reap point).
        if pr.tx.report_tx.is_closed() && pr.tx.ctrl_tx.is_closed() {
            self.resubscribe_pulled_at.remove(&pr.sub_id);
            return;
        }
        let fabric_id = match self.sole_fabric() {
            Ok(fabric) => fabric.fabric_id,
            Err(e) => {
                self.reschedule_resubscribe(pr, &e);
                return;
            }
        };
        if let Some((sid, peer)) = self
            .cache
            .get(&(fabric_id, pr.node_id))
            .map(|c| (c.session_id, c.peer))
        {
            self.resume_resubscribe(pr, sid, peer).await;
        } else {
            self.enqueue_connect_waiter(fabric_id, pr.node_id, ConnectWaiter::Resubscribe(pr));
        }
    }

    /// Reschedule a failed attempt with the next backoff step (retry forever),
    /// and log the failure.
    ///
    /// `cause` is what ended the attempt: the connect error, the send error,
    /// the missing fabric, or which of the two timeouts fired
    /// ([`SubscribeFailure`]). It is only displayed. Before this line
    /// existed a failed attempt left no trace at all, so a device that stayed
    /// unsubscribed for minutes could not be diagnosed from a field log.
    fn reschedule_resubscribe(
        &mut self,
        mut pr: PendingResubscribe,
        cause: &dyn std::fmt::Display,
    ) {
        // Same reap guard as `attempt_resubscribe`: a consumer that dropped
        // both receivers can never observe this subscription again.
        if pr.tx.report_tx.is_closed() && pr.tx.ctrl_tx.is_closed() {
            self.resubscribe_pulled_at.remove(&pr.sub_id);
            return;
        }
        let failed_attempt = pr.retry_count;
        pr.retry_count = pr.retry_count.saturating_add(1);
        let wait = resubscribe_backoff(self.rng.as_ref(), pr.retry_count);
        pr.attempt_at = Instant::now() + wait;
        tracing::debug!(
            target: "matter_controller::actor",
            node = format_args!("{:016X}", pr.node_id),
            sub_id = pr.sub_id.0,
            attempt = failed_attempt,
            next_wait_ms = u64::try_from(wait.as_millis()).unwrap_or(u64::MAX),
            cause = %cause,
            "resubscribe attempt failed; next attempt scheduled",
        );
        #[cfg(test)]
        self.reschedule_causes.push((pr.sub_id, cause.to_string()));
        self.resubscribes.push(pr);
    }

    /// The peer address for `sid`: O(1) from the session's stamped
    /// `peer_addr`; falls back to scanning subscriptions/pending/cache for
    /// sessions that predate stamping (defensive — every prod registration
    /// path stamps).
    fn peer_for_session(&self, sid: SessionId) -> Option<SocketAddr> {
        if let Some(addr) = self.sessions.get(sid).and_then(|s| s.peer_addr) {
            return Some(addr);
        }
        self.subscriptions
            .values()
            .find(|e| e.session_id == sid)
            .map(|e| e.peer)
            .or_else(|| {
                self.pending
                    .iter()
                    .find(|((s, _), _)| *s == sid)
                    .map(|(_, p)| p.peer)
            })
            .or_else(|| {
                self.cache
                    .values()
                    .find(|c| c.session_id == sid)
                    .map(|c| c.peer)
            })
    }
}

/// Convert the current wall-clock time to a [`matter_cert::MatterTime`] for use
/// in `CommissionerConfig.now`.
///
/// # Errors
///
/// Returns [`Error::Operational`] if the system clock is before the Unix epoch
/// (extremely unlikely in practice), or [`Error::SystemClockUnset`] if it reads
/// before the Matter epoch (see [`matter_time_from_unix_secs`]).
pub(crate) fn current_matter_time() -> Result<matter_cert::MatterTime, Error> {
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_err(|e| Error::Operational(format!("clock: {e}")))?
        .as_secs();
    matter_time_from_unix_secs(secs)
}

/// Apply the clock-relative validity checks to a fabric's window, given
/// whatever this host's clock had to say.
///
/// Fabric creation itself needs no clock: `crate::fabric::create_fabric` mints
/// the RCAC, the optional ICAC and the commissioner NOC entirely from
/// `cfg.validity`. The clock is used only to *sanity-check* that caller-supplied
/// window, so an unusable clock means "cannot perform the check", not "cannot
/// create a fabric". We skip it and carry on: a board with no RTC that creates
/// its fabric during init with a hardcoded sane window and reaches an NTP server
/// seconds later is a normal deployment, and refusing it would buy nothing —
/// the certificates are entirely caller-supplied and may be perfectly good.
///
/// What is *not* skipped:
///
/// - The clock-independent half of the check still runs inside `create_fabric`
///   ([`crate::fabric`]'s `validate_validity`): epoch-zero `not_before` and an
///   inverted/empty window are rejected regardless. That matters here, because
///   code following our own documentation derives `not_before` from
///   `SystemTime::now()` — which on an unset clock is pre-2000, i.e. exactly the
///   `MatterTime(0)` that gets rejected. Since we know both facts at this point,
///   we say so explicitly rather than leaving the caller to guess why the
///   wall-clock time they passed was called "the Matter epoch".
/// - Every site that genuinely needs a real time — minting a *device* NOC during
///   commissioning, operational CASE — still calls [`current_matter_time`]
///   directly and still hard-fails with [`Error::SystemClockUnset`].
fn validate_validity_against_clock(
    validity: (matter_cert::MatterTime, matter_cert::MatterTime),
    clock: Result<matter_cert::MatterTime, Error>,
) -> Result<(), Error> {
    match clock {
        Ok(now) => crate::fabric::validate_validity_against_now(validity, now),
        Err(Error::SystemClockUnset(secs)) => {
            if validity.0 == matter_cert::MatterTime(0) {
                return Err(Error::InvalidFabricValidity(format!(
                    "not_before is the Matter epoch (MatterTime(0), 2000-01-01T00:00:00Z), and \
                     this host's clock is unset — it reads unix {secs}, before the Matter epoch — \
                     which is the likely source: MatterTime::from_unix_secs clamps any pre-2000 \
                     time to MatterTime(0). Set the host clock (NTP/RTC) before creating the \
                     fabric, or pass a known-good not_before explicitly"
                )));
            }
            tracing::warn!(
                target: "matter_controller::actor",
                unix_secs = secs,
                "host clock reads before the Matter epoch (unset RTC / pre-NTP); creating the \
                 fabric anyway from the caller-supplied validity window, but its plausibility \
                 could not be checked against a clock. Commissioning and CASE will still fail \
                 until the clock is set."
            );
            Ok(())
        }
        Err(e) => Err(e),
    }
}

/// Convert Unix seconds to a [`matter_cert::MatterTime`], refusing a reading
/// that predates the Matter epoch.
///
/// `MatterTime::from_unix_secs` **saturates** any pre-2000 time to
/// `MatterTime(0)`. On a host whose clock has not been set — embedded Linux
/// with no RTC, before NTP converges, a very plausible deployment — that is
/// exactly what we would get, and `MatterTime(0)` is the one value certificates
/// must never carry as `notBefore`: chip maps it to `99991231235959Z` when it
/// rebuilds the X.509 TBS, so the signature check fails and the certificate is
/// unusable (`ChipEpochToASN1Time`,
/// `connectedhomeip/src/credentials/CHIPCert.cpp`; the same root cause as issue
/// #111, one stage later at `AddNOC` rather than at
/// `AddTrustedRootCertificate`).
///
/// Failing here names the cause — an unset host clock — instead of minting a
/// device NOC that cannot work and letting it fail opaquely on the device.
///
/// # Errors
///
/// Returns [`Error::SystemClockUnset`] if `secs` is before the Matter epoch
/// (2000-01-01T00:00:00Z, Unix `946_684_800`).
fn matter_time_from_unix_secs(secs: u64) -> Result<matter_cert::MatterTime, Error> {
    let now = matter_cert::MatterTime::from_unix_secs(secs);
    if now.0 == 0 {
        return Err(Error::SystemClockUnset(secs));
    }
    Ok(now)
}

