    // --- resubscribe watch (spec 2026-10-01) ---

    const WATCH_SUBTYPE_HANDLE: QueryHandle = QueryHandle(77);
    /// The second subtype handle a [`WatchDiscovery`] in late-attach replay
    /// mode hands out while [`WATCH_SUBTYPE_HANDLE`] is still attached.
    const WATCH_REPLAY_HANDLE: QueryHandle = QueryHandle(78);
    const WATCH_BASE_HANDLE: QueryHandle = QueryHandle(1);
    const WATCH_NODE_A: u64 = 0x0A;
    const WATCH_NODE_B: u64 = 0x0B;

    /// Test-visible state behind a [`WatchDiscovery`]. The actor owns the
    /// discovery, so a test keeps an `Arc` clone of this to inject records and
    /// found events and to read the counters.
    #[derive(Default)]
    struct WatchDiscoveryState {
        /// Drain-once record queues, per browse kind (mdns-sd-like).
        subtype_records: Vec<MatterService>,
        base_records: Vec<MatterService>,
        /// Drain-once found-event queues (instance names), per browse kind.
        subtype_found: Vec<String>,
        base_found: Vec<String>,
        /// Every `query_operational_fabric` / `query` call, failed ones included.
        subtype_opens: usize,
        base_opens: usize,
        /// Every `stop_query` call, in order.
        stops: Vec<QueryHandle>,
        /// Every `poll_found` call, in order.
        found_polls: Vec<QueryHandle>,
        /// Every `requery` call, in order.
        requeries: Vec<QueryHandle>,
        /// Released into `subtype_records` / `subtype_found` by the next
        /// `requery` of the subtype handle: a device that answers a fresh query
        /// but whose own announcement never reached the browse.
        requery_records: Vec<MatterService>,
        requery_found: Vec<String>,
        /// Return the base handle from `query_operational_fabric` too, as a
        /// `Discovery` that keeps the trait default does.
        equal_handles: bool,
        /// Make every open fail.
        fail_opens: bool,
        /// Make only `query_operational_fabric` fail (a daemon that refuses the
        /// subtype but serves the base type).
        fail_subtype_opens: bool,
        /// mdns-sd-like late-attach replay; `None` (the default) keeps every
        /// subtype open returning the one subtype handle.
        replay: Option<LateAttachReplay>,
    }

    /// [`WatchDiscoveryState::replay`]: a `query_operational_fabric` made while
    /// [`WATCH_SUBTYPE_HANDLE`] is still attached returns
    /// [`WATCH_REPLAY_HANDLE`] instead, seeded with `surfaced` (the adapter's
    /// `surfaced` replay). The attached handle itself is never re-sent those
    /// records, as mdns-sd never re-emits an unchanged one.
    #[derive(Default)]
    struct LateAttachReplay {
        /// The last record surfaced per instance on the subtype browse.
        surfaced: Vec<MatterService>,
        /// [`WATCH_REPLAY_HANDLE`]'s drain-once record queue.
        replay_records: Vec<MatterService>,
        /// Whether [`WATCH_SUBTYPE_HANDLE`] is attached (handed out, not yet
        /// stopped).
        subtype_attached: bool,
    }

    /// A [`Discovery`] with separate subtype and base browses, each with its
    /// own drain-once record and found-event queue, plus open/stop/poll
    /// counters, an equal-handles mode, an open-failure mode and an
    /// mdns-sd-like late-attach replay mode.
    struct WatchDiscovery(Arc<std::sync::Mutex<WatchDiscoveryState>>);

    impl Discovery for WatchDiscovery {
        fn publish(&mut self, _s: &MatterService) -> matter_transport::Result<()> {
            Ok(())
        }
        fn unpublish(&mut self, _n: &str, _k: ServiceKind) -> matter_transport::Result<()> {
            Ok(())
        }
        fn query(&mut self, _k: ServiceKind) -> matter_transport::Result<QueryHandle> {
            let mut s = self.0.lock().unwrap();
            s.base_opens += 1;
            if s.fail_opens {
                return Err(matter_transport::Error::Mdns(
                    "injected open failure".into(),
                ));
            }
            Ok(WATCH_BASE_HANDLE)
        }
        fn query_operational_fabric(
            &mut self,
            _compressed_fabric_id: [u8; 8],
        ) -> matter_transport::Result<QueryHandle> {
            let mut s = self.0.lock().unwrap();
            s.subtype_opens += 1;
            if s.fail_opens || s.fail_subtype_opens {
                return Err(matter_transport::Error::Mdns(
                    "injected open failure".into(),
                ));
            }
            if s.equal_handles {
                return Ok(WATCH_BASE_HANDLE);
            }
            if let Some(r) = s.replay.as_mut() {
                if r.subtype_attached {
                    r.replay_records = r.surfaced.clone();
                    return Ok(WATCH_REPLAY_HANDLE);
                }
                r.subtype_attached = true;
            }
            Ok(WATCH_SUBTYPE_HANDLE)
        }
        fn stop_query(&mut self, h: QueryHandle) {
            let mut s = self.0.lock().unwrap();
            if h == WATCH_SUBTYPE_HANDLE {
                if let Some(r) = s.replay.as_mut() {
                    r.subtype_attached = false;
                }
            }
            s.stops.push(h);
        }
        fn poll_results(&mut self, h: QueryHandle) -> Vec<MatterService> {
            let mut s = self.0.lock().unwrap();
            if h == WATCH_SUBTYPE_HANDLE {
                std::mem::take(&mut s.subtype_records)
            } else if h == WATCH_BASE_HANDLE {
                std::mem::take(&mut s.base_records)
            } else if h == WATCH_REPLAY_HANDLE {
                s.replay
                    .as_mut()
                    .map(|r| std::mem::take(&mut r.replay_records))
                    .unwrap_or_default()
            } else {
                Vec::new()
            }
        }
        fn poll_found(&mut self, h: QueryHandle) -> Vec<String> {
            let mut s = self.0.lock().unwrap();
            s.found_polls.push(h);
            if h == WATCH_SUBTYPE_HANDLE {
                std::mem::take(&mut s.subtype_found)
            } else if h == WATCH_BASE_HANDLE {
                std::mem::take(&mut s.base_found)
            } else {
                Vec::new()
            }
        }
        fn requery(&mut self, h: QueryHandle) {
            let mut s = self.0.lock().unwrap();
            s.requeries.push(h);
            if h == WATCH_SUBTYPE_HANDLE {
                let records = std::mem::take(&mut s.requery_records);
                let found = std::mem::take(&mut s.requery_found);
                s.subtype_records.extend(records);
                s.subtype_found.extend(found);
            }
        }
    }

    fn watch_discovery() -> (WatchDiscovery, Arc<std::sync::Mutex<WatchDiscoveryState>>) {
        let state = Arc::new(std::sync::Mutex::new(WatchDiscoveryState::default()));
        (WatchDiscovery(Arc::clone(&state)), state)
    }

    /// [`actor_with_one_fabric`] over a caller-supplied [`Discovery`].
    fn actor_with_one_fabric_using<D: Discovery>(discovery: D) -> Actor<InMemoryDatagram, D> {
        let (io, peer) = InMemoryDatagram::pair();
        keep_endpoint_open(peer);
        let fabric = {
            let cfg = FabricConfig {
                fabric_id: 0x0A0B_0C0D_0E0F_1011,
                rcac_id: 1,
                commissioner_node_id: 1,
                validity: (
                    MatterTime::from_unix_secs(1_700_000_000),
                    MatterTime::NO_EXPIRY,
                ),
                issue_icac: false,
            };
            crate::fabric::create_fabric(&cfg, &SystemNocRng).unwrap()
        };
        Actor::new(
            io,
            discovery,
            Arc::new(MemStore::default()),
            Arc::new(SystemNocRng),
            ControllerState {
                fabrics: vec![fabric],
            },
            None,
            crate::builder::DEFAULT_ADMIN_VENDOR_ID,
        )
    }

    /// A connect that parks while a resubscribe episode waits still gets its
    /// base-type fallback, and releasing it stops only the base: the subtype
    /// browse stays, because it is the resubscribe watch.
    #[tokio::test]
    async fn release_keeps_the_subtype_browse_while_a_resubscribe_episode_waits() {
        let (discovery, state) = watch_discovery();
        let mut actor = actor_with_one_fabric_using(discovery);
        let fabric_id = actor.sole_fabric().unwrap().fabric_id;
        let (queued, _queued_reports, _queued_ctrl) =
            test_pending_resubscribe(1, WATCH_NODE_A, 4, far_future());
        actor.resubscribes.push(queued);
        let (connecting, _connecting_reports, _connecting_ctrl) =
            test_pending_resubscribe(2, WATCH_NODE_B, 0, Instant::now());
        actor.enqueue_connect_waiter(
            fabric_id,
            WATCH_NODE_B,
            ConnectWaiter::Resubscribe(connecting),
        );
        assert_eq!(actor.resolve_query_fabric, Some(WATCH_SUBTYPE_HANDLE));

        // The subtype answered nothing within the window: the base fallback opens.
        actor.resolve_base_after = Some(just_past());
        actor.drive_pending_resolves();
        assert_eq!(actor.resolve_query, Some(WATCH_BASE_HANDLE));

        // B's resolve is abandoned; nothing is parked any more.
        actor.cancel_pending_resolve(WATCH_NODE_B);
        assert!(actor.pending_resolves.is_empty());
        assert_eq!(
            state.lock().unwrap().stops,
            vec![WATCH_BASE_HANDLE],
            "only the base goes"
        );
        assert_eq!(actor.resolve_query, None);
        assert_eq!(
            actor.resolve_query_fabric,
            Some(WATCH_SUBTYPE_HANDLE),
            "the subtype browse is the resubscribe watch while A waits"
        );
    }

    /// Equal handles: a `Discovery` that keeps the trait default hands back ONE
    /// handle for both browses. The base release must not stop it while the
    /// watch holds it; it is stopped exactly once, when the watch lets go
    /// (here: at shutdown).
    #[tokio::test]
    async fn a_handle_shared_by_both_browses_is_stopped_once_when_the_watch_lets_go() {
        let (discovery, state) = watch_discovery();
        state.lock().unwrap().equal_handles = true;
        let mut actor = actor_with_one_fabric_using(discovery);
        let fabric_id = actor.sole_fabric().unwrap().fabric_id;
        let (queued, _queued_reports, _queued_ctrl) =
            test_pending_resubscribe(1, WATCH_NODE_A, 4, far_future());
        actor.resubscribes.push(queued);
        let (connecting, _connecting_reports, _connecting_ctrl) =
            test_pending_resubscribe(2, WATCH_NODE_B, 0, Instant::now());
        actor.enqueue_connect_waiter(
            fabric_id,
            WATCH_NODE_B,
            ConnectWaiter::Resubscribe(connecting),
        );
        actor.resolve_base_after = Some(just_past());
        actor.drive_pending_resolves();
        assert_eq!(actor.resolve_query, Some(WATCH_BASE_HANDLE));
        assert_eq!(actor.resolve_query_fabric, Some(WATCH_BASE_HANDLE));

        actor.cancel_pending_resolve(WATCH_NODE_B);
        assert!(
            state.lock().unwrap().stops.is_empty(),
            "the shared handle is the watch's browse: not stopped by the base release"
        );
        assert_eq!(actor.resolve_query_fabric, Some(WATCH_BASE_HANDLE));

        actor.shutdown_discovery();
        assert_eq!(
            state.lock().unwrap().stops,
            vec![WATCH_BASE_HANDLE],
            "stopped exactly once"
        );
    }

    /// Shutdown releases the watch's browse even though resubscribes are still
    /// queued — a caller-supplied daemon would otherwise run it forever.
    #[tokio::test]
    async fn shutdown_releases_the_watch_with_resubscribes_still_queued() {
        let (discovery, state) = watch_discovery();
        let mut actor = actor_with_one_fabric_using(discovery);
        let fabric_id = actor.sole_fabric().unwrap().fabric_id;
        let (connecting, _connecting_reports, _connecting_ctrl) =
            test_pending_resubscribe(1, WATCH_NODE_A, 0, Instant::now());
        actor.enqueue_connect_waiter(
            fabric_id,
            WATCH_NODE_A,
            ConnectWaiter::Resubscribe(connecting),
        );
        // The connect fails: the episode goes back to the queue, still waiting.
        actor.fail_connect_waiters(WATCH_NODE_A, &Error::Operational("resolve expired".into()));
        assert_eq!(actor.resubscribes.len(), 1);
        assert_eq!(actor.resolve_query_fabric, Some(WATCH_SUBTYPE_HANDLE));

        actor.shutdown_discovery();
        assert_eq!(state.lock().unwrap().stops, vec![WATCH_SUBTYPE_HANDLE]);
        assert_eq!(actor.resolve_query_fabric, None);
    }

    /// An episode whose consumer dropped both receivers is reaped when it next
    /// fires; it must not hold the browse open until then.
    #[tokio::test]
    async fn release_closes_the_subtype_browse_when_only_dead_consumers_wait() {
        let (discovery, state) = watch_discovery();
        let mut actor = actor_with_one_fabric_using(discovery);
        let fabric_id = actor.sole_fabric().unwrap().fabric_id;
        let (queued, report_rx, ctrl_rx) =
            test_pending_resubscribe(1, WATCH_NODE_A, 4, far_future());
        drop(report_rx);
        drop(ctrl_rx);
        actor.resubscribes.push(queued);
        let (connecting, connecting_reports, connecting_ctrl) =
            test_pending_resubscribe(2, WATCH_NODE_B, 0, Instant::now());
        drop(connecting_reports);
        drop(connecting_ctrl);
        actor.enqueue_connect_waiter(
            fabric_id,
            WATCH_NODE_B,
            ConnectWaiter::Resubscribe(connecting),
        );
        actor.cancel_pending_resolve(WATCH_NODE_B);
        assert_eq!(state.lock().unwrap().stops, vec![WATCH_SUBTYPE_HANDLE]);
        assert_eq!(actor.resolve_query_fabric, None);
    }

    /// While `drive_resubscribes` works through several due entries, the ones
    /// not yet attempted must still sit in `resubscribes`, i.e. in the episode
    /// set: an attempt can reach `trigger_resubscribe` and the watch
    /// bookkeeping (`attempt_resubscribe` → `enqueue_connect_waiter` →
    /// `spawn_connect` → `drive_pending_resolves`), and an entry parked in a
    /// local batch would be invisible to both.
    #[tokio::test]
    async fn every_waiting_resubscribe_stays_visible_while_another_is_attempted() {
        // No fabric: every attempt fails at once and is rescheduled into the
        // future, so the pass also has to end.
        let (io, _peer) = InMemoryDatagram::pair();
        let mut actor = Actor::new(
            io,
            NullDiscovery,
            Arc::new(MemStore::default()),
            Arc::new(SystemNocRng),
            ControllerState { fabrics: vec![] },
            None,
            crate::builder::DEFAULT_ADMIN_VENDOR_ID,
        );
        let (first, _first_reports, _first_ctrl) =
            test_pending_resubscribe(1, WATCH_NODE_A, 2, just_past());
        let (second, _second_reports, _second_ctrl) =
            test_pending_resubscribe(2, WATCH_NODE_B, 2, just_past());
        actor.resubscribes.extend([first, second]);
        tokio::time::timeout(Duration::from_secs(5), actor.drive_resubscribes())
            .await
            .expect("the pass must end");
        assert_eq!(
            actor.episode_sizes_at_attempt,
            vec![1, 1],
            "the entry not being attempted must stay in the queue (a local batch gives [0, 1])"
        );
        assert_eq!(
            actor.reschedule_causes.len(),
            2,
            "each due entry attempted exactly once"
        );
        assert!(actor
            .resubscribes
            .iter()
            .all(|pr| pr.attempt_at > Instant::now()));
    }

    /// An operational record for `instance_name` at 127.0.0.1:5540.
    fn op_record(instance_name: &str) -> MatterService {
        MatterService::new(
            instance_name.to_string(),
            ServiceKind::Operational,
            vec!["127.0.0.1".parse().unwrap()],
            5540,
            std::collections::HashMap::new(),
        )
    }

    /// The watch opens the SUBTYPE browse — never the base type, never the base
    /// fallback — once an episode exists with nothing parked, and records the
    /// fabric it was opened for.
    #[tokio::test]
    async fn watch_opens_only_the_subtype_browse_when_an_episode_begins() {
        let (discovery, state) = watch_discovery();
        let mut actor = actor_with_one_fabric_using(discovery);
        actor.reconcile_resubscribe_watch(Instant::now());
        assert_eq!(
            state.lock().unwrap().subtype_opens,
            0,
            "no episode, no watch"
        );

        let (pr, _reports, _ctrl) = test_pending_resubscribe(1, WATCH_NODE_A, 4, far_future());
        actor.resubscribes.push(pr);
        actor.reconcile_resubscribe_watch(Instant::now());
        {
            let s = state.lock().unwrap();
            assert_eq!(s.subtype_opens, 1);
            assert_eq!(s.base_opens, 0, "the watch never opens the base type");
        }
        assert_eq!(actor.resolve_query_fabric, Some(WATCH_SUBTYPE_HANDLE));
        assert_eq!(
            actor.resolve_query_fabric_cfid,
            Some(actor.sole_compressed_fabric_id().unwrap())
        );
        assert!(
            actor.resolve_base_after.is_none(),
            "the watch never arms the fallback"
        );

        actor.reconcile_resubscribe_watch(Instant::now());
        assert_eq!(
            state.lock().unwrap().subtype_opens,
            1,
            "a held watch is not reopened"
        );
    }

    /// The watch stays open through an attempt in flight, its failure, and
    /// a connect that parks — which reuses the held handle — and whose resolve
    /// completing does not close it.
    #[tokio::test]
    async fn watch_stays_open_across_in_flight_and_connecting_attempts() {
        let (discovery, state) = watch_discovery();
        let mut actor = actor_with_one_fabric_using(discovery);
        let fabric_id = actor.sole_fabric().unwrap().fabric_id;
        let cfid = actor.sole_compressed_fabric_id().unwrap();
        let sid = {
            use matter_crypto::pase::PaseSessionKeys;
            let keys = PaseSessionKeys {
                ke: [0u8; 16],
                i2r_key: [1u8; 16],
                r2i_key: [2u8; 16],
                attestation_key: [3u8; 16],
            };
            actor.sessions.register_pase(
                keys,
                SessionRole::Initiator,
                1,
                matter_transport::PeerHint::default(),
            )
        };
        actor.cache.insert(
            (fabric_id, WATCH_NODE_A),
            CachedSession {
                session_id: sid,
                peer: "127.0.0.1:5540".parse().unwrap(),
            },
        );
        let (pr, _reports, _ctrl) = test_pending_resubscribe(1, WATCH_NODE_A, 4, far_future());
        actor.resubscribes.push(pr);
        actor.reconcile_resubscribe_watch(Instant::now());

        // The attempt fires on the cached session: in flight.
        actor.resubscribes[0].attempt_at = just_past();
        actor.drive_resubscribes().await;
        assert_eq!(actor.pending.len(), 1, "a SubscribeRequest is in flight");
        actor.reconcile_resubscribe_watch(Instant::now());
        assert_eq!(
            state.lock().unwrap().stops,
            Vec::<matter_transport::QueryHandle>::new()
        );

        // It times out (the route is gone too), comes back to the queue, fires
        // again and parks behind a connect, which reuses the held subtype.
        actor.cache.clear();
        let key = *actor.pending.keys().next().unwrap();
        actor
            .on_pending_timeout(key.0, key.1, SubscribeFailure::MrpExpired)
            .await;
        actor.resubscribes[0].attempt_at = just_past();
        actor.drive_resubscribes().await;
        assert_eq!(actor.pending_resolves.len(), 1, "the connect parked");
        // The second open is the connect's replay attach (A is not cached).
        // This fake hands the held handle back for it, which the actor must
        // recognise and leave alone: not stopped, its found events not eaten.
        assert_eq!(
            state.lock().unwrap().subtype_opens,
            2,
            "the held handle is reused; only the replay attach is extra"
        );
        assert_eq!(actor.resolve_query_fabric, Some(WATCH_SUBTYPE_HANDLE));
        assert!(
            !state.lock().unwrap().stops.contains(&WATCH_SUBTYPE_HANDLE),
            "a replay attach that returned the held handle must not stop it"
        );
        actor.reconcile_resubscribe_watch(Instant::now());

        // The device's record lands: the resolve completes (the handshake task
        // is spawned) and the watch keeps the browse. Nothing answers that CASE
        // task; it is dropped with the test runtime, which is expected.
        state
            .lock()
            .unwrap()
            .subtype_records
            .push(op_record(&operational_instance_name(cfid, WATCH_NODE_A)));
        actor.drive_pending_resolves();
        assert!(actor.pending_resolves.is_empty());
        actor.reconcile_resubscribe_watch(Instant::now());
        let s = state.lock().unwrap();
        // The parked connect may legitimately have opened (and then released)
        // the base fallback if this machine took longer than the test-build
        // SUBTYPE_ONLY_WINDOW; only the subtype handle matters here.
        assert!(
            !s.stops.contains(&WATCH_SUBTYPE_HANDLE),
            "nothing closed the watch: {:?}",
            s.stops
        );
        assert_eq!(s.subtype_opens, 2, "the watch open and the replay attach");
        drop(s);
        assert_eq!(actor.resolve_query_fabric, Some(WATCH_SUBTYPE_HANDLE));
    }

    /// The watch closes once the episode is established.
    #[tokio::test]
    async fn watch_closes_once_the_episode_is_established() {
        let (discovery, state) = watch_discovery();
        let mut actor = actor_with_one_fabric_using(discovery);
        let (pr, _reports, _ctrl) = test_pending_resubscribe(1, WATCH_NODE_A, 4, Instant::now());
        seed_inflight_resubscribe(&mut actor, (SessionId(7), 0x21), pr, far_future());
        actor.reconcile_resubscribe_watch(Instant::now());
        assert_eq!(actor.resolve_query_fabric, Some(WATCH_SUBTYPE_HANDLE));

        actor
            .resolve_subscribe(
                SessionId(7),
                0x21,
                ProtocolId::INTERACTION_MODEL,
                OP_SUBSCRIBE_RESPONSE,
                build_subscribe_response(0x55, 30),
            )
            .await;
        assert!(
            actor.subscriptions.contains_key(&SubId(1)),
            "re-established"
        );
        actor.reconcile_resubscribe_watch(Instant::now());
        assert_eq!(state.lock().unwrap().stops, vec![WATCH_SUBTYPE_HANDLE]);
        assert_eq!(actor.resolve_query_fabric, None);
        assert_eq!(actor.resolve_query_fabric_cfid, None);
    }

    /// The watch closes when the waiting consumer is gone.
    #[tokio::test]
    async fn watch_closes_when_the_waiting_consumer_is_gone() {
        let (discovery, state) = watch_discovery();
        let mut actor = actor_with_one_fabric_using(discovery);
        let (pr, report_rx, ctrl_rx) = test_pending_resubscribe(1, WATCH_NODE_A, 4, far_future());
        actor.resubscribes.push(pr);
        actor.reconcile_resubscribe_watch(Instant::now());
        drop(report_rx);
        drop(ctrl_rx);
        actor.reconcile_resubscribe_watch(Instant::now());
        assert_eq!(state.lock().unwrap().stops, vec![WATCH_SUBTYPE_HANDLE]);
    }

    /// The watch closes when the node is forgotten.
    #[tokio::test]
    async fn watch_closes_when_the_node_is_forgotten() {
        let (discovery, state) = watch_discovery();
        let mut actor = actor_with_one_fabric_using(discovery);
        let (pr, _reports, _ctrl) = test_pending_resubscribe(1, WATCH_NODE_A, 4, far_future());
        actor.resubscribes.push(pr);
        actor.reconcile_resubscribe_watch(Instant::now());
        let (reply, rx) = oneshot::channel();
        actor
            .dispatch_ready(Command::ForgetNode {
                node_id: WATCH_NODE_A,
                reply,
            })
            .await;
        let _ = rx.await.unwrap();
        actor.reconcile_resubscribe_watch(Instant::now());
        assert_eq!(state.lock().unwrap().stops, vec![WATCH_SUBTYPE_HANDLE]);
    }

    /// A subtype browse opened by `spawn_connect` (where most episodes' first
    /// cache-miss connect opens it) carries its cfid, so the reconcile step
    /// keeps it instead of closing and reopening it — every reopen would
    /// re-flush found events.
    #[tokio::test]
    async fn a_subtype_opened_by_spawn_connect_is_kept_not_reopened() {
        let (discovery, state) = watch_discovery();
        let mut actor = actor_with_one_fabric_using(discovery);
        let fabric_id = actor.sole_fabric().unwrap().fabric_id;
        let (pr, _reports, _ctrl) = test_pending_resubscribe(1, WATCH_NODE_A, 2, Instant::now());
        actor.enqueue_connect_waiter(fabric_id, WATCH_NODE_A, ConnectWaiter::Resubscribe(pr));
        assert_eq!(state.lock().unwrap().subtype_opens, 1);
        actor.fail_connect_waiters(WATCH_NODE_A, &Error::Operational("resolve expired".into()));
        assert!(actor.pending_resolves.is_empty());
        assert_eq!(actor.resubscribes.len(), 1);
        for _ in 0..3 {
            actor.reconcile_resubscribe_watch(Instant::now());
        }
        let s = state.lock().unwrap();
        assert_eq!(s.subtype_opens, 1, "kept, not closed and reopened");
        assert!(s.stops.is_empty(), "{:?}", s.stops);
    }

    /// What [`held_watch_with_b_surfaced`] returns: the actor, the fake's
    /// state, and A's consumer receivers (kept alive by the caller).
    type HeldWatch = (
        Actor<InMemoryDatagram, WatchDiscovery>,
        Arc<std::sync::Mutex<WatchDiscoveryState>>,
        mpsc::Receiver<SubscriptionEvent>,
        mpsc::UnboundedReceiver<SubscriptionEvent>,
    );

    /// The setup every held-watch replay test starts from: an mdns-sd-like
    /// discovery whose subtype browse has already surfaced `WATCH_NODE_B`'s
    /// record (so it will never re-emit it to the attached handle), and an
    /// actor whose resubscribe watch holds that browse because `WATCH_NODE_A`
    /// waits. The returned receivers keep A's consumer alive.
    fn held_watch_with_b_surfaced() -> HeldWatch {
        let (discovery, state) = watch_discovery();
        let mut actor = actor_with_one_fabric_using(discovery);
        let cfid = actor.sole_compressed_fabric_id().unwrap();
        state.lock().unwrap().replay = Some(LateAttachReplay {
            surfaced: vec![op_record(&operational_instance_name(cfid, WATCH_NODE_B))],
            ..LateAttachReplay::default()
        });
        let (pr, reports, ctrl) = test_pending_resubscribe(1, WATCH_NODE_A, 4, far_future());
        actor.resubscribes.push(pr);
        actor.reconcile_resubscribe_watch(Instant::now());
        assert_eq!(actor.resolve_query_fabric, Some(WATCH_SUBTYPE_HANDLE));
        assert_eq!(state.lock().unwrap().subtype_opens, 1);
        (actor, state, reports, ctrl)
    }

    /// While the watch holds the subtype browse, a connect to a healthy node
    /// whose record the actor no longer has cached gets the fresh-browse replay
    /// a per-connect browse used to give it — through a second, short-lived
    /// handle — and resolves in the immediate settle pass, with no base-type
    /// fallback. The extra handle is drained (records AND found events) and
    /// stopped; the watch handle is left alone.
    #[tokio::test]
    async fn a_connect_behind_a_held_watch_resolves_from_the_replay_without_the_base_fallback() {
        let (mut actor, state, _reports, _ctrl) = held_watch_with_b_surfaced();
        let fabric_id = actor.sole_fabric().unwrap().fabric_id;
        let cfid = actor.sole_compressed_fabric_id().unwrap();
        assert!(
            !actor.seen_records.contains_key(
                &Actor::<InMemoryDatagram, WatchDiscovery>::record_key(&operational_instance_name(
                    cfid,
                    WATCH_NODE_B
                ))
            ),
            "precondition: B is not cached"
        );

        let (pr_b, _b_reports, _b_ctrl) =
            test_pending_resubscribe(2, WATCH_NODE_B, 0, Instant::now());
        actor.enqueue_connect_waiter(fabric_id, WATCH_NODE_B, ConnectWaiter::Resubscribe(pr_b));

        assert!(
            actor.pending_resolves.is_empty(),
            "B must resolve in spawn_connect's own settle pass, not park"
        );
        assert_eq!(actor.resolve_base_after, None, "no fallback armed");
        let s = state.lock().unwrap();
        assert_eq!(s.base_opens, 0, "the base-type fallback was never opened");
        assert_eq!(s.subtype_opens, 2, "one watch open + one replay attach");
        assert_eq!(
            s.stops,
            vec![WATCH_REPLAY_HANDLE],
            "only the short-lived replay handle is stopped"
        );
        assert!(
            s.found_polls.contains(&WATCH_REPLAY_HANDLE),
            "the replay handle's found buffer is drained before it is stopped"
        );
        drop(s);
        assert_eq!(actor.resolve_query_fabric, Some(WATCH_SUBTYPE_HANDLE));
        assert_eq!(actor.resolve_query, None);
    }

    /// Expired entry: a cached record older than `SEEN_RECORD_TTL` counts as
    /// absent — the replay attach still happens and the connect resolves off
    /// the refreshed entry.
    #[tokio::test]
    async fn a_connect_behind_a_held_watch_replays_when_the_cached_record_has_expired() {
        let (mut actor, state, _reports, _ctrl) = held_watch_with_b_surfaced();
        let fabric_id = actor.sole_fabric().unwrap().fabric_id;
        let cfid = actor.sole_compressed_fabric_id().unwrap();
        let b_name = operational_instance_name(cfid, WATCH_NODE_B);
        // Built by subtraction because the entry must predate the test by more
        // than the TTL; a host up for under a minute cannot express that, and
        // the absent-entry test above still covers the replay there.
        let Some(expired_at) = Instant::now().checked_sub(SEEN_RECORD_TTL + Duration::from_secs(1))
        else {
            eprintln!("host uptime below SEEN_RECORD_TTL; expired-entry case skipped");
            return;
        };
        actor.record_seen(&[op_record(&b_name)], expired_at, BROWSE_SUBTYPE);

        let (pr_b, _b_reports, _b_ctrl) =
            test_pending_resubscribe(2, WATCH_NODE_B, 0, Instant::now());
        actor.enqueue_connect_waiter(fabric_id, WATCH_NODE_B, ConnectWaiter::Resubscribe(pr_b));

        assert!(actor.pending_resolves.is_empty(), "resolved, not parked");
        let s = state.lock().unwrap();
        assert_eq!(s.base_opens, 0);
        assert_eq!(s.subtype_opens, 2);
        assert_eq!(s.stops, vec![WATCH_REPLAY_HANDLE]);
    }

    /// Fresh entry: a record still inside `SEEN_RECORD_TTL` needs no replay, so
    /// no second handle is attached.
    #[tokio::test]
    async fn a_connect_behind_a_held_watch_with_a_fresh_record_attaches_nothing() {
        let (mut actor, state, _reports, _ctrl) = held_watch_with_b_surfaced();
        let fabric_id = actor.sole_fabric().unwrap().fabric_id;
        let cfid = actor.sole_compressed_fabric_id().unwrap();
        let b_name = operational_instance_name(cfid, WATCH_NODE_B);
        actor.record_seen(&[op_record(&b_name)], Instant::now(), BROWSE_SUBTYPE);

        let (pr_b, _b_reports, _b_ctrl) =
            test_pending_resubscribe(2, WATCH_NODE_B, 0, Instant::now());
        actor.enqueue_connect_waiter(fabric_id, WATCH_NODE_B, ConnectWaiter::Resubscribe(pr_b));

        assert!(actor.pending_resolves.is_empty());
        let s = state.lock().unwrap();
        assert_eq!(s.subtype_opens, 1, "no replay attach for a fresh record");
        assert!(s.stops.is_empty(), "{:?}", s.stops);
    }

    /// Follow-up to F1: the replay never overwrites a fresher cache entry.
    /// Connecting to C (not cached) triggers the replay, which also carries
    /// B's last-surfaced record; B already has a fresh entry from the watch's
    /// own drain (a different port here), and that entry must survive as-is —
    /// same peer, same `seen` stamp.
    #[tokio::test]
    async fn the_replay_leaves_an_already_fresh_entry_alone() {
        const WATCH_NODE_C: u64 = 0x0C;
        let (mut actor, state, _reports, _ctrl) = held_watch_with_b_surfaced();
        let fabric_id = actor.sole_fabric().unwrap().fabric_id;
        let cfid = actor.sole_compressed_fabric_id().unwrap();
        let b_name = operational_instance_name(cfid, WATCH_NODE_B);
        let b_key = Actor::<InMemoryDatagram, WatchDiscovery>::record_key(&b_name);
        let fresh_b = MatterService::new(
            b_name.clone(),
            ServiceKind::Operational,
            vec!["127.0.0.1".parse().unwrap()],
            5599,
            std::collections::HashMap::new(),
        );
        let stamped = Instant::now();
        actor.record_seen(&[fresh_b], stamped, BROWSE_SUBTYPE);

        let (pr_c, _c_reports, _c_ctrl) =
            test_pending_resubscribe(2, WATCH_NODE_C, 0, Instant::now());
        actor.enqueue_connect_waiter(fabric_id, WATCH_NODE_C, ConnectWaiter::Resubscribe(pr_c));

        assert_eq!(
            state.lock().unwrap().stops,
            vec![WATCH_REPLAY_HANDLE],
            "precondition: the replay ran"
        );
        let b = actor.seen_records.get(&b_key).expect("B still cached");
        assert_eq!(b.peer.port(), 5599, "the fresher entry was not overwritten");
        assert_eq!(b.seen, stamped, "and not re-stamped");
        assert_eq!(actor.pending_resolves.len(), 1, "C itself stays parked");
    }

    /// Failed attach: a daemon that refuses the second handle costs nothing but
    /// the replay — the connect parks on the held watch as before, with the
    /// delayed base fallback armed, and nothing is stopped.
    #[tokio::test]
    async fn a_failed_replay_attach_falls_through_to_the_parked_resolve() {
        let (mut actor, state, _reports, _ctrl) = held_watch_with_b_surfaced();
        let fabric_id = actor.sole_fabric().unwrap().fabric_id;
        state.lock().unwrap().fail_subtype_opens = true;

        let (pr_b, _b_reports, _b_ctrl) =
            test_pending_resubscribe(2, WATCH_NODE_B, 0, Instant::now());
        actor.enqueue_connect_waiter(fabric_id, WATCH_NODE_B, ConnectWaiter::Resubscribe(pr_b));

        assert_eq!(actor.pending_resolves.len(), 1, "parked as before");
        assert!(
            actor.resolve_base_after.is_some(),
            "fallback armed as before"
        );
        let s = state.lock().unwrap();
        assert_eq!(s.subtype_opens, 2, "the replay attach was tried");
        assert!(s.stops.is_empty(), "{:?}", s.stops);
        drop(s);
        assert_eq!(actor.resolve_query_fabric, Some(WATCH_SUBTYPE_HANDLE));
    }

    /// Failing opens are retried no more often than `WATCH_OPEN_RETRY`, and a
    /// later success clears the retry.
    #[tokio::test]
    async fn a_failing_watch_open_is_retried_no_more_often_than_watch_open_retry() {
        let (discovery, state) = watch_discovery();
        state.lock().unwrap().fail_opens = true;
        let mut actor = actor_with_one_fabric_using(discovery);
        let (pr, _reports, _ctrl) = test_pending_resubscribe(1, WATCH_NODE_A, 4, far_future());
        actor.resubscribes.push(pr);
        let t0 = Instant::now();
        actor.reconcile_resubscribe_watch(t0);
        assert_eq!(state.lock().unwrap().subtype_opens, 1);
        actor.reconcile_resubscribe_watch(t0 + Duration::from_secs(1));
        actor.reconcile_resubscribe_watch(
            t0 + WATCH_OPEN_RETRY.saturating_sub(Duration::from_millis(1)),
        );
        assert_eq!(
            state.lock().unwrap().subtype_opens,
            1,
            "no retry inside the interval"
        );
        actor.reconcile_resubscribe_watch(t0 + WATCH_OPEN_RETRY);
        assert_eq!(state.lock().unwrap().subtype_opens, 2);

        state.lock().unwrap().fail_opens = false;
        actor.reconcile_resubscribe_watch(t0 + WATCH_OPEN_RETRY * 2);
        assert_eq!(state.lock().unwrap().subtype_opens, 3);
        assert_eq!(actor.resolve_query_fabric, Some(WATCH_SUBTYPE_HANDLE));
        assert!(actor.watch_open_retry_at.is_none());
    }

    /// With only the watch open the loop wakes within ~1 s to drain it; with
    /// nothing pending the deadline is unchanged.
    #[tokio::test]
    async fn the_watch_alone_wakes_the_loop_about_once_a_second() {
        let (discovery, _state) = watch_discovery();
        let mut actor = actor_with_one_fabric_using(discovery);
        assert_eq!(actor.next_timer_deadline(), None, "nothing pending");
        let attempt_at = far_future();
        let (pr, _reports, _ctrl) = test_pending_resubscribe(1, WATCH_NODE_A, 4, attempt_at);
        actor.resubscribes.push(pr);
        assert_eq!(
            actor.next_timer_deadline(),
            Some(attempt_at),
            "no watch yet"
        );
        actor.reconcile_resubscribe_watch(Instant::now());
        actor.drive_pending_resolves();
        let deadline = actor.next_timer_deadline().expect("armed");
        assert!(
            deadline <= Instant::now() + ADVERT_WATCH_POLL_INTERVAL,
            "the watch must be drained about once a second"
        );
    }

    /// A failed-open retry counts toward the deadline only while it is in the
    /// future AND could happen. A past-due or impossible one (no sole fabric)
    /// would spin the overdue guard.
    #[tokio::test]
    async fn a_watch_open_retry_counts_only_while_it_can_still_happen() {
        let (discovery, state) = watch_discovery();
        state.lock().unwrap().fail_opens = true;
        let mut actor = actor_with_one_fabric_using(discovery);
        let attempt_at = far_future();
        let (pr, _reports, _ctrl) = test_pending_resubscribe(1, WATCH_NODE_A, 4, attempt_at);
        actor.resubscribes.push(pr);
        let t0 = Instant::now();
        actor.reconcile_resubscribe_watch(t0);
        assert_eq!(actor.next_timer_deadline(), Some(t0 + WATCH_OPEN_RETRY));

        actor.watch_open_retry_at = Some(just_past());
        assert_eq!(
            actor.next_timer_deadline(),
            Some(attempt_at),
            "past-due never counts"
        );

        actor.watch_open_retry_at = Some(Instant::now() + WATCH_OPEN_RETRY);
        actor.state.fabrics.clear();
        assert_eq!(
            actor.next_timer_deadline(),
            Some(attempt_at),
            "no sole fabric: the retry cannot happen, so it must not wake the loop"
        );
    }

    /// A held watch whose fabric is no longer the sole one is closed (nothing
    /// parked) and reopened for the current fabric next pass; with no sole
    /// fabric at all it stays closed.
    #[tokio::test]
    async fn watch_follows_a_fabric_change() {
        let (discovery, state) = watch_discovery();
        let mut actor = actor_with_one_fabric_using(discovery);
        let (pr, _reports, _ctrl) = test_pending_resubscribe(1, WATCH_NODE_A, 4, far_future());
        actor.resubscribes.push(pr);
        actor.reconcile_resubscribe_watch(Instant::now());
        actor.resolve_query_fabric_cfid = Some([0xEE; 8]); // opened for another fabric

        actor.reconcile_resubscribe_watch(Instant::now());
        assert_eq!(state.lock().unwrap().stops, vec![WATCH_SUBTYPE_HANDLE]);
        assert_eq!(actor.resolve_query_fabric, None);
        actor.reconcile_resubscribe_watch(Instant::now());
        assert_eq!(state.lock().unwrap().subtype_opens, 2, "reopened");
        assert_eq!(
            actor.resolve_query_fabric_cfid,
            Some(actor.sole_compressed_fabric_id().unwrap())
        );

        actor.state.fabrics.clear();
        actor.reconcile_resubscribe_watch(Instant::now());
        actor.reconcile_resubscribe_watch(Instant::now());
        let s = state.lock().unwrap();
        assert_eq!(s.stops.len(), 2, "closed");
        assert_eq!(s.subtype_opens, 2, "and not reopened without a sole fabric");
    }

    /// #113 guard: the watch never opens the subtype browse beside a live
    /// base-type browse; it opens once the base browse is gone.
    #[tokio::test]
    async fn watch_never_opens_the_subtype_beside_a_live_base_browse() {
        let (discovery, state) = watch_discovery();
        state.lock().unwrap().fail_subtype_opens = true;
        let mut actor = actor_with_one_fabric_using(discovery);
        let fabric_id = actor.sole_fabric().unwrap().fabric_id;
        let (queued, _queued_reports, _queued_ctrl) =
            test_pending_resubscribe(1, WATCH_NODE_A, 4, far_future());
        actor.resubscribes.push(queued);
        // B's connect cannot open the subtype, so `spawn_connect` opens the
        // base type at once and parks on it.
        let (connecting, _connecting_reports, _connecting_ctrl) =
            test_pending_resubscribe(2, WATCH_NODE_B, 0, Instant::now());
        actor.enqueue_connect_waiter(
            fabric_id,
            WATCH_NODE_B,
            ConnectWaiter::Resubscribe(connecting),
        );
        assert_eq!(actor.resolve_query, Some(WATCH_BASE_HANDLE));
        assert_eq!(actor.resolve_query_fabric, None);

        // The daemon would now accept a subtype browse — but the base one is live.
        state.lock().unwrap().fail_subtype_opens = false;
        actor.reconcile_resubscribe_watch(Instant::now());
        assert_eq!(
            state.lock().unwrap().subtype_opens,
            1,
            "only spawn_connect's failed try"
        );
        assert_eq!(actor.resolve_query_fabric, None);
        assert!(actor.watch_open_retry_at.is_none(), "deferred, not failed");

        // B's resolve ends; the base browse goes; the watch opens.
        actor.cancel_pending_resolve(WATCH_NODE_B);
        assert_eq!(actor.resolve_query, None);
        actor.reconcile_resubscribe_watch(Instant::now());
        assert_eq!(state.lock().unwrap().subtype_opens, 2);
        assert_eq!(actor.resolve_query_fabric, Some(WATCH_SUBTYPE_HANDLE));
    }

    /// A registered session for route-eviction tests (`sessions.get` must find it).
    fn register_test_session<D: Discovery>(actor: &mut Actor<InMemoryDatagram, D>) -> SessionId {
        use matter_crypto::pase::PaseSessionKeys;
        let keys = PaseSessionKeys {
            ke: [0u8; 16],
            i2r_key: [1u8; 16],
            r2i_key: [2u8; 16],
            attestation_key: [3u8; 16],
        };
        actor.sessions.register_pase(
            keys,
            SessionRole::Initiator,
            1,
            matter_transport::PeerHint::default(),
        )
    }

    /// `(retry_count, attempt_at)` of the queued entry for `sub_id`.
    fn queued_state<D: Discovery>(
        actor: &Actor<InMemoryDatagram, D>,
        sub_id: u64,
    ) -> (u32, Instant) {
        let pr = actor
            .resubscribes
            .iter()
            .find(|pr| pr.sub_id == SubId(sub_id))
            .expect("queued entry");
        (pr.retry_count, pr.attempt_at)
    }

    /// The backoff of an attempt already on the wire is reset, and nothing else
    /// happens — no queued copy, no second request.
    #[tokio::test]
    async fn a_pull_resets_an_in_flight_attempt_without_starting_another() {
        let mut actor = actor_with_one_fabric();
        let (pr, _reports, _ctrl) = test_pending_resubscribe(1, 0x42, 7, Instant::now());
        seed_inflight_resubscribe(&mut actor, (SessionId(7), 0x30), pr, far_future());
        assert_eq!(
            actor.trigger_resubscribe(0x42, TriggerSource::Advert, Instant::now()),
            1
        );
        match &actor.pending[&(SessionId(7), 0x30)].reply {
            PendingReply::Subscribe { retry_count, .. } => assert_eq!(*retry_count, 0),
            _ => panic!("still the same in-flight Subscribe"),
        }
        assert_eq!(actor.pending.len(), 1, "no second request");
        assert!(actor.resubscribes.is_empty(), "no queued copy");
        assert!(actor.pending_connects.is_empty(), "no connect");
        actor.assert_pulled_at_within_episodes();
    }

    /// Same for an attempt parked behind a connect — and the reset is what
    /// makes its failure land on the short step.
    #[tokio::test]
    async fn a_pull_resets_a_connecting_attempt_without_starting_another() {
        let mut actor = actor_with_one_fabric();
        let (pr, _reports, _ctrl) = test_pending_resubscribe(1, 0x42, 7, Instant::now());
        actor
            .pending_connects
            .insert(0x42, vec![ConnectWaiter::Resubscribe(pr)]);
        assert_eq!(
            actor.trigger_resubscribe(0x42, TriggerSource::Advert, Instant::now()),
            1
        );
        let ConnectWaiter::Resubscribe(waiting) = &actor.pending_connects[&0x42][0] else {
            panic!("still the same waiter");
        };
        assert_eq!(waiting.retry_count, 0);
        assert_eq!(actor.pending_connects[&0x42].len(), 1);
        assert!(actor.resubscribes.is_empty() && actor.pending.is_empty());

        actor.fail_connect_waiters(0x42, &Error::Operational("unreachable".into()));
        let (retry, at) = queued_state(&actor, 1);
        assert_eq!(retry, 1);
        assert!(
            at <= Instant::now() + Duration::from_secs(10),
            "fibonacci(1): 3-10 s"
        );
    }

    /// The cooldown is on the actor, so it survives `on_pending_timeout`
    /// rebuilding the `PendingResubscribe`.
    #[tokio::test]
    async fn the_advert_cooldown_survives_a_failed_attempt() {
        let mut actor = actor_with_one_fabric();
        let (pr, _reports, _ctrl) = test_pending_resubscribe(1, 0x42, 5, far_future());
        actor.resubscribes.push(pr);
        assert_eq!(
            actor.trigger_resubscribe(0x42, TriggerSource::Advert, Instant::now()),
            1
        );

        let pr = actor.resubscribes.pop().unwrap();
        seed_inflight_resubscribe(&mut actor, (SessionId(7), 0x40), pr, far_future());
        actor
            .on_pending_timeout(SessionId(7), 0x40, SubscribeFailure::MrpExpired)
            .await;
        assert_eq!(queued_state(&actor, 1).0, 1);

        assert_eq!(
            actor.trigger_resubscribe(0x42, TriggerSource::Advert, Instant::now()),
            0,
            "inside the 30 s cooldown"
        );
        assert_eq!(queued_state(&actor, 1).0, 1);

        let stale = Instant::now()
            .checked_sub(ADVERT_PULL_COOLDOWN + Duration::from_secs(1))
            .expect("process uptime exceeds the cooldown");
        actor.resubscribe_pulled_at.insert(SubId(1), stale);
        assert_eq!(
            actor.trigger_resubscribe(0x42, TriggerSource::Advert, Instant::now()),
            1
        );
        assert_eq!(queued_state(&actor, 1).0, 0);
        actor.assert_pulled_at_within_episodes();
    }

    /// Only eligible subscriptions of the node move, and the count says exactly
    /// how many. The API then ignores only the cooldown.
    #[tokio::test]
    async fn a_pull_counts_only_eligible_subscriptions_of_the_node() {
        let mut actor = actor_with_one_fabric();
        let now = Instant::now();
        let far = far_future();
        let past = just_past();
        let (eligible, _eligible_reports, _eligible_ctrl) =
            test_pending_resubscribe(1, 0x42, 6, far);
        let (due, _due_reports, _due_ctrl) = test_pending_resubscribe(2, 0x42, 6, past);
        let (cooling, _cooling_reports, _cooling_ctrl) = test_pending_resubscribe(3, 0x42, 6, far);
        let (gone, gone_reports, gone_ctrl) = test_pending_resubscribe(4, 0x42, 6, far);
        drop(gone_reports);
        drop(gone_ctrl);
        let (elsewhere, _elsewhere_reports, _elsewhere_ctrl) =
            test_pending_resubscribe(5, 0x43, 6, far);
        actor
            .resubscribes
            .extend([eligible, due, cooling, gone, elsewhere]);
        actor.resubscribe_pulled_at.insert(SubId(3), now);

        assert_eq!(
            actor.trigger_resubscribe(0x42, TriggerSource::Advert, now),
            1
        );
        assert_eq!(queued_state(&actor, 1), (0, now));
        // Already due: it fires this pass anyway, so it is neither moved nor
        // counted nor stamped — but its backoff IS reset (chip/Apple reset
        // unconditionally), so a failure of that attempt retries on step 1.
        assert_eq!(
            queued_state(&actor, 2),
            (0, past),
            "already due: backoff reset, attempt time unchanged"
        );
        assert!(
            !actor.resubscribe_pulled_at.contains_key(&SubId(2)),
            "already due: not counted, so no cooldown stamp"
        );
        assert_eq!(queued_state(&actor, 3), (6, far), "cooldown");
        assert_eq!(queued_state(&actor, 4), (6, far), "consumer gone");
        assert_eq!(queued_state(&actor, 5), (6, far), "another node");

        assert_eq!(actor.trigger_resubscribe(0x42, TriggerSource::Api, now), 1);
        assert_eq!(
            queued_state(&actor, 3),
            (0, now),
            "the API ignores the cooldown"
        );
        assert_eq!(queued_state(&actor, 4), (6, far), "but not a dead consumer");
        actor.assert_pulled_at_within_episodes();
    }

    /// A pull that moves a queued entry drops the idle cached route, never the
    /// session itself.
    #[tokio::test]
    async fn a_pull_evicts_an_idle_cached_route_but_never_the_session() {
        let mut actor = actor_with_one_fabric();
        let fabric_id = actor.sole_fabric().unwrap().fabric_id;
        let sid = register_test_session(&mut actor);
        actor.cache.insert(
            (fabric_id, 0x42),
            CachedSession {
                session_id: sid,
                peer: "127.0.0.1:5540".parse().unwrap(),
            },
        );
        let (pr, _reports, _ctrl) = test_pending_resubscribe(1, 0x42, 5, far_future());
        actor.resubscribes.push(pr);
        assert_eq!(
            actor.trigger_resubscribe(0x42, TriggerSource::Api, Instant::now()),
            1
        );
        assert!(
            !actor.cache.contains_key(&(fabric_id, 0x42)),
            "route dropped"
        );
        assert!(
            actor.sessions.get(sid).is_some(),
            "the session is left alone"
        );
    }

